package main

import (
	"image"
	"math"
)

// Lanczos3-based separable resampler. The horizontal pass writes into a
// transposed temporary buffer, the second pass filters that buffer again and
// produces the final (non transposed) image.

func sincF(x float64) float64 {
	x = math.Abs(x) * math.Pi
	if x >= 1.220703e-4 {
		return math.Sin(x) / x
	}
	return 1
}

func lanczos3Kernel(in float64) float64 {
	if in > -3 && in < 3 {
		return sincF(in) * sincF(in*0.3333333333333333)
	}
	return 0
}

const kernelTaps = 6

func scaleFactors(width, height uint, oldW, oldH float64) (sx, sy float64) {
	if width == 0 {
		if height == 0 {
			sx, sy = 1.0, 1.0
		} else {
			sy = oldH / float64(height)
			sx = sy
		}
	} else {
		sx = oldW / float64(width)
		if height == 0 {
			sy = sx
		} else {
			sy = oldH / float64(height)
		}
	}
	return
}

func weights8(dy, taps int, scale float64) ([]int16, []int, int) {
	n := taps * int(math.Max(math.Ceil(scale), 1))
	factor := math.Min(1./scale, 1)
	coeffs := make([]int16, dy*n)
	start := make([]int, dy)
	for y := 0; y < dy; y++ {
		ix := scale*(float64(y)+0.5) - 0.5
		start[y] = int(ix) - n/2 + 1
		ix -= float64(start[y])
		for i := 0; i < n; i++ {
			v := (ix - float64(i)) * factor
			coeffs[y*n+i] = int16(lanczos3Kernel(v) * 256)
		}
	}
	return coeffs, start, n
}

func weights16(dy, taps int, scale float64) ([]int32, []int, int) {
	n := taps * int(math.Max(math.Ceil(scale), 1))
	factor := math.Min(1./scale, 1)
	coeffs := make([]int32, dy*n)
	start := make([]int, dy)
	for y := 0; y < dy; y++ {
		ix := scale*(float64(y)+0.5) - 0.5
		start[y] = int(ix) - n/2 + 1
		ix -= float64(start[y])
		for i := 0; i < n; i++ {
			v := (ix - float64(i)) * factor
			coeffs[y*n+i] = int32(lanczos3Kernel(v) * 65536)
		}
	}
	return coeffs, start, n
}

func clamp8(v int32) uint8 {
	if uint32(v) < 256 {
		return uint8(v)
	}
	if v > 255 {
		return 255
	}
	return 0
}

func clamp16(v int64) uint16 {
	if uint64(v) < 65536 {
		return uint16(v)
	}
	if v > 65535 {
		return 65535
	}
	return 0
}

// resizeImage scales img to width x height.
func resizeImage(width, height uint, img image.Image) image.Image {
	b := img.Bounds()
	sx, sy := scaleFactors(width, height, float64(b.Dx()), float64(b.Dy()))
	if width == 0 {
		width = uint(0.7 + float64(b.Dx())/sx)
	}
	if height == 0 {
		height = uint(0.7 + float64(b.Dy())/sy)
	}
	if int(width) == b.Dx() && int(height) == b.Dy() {
		return img
	}
	if b.Dx() <= 0 || b.Dy() <= 0 {
		return img
	}
	w, h := int(width), int(height)

	switch in := img.(type) {
	case *image.RGBA:
		temp := image.NewRGBA(image.Rect(0, 0, b.Dy(), w))
		res := image.NewRGBA(image.Rect(0, 0, w, h))
		c, o, n := weights8(w, kernelTaps, sx)
		passRGBA(in.Pix, in.Stride, b.Dx(), temp, c, o, n, false)
		c, o, n = weights8(h, kernelTaps, sy)
		passRGBA(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n, false)
		return res
	case *image.NRGBA:
		temp := image.NewRGBA(image.Rect(0, 0, b.Dy(), w))
		res := image.NewRGBA(image.Rect(0, 0, w, h))
		c, o, n := weights8(w, kernelTaps, sx)
		passRGBA(in.Pix, in.Stride, b.Dx(), temp, c, o, n, true)
		c, o, n = weights8(h, kernelTaps, sy)
		passRGBA(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n, false)
		return res
	case *image.YCbCr:
		src := yccFromYCbCr(in)
		temp := make([]uint8, 3*b.Dy()*w)
		c, o, n := weights8(w, kernelTaps, sx)
		passYCC(src, 3*b.Dx(), b.Dx(), temp, 3*b.Dy(), b.Dy(), w, c, o, n)
		out := make([]uint8, 3*w*h)
		c, o, n = weights8(h, kernelTaps, sy)
		passYCC(temp, 3*b.Dy(), b.Dy(), out, 3*w, w, h, c, o, n)
		res := image.NewYCbCr(image.Rect(0, 0, w, h), image.YCbCrSubsampleRatio444)
		off := 0
		for y := 0; y < h; y++ {
			for x := 0; x < w; x++ {
				res.Y[y*res.YStride+x] = out[off]
				res.Cb[y*res.CStride+x] = out[off+1]
				res.Cr[y*res.CStride+x] = out[off+2]
				off += 3
			}
		}
		return res
	case *image.RGBA64:
		temp := image.NewRGBA64(image.Rect(0, 0, b.Dy(), w))
		res := image.NewRGBA64(image.Rect(0, 0, w, h))
		c, o, n := weights16(w, kernelTaps, sx)
		passRGBA64(in.Pix, in.Stride, b.Dx(), temp, c, o, n, false)
		c, o, n = weights16(h, kernelTaps, sy)
		passRGBA64(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n, false)
		return res
	case *image.NRGBA64:
		temp := image.NewRGBA64(image.Rect(0, 0, b.Dy(), w))
		res := image.NewRGBA64(image.Rect(0, 0, w, h))
		c, o, n := weights16(w, kernelTaps, sx)
		passRGBA64(in.Pix, in.Stride, b.Dx(), temp, c, o, n, true)
		c, o, n = weights16(h, kernelTaps, sy)
		passRGBA64(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n, false)
		return res
	case *image.Gray:
		temp := image.NewGray(image.Rect(0, 0, b.Dy(), w))
		res := image.NewGray(image.Rect(0, 0, w, h))
		c, o, n := weights8(w, kernelTaps, sx)
		passGray(in.Pix, in.Stride, b.Dx(), temp, c, o, n)
		c, o, n = weights8(h, kernelTaps, sy)
		passGray(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n)
		return res
	case *image.Gray16:
		temp := image.NewGray16(image.Rect(0, 0, b.Dy(), w))
		res := image.NewGray16(image.Rect(0, 0, w, h))
		c, o, n := weights16(w, kernelTaps, sx)
		passGray16(in.Pix, in.Stride, b.Dx(), temp, c, o, n)
		c, o, n = weights16(h, kernelTaps, sy)
		passGray16(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n)
		return res
	default:
		temp := image.NewRGBA64(image.Rect(0, 0, b.Dy(), w))
		res := image.NewRGBA64(image.Rect(0, 0, w, h))
		c, o, n := weights16(w, kernelTaps, sx)
		passGeneric(img, temp, c, o, n)
		c, o, n = weights16(h, kernelTaps, sy)
		passRGBA64(temp.Pix, temp.Stride, temp.Rect.Dx(), res, c, o, n, false)
		return res
	}
}

// passRGBA: out is transposed relative to the source rows. For each output
// pixel (x,y): source row x, filtered along columns using weights of y.
func passRGBA(pix []uint8, stride, srcW int, out *image.RGBA, coeffs []int16, offset []int, n int, premul bool) {
	maxX := srcW - 1
	ob := out.Rect
	for x := ob.Min.X; x < ob.Max.X; x++ {
		row := pix[x*stride:]
		for y := ob.Min.Y; y < ob.Max.Y; y++ {
			var acc [4]int32
			var sum int32
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = 4 * maxX
				default:
					xi *= 4
				}
				if premul {
					a := int32(row[xi+3])
					r := int32(row[xi+0]) * a
					r /= 0xff
					g := int32(row[xi+1]) * a
					g /= 0xff
					bb := int32(row[xi+2]) * a
					bb /= 0xff
					acc[0] += int32(cf) * r
					acc[1] += int32(cf) * g
					acc[2] += int32(cf) * bb
					acc[3] += int32(cf) * a
				} else {
					acc[0] += int32(cf) * int32(row[xi+0])
					acc[1] += int32(cf) * int32(row[xi+1])
					acc[2] += int32(cf) * int32(row[xi+2])
					acc[3] += int32(cf) * int32(row[xi+3])
				}
				sum += int32(cf)
			}
			xo := (y-ob.Min.Y)*out.Stride + (x-ob.Min.X)*4
			out.Pix[xo+0] = clamp8(acc[0] / sum)
			out.Pix[xo+1] = clamp8(acc[1] / sum)
			out.Pix[xo+2] = clamp8(acc[2] / sum)
			out.Pix[xo+3] = clamp8(acc[3] / sum)
		}
	}
}

func passRGBA64(pix []uint8, stride, srcW int, out *image.RGBA64, coeffs []int32, offset []int, n int, premul bool) {
	maxX := srcW - 1
	ob := out.Rect
	for x := ob.Min.X; x < ob.Max.X; x++ {
		row := pix[x*stride:]
		for y := ob.Min.Y; y < ob.Max.Y; y++ {
			var acc [4]int64
			var sum int64
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = 8 * maxX
				default:
					xi *= 8
				}
				if premul {
					a := int64(uint16(row[xi+6])<<8 | uint16(row[xi+7]))
					r := int64(uint16(row[xi+0])<<8|uint16(row[xi+1])) * a
					r /= 0xffff
					g := int64(uint16(row[xi+2])<<8|uint16(row[xi+3])) * a
					g /= 0xffff
					bb := int64(uint16(row[xi+4])<<8|uint16(row[xi+5])) * a
					bb /= 0xffff
					acc[0] += int64(cf) * r
					acc[1] += int64(cf) * g
					acc[2] += int64(cf) * bb
					acc[3] += int64(cf) * a
				} else {
					acc[0] += int64(cf) * (int64(row[xi+0])<<8 | int64(row[xi+1]))
					acc[1] += int64(cf) * (int64(row[xi+2])<<8 | int64(row[xi+3]))
					acc[2] += int64(cf) * (int64(row[xi+4])<<8 | int64(row[xi+5]))
					acc[3] += int64(cf) * (int64(row[xi+6])<<8 | int64(row[xi+7]))
				}
				sum += int64(cf)
			}
			xo := (y-ob.Min.Y)*out.Stride + (x-ob.Min.X)*8
			for k := 0; k < 4; k++ {
				v := clamp16(acc[k] / sum)
				out.Pix[xo+2*k] = uint8(v >> 8)
				out.Pix[xo+2*k+1] = uint8(v)
			}
		}
	}
}

func passGray(pix []uint8, stride, srcW int, out *image.Gray, coeffs []int16, offset []int, n int) {
	maxX := srcW - 1
	ob := out.Rect
	for x := ob.Min.X; x < ob.Max.X; x++ {
		row := pix[(x-ob.Min.X)*stride:]
		for y := ob.Min.Y; y < ob.Max.Y; y++ {
			var g, sum int32
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = maxX
				}
				g += int32(cf) * int32(row[xi])
				sum += int32(cf)
			}
			out.Pix[(y-ob.Min.Y)*out.Stride+(x-ob.Min.X)] = clamp8(g / sum)
		}
	}
}

func passGray16(pix []uint8, stride, srcW int, out *image.Gray16, coeffs []int32, offset []int, n int) {
	maxX := srcW - 1
	ob := out.Rect
	for x := ob.Min.X; x < ob.Max.X; x++ {
		row := pix[x*stride:]
		for y := ob.Min.Y; y < ob.Max.Y; y++ {
			var g, sum int64
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = 2 * maxX
				default:
					xi *= 2
				}
				g += int64(cf) * (int64(row[xi+0])<<8 | int64(row[xi+1]))
				sum += int64(cf)
			}
			o := (y-ob.Min.Y)*out.Stride + (x-ob.Min.X)*2
			v := clamp16(g / sum)
			out.Pix[o+0] = uint8(v >> 8)
			out.Pix[o+1] = uint8(v)
		}
	}
}

func passGeneric(in image.Image, out *image.RGBA64, coeffs []int32, offset []int, n int) {
	ib := in.Bounds()
	maxX := ib.Dx() - 1
	ob := out.Rect
	for x := ob.Min.X; x < ob.Max.X; x++ {
		for y := ob.Min.Y; y < ob.Max.Y; y++ {
			var acc [4]int64
			var sum int64
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = maxX
				}
				r, g, b, a := in.At(xi+ib.Min.X, x+ib.Min.Y).RGBA()
				acc[0] += int64(cf) * int64(r)
				acc[1] += int64(cf) * int64(g)
				acc[2] += int64(cf) * int64(b)
				acc[3] += int64(cf) * int64(a)
				sum += int64(cf)
			}
			xo := (y-ob.Min.Y)*out.Stride + (x-ob.Min.X)*8
			for k := 0; k < 4; k++ {
				v := clamp16(acc[k] / sum)
				out.Pix[xo+2*k] = uint8(v >> 8)
				out.Pix[xo+2*k+1] = uint8(v)
			}
		}
	}
}

// yccFromYCbCr builds an interleaved, fully sampled Y/Cb/Cr buffer.
func yccFromYCbCr(in *image.YCbCr) []uint8 {
	w, h := in.Rect.Dx(), in.Rect.Dy()
	pix := make([]uint8, 3*w*h)
	off := 0
	for y := 0; y < h; y++ {
		yy := y * in.YStride
		var cy int
		switch in.SubsampleRatio {
		case image.YCbCrSubsampleRatio420, image.YCbCrSubsampleRatio440:
			cy = (y / 2) * in.CStride
		case image.YCbCrSubsampleRatio410:
			cy = (y / 2) * in.CStride
		default:
			cy = y * in.CStride
		}
		for x := 0; x < w; x++ {
			var ci int
			switch in.SubsampleRatio {
			case image.YCbCrSubsampleRatio422, image.YCbCrSubsampleRatio420:
				ci = cy + x/2
			case image.YCbCrSubsampleRatio411, image.YCbCrSubsampleRatio410:
				ci = cy + x/4
			default:
				ci = cy + x
			}
			pix[off+0] = in.Y[yy+x]
			pix[off+1] = in.Cb[ci]
			pix[off+2] = in.Cr[ci]
			off += 3
		}
	}
	return pix
}

func passYCC(pix []uint8, stride, srcW int, out []uint8, outStride, outW, outH int, coeffs []int16, offset []int, n int) {
	maxX := srcW - 1
	for x := 0; x < outW; x++ {
		row := pix[x*stride:]
		for y := 0; y < outH; y++ {
			var p [3]int32
			var sum int32
			start := offset[y]
			ci := y * n
			for i := 0; i < n; i++ {
				cf := coeffs[ci+i]
				if cf == 0 {
					continue
				}
				xi := start + i
				switch {
				case xi < 0:
					xi = 0
				case xi >= maxX:
					xi = 3 * maxX
				default:
					xi *= 3
				}
				p[0] += int32(cf) * int32(row[xi+0])
				p[1] += int32(cf) * int32(row[xi+1])
				p[2] += int32(cf) * int32(row[xi+2])
				sum += int32(cf)
			}
			xo := y*outStride + x*3
			out[xo+0] = clamp8(p[0] / sum)
			out[xo+1] = clamp8(p[1] / sum)
			out[xo+2] = clamp8(p[2] / sum)
		}
	}
}
