	"math"
)

type iw struct {
	index  int
	weight float64
}

func imgSinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

var imgSupport = 3.0
var imgKernel = func(x float64) float64 {
	x = math.Abs(x)
	if x < 3.0 {
		return imgSinc(x) * imgSinc(x/3.0)
	}
	return 0
}

func precomp(dstSize, srcSize int) [][]iw {
	du := float64(srcSize) / float64(dstSize)
	scale := du
	if scale < 1.0 {
		scale = 1.0
	}
	ru := math.Ceil(scale * imgSupport)
	out := make([][]iw, dstSize)
	for v := 0; v < dstSize; v++ {
		fu := (float64(v)+0.5)*du - 0.5
		begin := int(math.Ceil(fu - ru))
		if begin < 0 {
			begin = 0
		}
		end := int(math.Floor(fu + ru))
		if end > srcSize-1 {
			end = srcSize - 1
		}
		var sum float64
		var tmp []iw
		for u := begin; u <= end; u++ {
			w := imgKernel((float64(u) - fu) / scale)
			if w != 0 {
				sum += w
				tmp = append(tmp, iw{u, w})
			}
		}
		if sum != 0 {
			for i := range tmp {
				tmp[i].weight /= sum
			}
		}
		out[v] = tmp
	}
	return out
}

func clampF(x float64) uint8 {
	v := int64(x + 0.5)
	if v > 255 {
		return 255
	}
	if v > 0 {
		return uint8(v)
	}
	return 0
}

func toNRGBA(img image.Image) *image.NRGBA {
	b := img.Bounds()
	n := image.NewNRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	draw.Draw(n, n.Rect, img, b.Min, draw.Src)
	return n
}

func imgResizeH(src *image.NRGBA, width int) *image.NRGBA {
	sw, sh := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, width, sh))
	ws := precomp(width, sw)
	for y := 0; y < sh; y++ {
		line := src.Pix[y*src.Stride:]
		for i := range ws {
			var r, g, b, a float64
			for _, w := range ws[i] {
				s := line[w.index*4:]
				aw := float64(s[3]) * w.weight
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				ai := 1 / a
				d := dst.Pix[y*dst.Stride+i*4:]
				d[0] = clampF(r * ai)
				d[1] = clampF(g * ai)
				d[2] = clampF(b * ai)
				d[3] = clampF(a)
			}
		}
	}
	return dst
}

func imgResizeV(src *image.NRGBA, height int) *image.NRGBA {
	sw, sh := src.Rect.Dx(), src.Rect.Dy()
	dst := image.NewNRGBA(image.Rect(0, 0, sw, height))
	ws := precomp(height, sh)
	for x := 0; x < sw; x++ {
		for i := range ws {
			var r, g, b, a float64
			for _, w := range ws[i] {
				s := src.Pix[w.index*src.Stride+x*4:]
				aw := float64(s[3]) * w.weight
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				ai := 1 / a
				d := dst.Pix[i*dst.Stride+x*4:]
				d[0] = clampF(r * ai)
				d[1] = clampF(g * ai)
				d[2] = clampF(b * ai)
				d[3] = clampF(a)
			}
		}
	}
	return dst
}

func imagingResize(img image.Image, w, h int) image.Image {
	n := toNRGBA(img)
	sw, sh := n.Rect.Dx(), n.Rect.Dy()
	if sw != w && sh != h {
		return imgResizeV(imgResizeH(n, w), h)
	}
	if sw != w {
		return imgResizeH(n, w)
	}
	if sh != h {
		return imgResizeV(n, h)
	}
	return n
}
