// Separable Lanczos (a=3) resampling producing non-premultiplied 8-bit RGBA.
// Pixels are first normalised to 8-bit NRGBA by the scanner below; each pass
// weights colour channels by alpha and accumulates in float64.

type pixWeight struct {
	index  int
	weight float64
}

func sincPi(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

func lanczosKernel(x float64) float64 {
	x = math.Abs(x)
	if x < 3.0 {
		return sincPi(x) * sincPi(x/3.0)
	}
	return 0
}

const lanczosSupport = 3.0

func buildWeights(dstSize, srcSize int) [][]pixWeight {
	du := float64(srcSize) / float64(dstSize)
	scale := du
	if scale < 1.0 {
		scale = 1.0
	}
	ru := math.Ceil(scale * lanczosSupport)

	out := make([][]pixWeight, dstSize)
	tmp := make([]pixWeight, 0, dstSize*int(ru+2)*2)
	for v := 0; v < dstSize; v++ {
		fu := (float64(v)+0.5)*du - 0.5
		begin := int(math.Ceil(fu - ru))
		if begin < 0 {
			begin = 0
		}
		end := int(math.Floor(fu + ru))
		if end > srcSize-1 {
			end = srcSize - 1
		}
		var sum float64
		for u := begin; u <= end; u++ {
			w := lanczosKernel((float64(u) - fu) / scale)
			if w != 0 {
				sum += w
				tmp = append(tmp, pixWeight{index: u, weight: w})
			}
		}
		if sum != 0 {
			for i := range tmp {
				tmp[i].weight /= sum
			}
		}
		out[v] = tmp
		tmp = tmp[len(tmp):]
	}
	return out
}

func clampRound(x float64) uint8 {
	v := int64(x + 0.5)
	if v > 255 {
		return 255
	}
	if v > 0 {
		return uint8(v)
	}
	return 0
}

