type pixelScanner struct {
	img     image.Image
	w, h    int
	palette []color.NRGBA
}

func newPixelScanner(img image.Image) *pixelScanner {
	s := &pixelScanner{img: img, w: img.Bounds().Dx(), h: img.Bounds().Dy()}
	if p, ok := img.(*image.Paletted); ok {
		s.palette = make([]color.NRGBA, len(p.Palette))
		for i := range p.Palette {
			s.palette[i] = color.NRGBAModel.Convert(p.Palette[i]).(color.NRGBA)
		}
	}
	return s
}

func (s *pixelScanner) scan(x1, y1, x2, y2 int, dst []uint8) {
	switch img := s.img.(type) {
	case *image.NRGBA:
		size := (x2 - x1) * 4
		j := 0
		i := y1*img.Stride + x1*4
		for y := y1; y < y2; y++ {
			copy(dst[j:j+size], img.Pix[i:i+size])
			j += size
			i += img.Stride
		}
	case *image.NRGBA64:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1*8
			for x := x1; x < x2; x++ {
				p := img.Pix[i : i+8]
				dst[j+0] = p[0]
				dst[j+1] = p[2]
				dst[j+2] = p[4]
				dst[j+3] = p[6]
				j += 4
				i += 8
			}
		}
	case *image.RGBA:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1*4
			for x := x1; x < x2; x++ {
				a := img.Pix[i+3]
				switch a {
				case 0:
					dst[j+0], dst[j+1], dst[j+2] = 0, 0, 0
				case 0xff:
					dst[j+0] = img.Pix[i+0]
					dst[j+1] = img.Pix[i+1]
					dst[j+2] = img.Pix[i+2]
				default:
					a16 := uint16(a)
					dst[j+0] = uint8(uint16(img.Pix[i+0]) * 0xff / a16)
					dst[j+1] = uint8(uint16(img.Pix[i+1]) * 0xff / a16)
					dst[j+2] = uint8(uint16(img.Pix[i+2]) * 0xff / a16)
				}
				dst[j+3] = a
				j += 4
				i += 4
			}
		}
