				switch a {
				case 0:
					dst[j+0], dst[j+1], dst[j+2] = 0, 0, 0
				case 0xff:
					dst[j+0] = p[0]
					dst[j+1] = p[2]
					dst[j+2] = p[4]
				default:
					r32 := uint32(p[0])<<8 | uint32(p[1])
					g32 := uint32(p[2])<<8 | uint32(p[3])
					b32 := uint32(p[4])<<8 | uint32(p[5])
					a32 := uint32(p[6])<<8 | uint32(p[7])
					dst[j+0] = uint8((r32 * 0xffff / a32) >> 8)
					dst[j+1] = uint8((g32 * 0xffff / a32) >> 8)
					dst[j+2] = uint8((b32 * 0xffff / a32) >> 8)
				}
				dst[j+3] = a
				j += 4
				i += 8
			}
		}
