					dst[j+0], dst[j+1], dst[j+2] = 0, 0, 0
				case 0xff:
					dst[j+0] = img.Pix[i+0]
					dst[j+1] = img.Pix[i+1]
					dst[j+2] = img.Pix[i+2]
				default:
					a16 := uint16(a)
					dst[j+0] = uint8(uint16(img.Pix[i+0]) * 0xff / a16)
					dst[j+1] = uint8(uint16(img.Pix[i+1]) * 0xff / a16)
					dst[j+2] = uint8(uint16(img.Pix[i+2]) * 0xff / a16)
				}
				dst[j+3] = a
				j += 4
				i += 4
			}
		}
	case *image.RGBA64:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1*8
			for x := x1; x < x2; x++ {
				p := img.Pix[i : i+8]
				a := p[6]
				switch a {
				case 0:
					dst[j+0], dst[j+1], dst[j+2] = 0, 0, 0
				case 0xff:
					dst[j+0] = p[0]
					dst[j+1] = p[2]
					dst[j+2] = p[4]
				default:
					r32 := uint32(p[0])<<8 | uint32(p[1])
					g32 := uint32(p[2])<<8 | uint32(p[3])
					b32 := uint32(p[4])<<8 | uint32(p[5])
					a32 := uint32(p[6])<<8 | uint32(p[7])
					dst[j+0] = uint8((r32 * 0xffff / a32) >> 8)
					dst[j+1] = uint8((g32 * 0xffff / a32) >> 8)
					dst[j+2] = uint8((b32 * 0xffff / a32) >> 8)
				}
				dst[j+3] = a
				j += 4
				i += 8
			}
		}
	case *image.Gray:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1
			for x := x1; x < x2; x++ {
				c := img.Pix[i]
				dst[j+0], dst[j+1], dst[j+2], dst[j+3] = c, c, c, 0xff
				j += 4
				i++
			}
		}
	case *image.Gray16:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1*2
			for x := x1; x < x2; x++ {
				c := img.Pix[i]
				dst[j+0], dst[j+1], dst[j+2], dst[j+3] = c, c, c, 0xff
				j += 4
				i += 2
			}
		}
	case *image.YCbCr:
		j := 0
		x1 += img.Rect.Min.X
		x2 += img.Rect.Min.X
		y1 += img.Rect.Min.Y
		y2 += img.Rect.Min.Y
		hy := img.Rect.Min.Y / 2
		hx := img.Rect.Min.X / 2
		for y := y1; y < y2; y++ {
			iy := (y-img.Rect.Min.Y)*img.YStride + (x1 - img.Rect.Min.X)
			var yBase int
			switch img.SubsampleRatio {
			case image.YCbCrSubsampleRatio444, image.YCbCrSubsampleRatio422:
				yBase = (y - img.Rect.Min.Y) * img.CStride
			case image.YCbCrSubsampleRatio420, image.YCbCrSubsampleRatio440:
				yBase = (y/2 - hy) * img.CStride
			}
			for x := x1; x < x2; x++ {
				var ic int
				switch img.SubsampleRatio {
				case image.YCbCrSubsampleRatio444, image.YCbCrSubsampleRatio440:
					ic = yBase + (x - img.Rect.Min.X)
				case image.YCbCrSubsampleRatio422, image.YCbCrSubsampleRatio420:
					ic = yBase + (x/2 - hx)
				default:
					ic = img.COffset(x, y)
				}
				r, g, b := color.YCbCrToRGB(img.Y[iy], img.Cb[ic], img.Cr[ic])
				dst[j+0], dst[j+1], dst[j+2], dst[j+3] = r, g, b, 0xff
				iy++
				j += 4
			}
		}
	case *image.Paletted:
		j := 0
		for y := y1; y < y2; y++ {
			i := y*img.Stride + x1
			for x := x1; x < x2; x++ {
				c := s.palette[img.Pix[i]]
				dst[j+0], dst[j+1], dst[j+2], dst[j+3] = c.R, c.G, c.B, c.A
				j += 4
				i++
			}
		}
	default:
		j := 0
		b := s.img.Bounds()
		x1 += b.Min.X
		x2 += b.Min.X
		y1 += b.Min.Y
		y2 += b.Min.Y
		for y := y1; y < y2; y++ {
			for x := x1; x < x2; x++ {
				r16, g16, b16, a16 := s.img.At(x, y).RGBA()
				switch a16 {
				case 0xffff:
					dst[j+0] = uint8(r16 >> 8)
					dst[j+1] = uint8(g16 >> 8)
					dst[j+2] = uint8(b16 >> 8)
					dst[j+3] = 0xff
				case 0:
					dst[j+0], dst[j+1], dst[j+2], dst[j+3] = 0, 0, 0, 0
				default:
					dst[j+0] = uint8(((r16 * 0xffff) / a16) >> 8)
					dst[j+1] = uint8(((g16 * 0xffff) / a16) >> 8)
					dst[j+2] = uint8(((b16 * 0xffff) / a16) >> 8)
					dst[j+3] = uint8(a16 >> 8)
				}
				j += 4
			}
		}
	}
}

// cloneNRGBA converts any image into an NRGBA copy with origin (0,0).
func cloneNRGBA(img image.Image) *image.NRGBA {
	s := newPixelScanner(img)
	dst := image.NewNRGBA(image.Rect(0, 0, s.w, s.h))
	size := s.w * 4
	for y := 0; y < s.h; y++ {
		i := y * dst.Stride
		s.scan(0, y, s.w, y+1, dst.Pix[i:i+size])
	}
	return dst
}

func resizeH(img image.Image, width int) *image.NRGBA {
	src := newPixelScanner(img)
	dst := image.NewNRGBA(image.Rect(0, 0, width, src.h))
	weights := buildWeights(width, src.w)
	line := make([]uint8, src.w*4)
	for y := 0; y < src.h; y++ {
		src.scan(0, y, src.w, y+1, line)
		j0 := y * dst.Stride
		for i := range weights {
			var r, g, b, a float64
			for _, w := range weights[i] {
				k := w.index * 4
				s := line[k : k+4 : k+4]
				aw := float64(s[3]) * w.weight
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				aInv := 1 / a
				j := j0 + i*4
				d := dst.Pix[j : j+4 : j+4]
				d[0] = clampRound(r * aInv)
				d[1] = clampRound(g * aInv)
				d[2] = clampRound(b * aInv)
				d[3] = clampRound(a)
			}
		}
	}
	return dst
}

func resizeV(img image.Image, height int) *image.NRGBA {
	src := newPixelScanner(img)
	dst := image.NewNRGBA(image.Rect(0, 0, src.w, height))
	weights := buildWeights(height, src.h)
	line := make([]uint8, src.h*4)
	for x := 0; x < src.w; x++ {
		src.scan(x, 0, x+1, src.h, line)
		for y := range weights {
			var r, g, b, a float64
			for _, w := range weights[y] {
				k := w.index * 4
				s := line[k : k+4 : k+4]
				aw := float64(s[3]) * w.weight
				r += float64(s[0]) * aw
				g += float64(s[1]) * aw
				b += float64(s[2]) * aw
				a += aw
			}
			if a != 0 {
				aInv := 1 / a
				j := y*dst.Stride + x*4
				d := dst.Pix[j : j+4 : j+4]
				d[0] = clampRound(r * aInv)
				d[1] = clampRound(g * aInv)
				d[2] = clampRound(b * aInv)
				d[3] = clampRound(a)
			}
		}
	}
	return dst
}

// resizeLanczos scales img to exactly w x h (w,h > 0). A zero dimension keeps
// the aspect ratio.
func resizeLanczos(img image.Image, w, h int) *image.NRGBA {
	if w < 0 || h < 0 {
		return &image.NRGBA{}
	}
	if w == 0 && h == 0 {
		return &image.NRGBA{}
	}
	sw := img.Bounds().Dx()
	sh := img.Bounds().Dy()
	if sw <= 0 || sh <= 0 {
		return &image.NRGBA{}
	}
	if w == 0 {
		t := float64(h) * float64(sw) / float64(sh)
		w = int(math.Max(1.0, math.Floor(t+0.5)))
	}
	if h == 0 {
		t := float64(w) * float64(sh) / float64(sw)
		h = int(math.Max(1.0, math.Floor(t+0.5)))
	}
	if sw != w && sh != h {
		return resizeV(resizeH(img, w), h)
	}
	if sw != w {
		return resizeH(img, w)
	}
	if sh != h {
		return resizeV(img, h)
	}
	return cloneNRGBA(img)
}

func flipHorizontal(img image.Image) *image.NRGBA {
	src := newPixelScanner(img)
	dst := image.NewNRGBA(image.Rect(0, 0, src.w, src.h))
	rowSize := src.w * 4
	for y := 0; y < src.h; y++ {
		i := y * dst.Stride
		row := dst.Pix[i : i+rowSize]
		src.scan(0, y, src.w, y+1, row)
		for l, r := 0, len(row)-4; l < r; l, r = l+4, r-4 {
			for k := 0; k < 4; k++ {
				row[l+k], row[r+k] = row[r+k], row[l+k]
			}
		}
	}
	return dst
}

func flipVertical(img image.Image) *image.NRGBA {
	src := newPixelScanner(img)
	dst := image.NewNRGBA(image.Rect(0, 0, src.w, src.h))
	rowSize := src.w * 4
	for y := 0; y < src.h; y++ {
		i := (src.h - 1 - y) * dst.Stride
		src.scan(0, y, src.w, y+1, dst.Pix[i:i+rowSize])
	}
	return dst
}
