package main

import (
	"fmt"
	"image"
	_ "image/gif"
	_ "image/png"
	"os"
	"strconv"
)

func main() {
	f, _ := os.Open(os.Args[1])
	img, name, err := image.Decode(f)
	fmt.Printf("%s %T %v %v\n", name, img, img.Bounds(), err)
	step := 1
	if len(os.Args) > 2 {
		step, _ = strconv.Atoi(os.Args[2])
	}
	b := img.Bounds()
	hist := map[[4]uint32]int{}
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			r, g, bb, a := img.At(x, y).RGBA()
			hist[[4]uint32{r >> 8, g >> 8, bb >> 8, a >> 8}]++
		}
	}
	fmt.Println("distinct colors:", len(hist))
	n := 0
	for k, v := range hist {
		if n < 10 {
			fmt.Println(k, v)
		}
		n++
	}
	if step > 0 {
		for y := b.Min.Y; y < b.Max.Y; y += step {
			for x := b.Min.X; x < b.Max.X; x += (step+1)/2 {
				r, _, _, _ := img.At(x, y).RGBA()
				c := " .:-=+*#%@"[r*9/65535]
				fmt.Print(string(c))
			}
			fmt.Println()
		}
	}
}
