	v, err := strconv.ParseBool(s)
	*b.p = v
	return err
}

type intValue struct{ p *int }

func (i intValue) Set(s string) error {
	v, err := strconv.ParseInt(s, 0, 64)
	*i.p = int(v)
	return err
}

type stringValue struct{ p *string }

func (s stringValue) Set(v string) error {
	*s.p = v
	return nil
}

type intListValue struct {
	p       *[]int
	changed bool
}

func (l *intListValue) Set(val string) error {
	parts := strings.Split(val, ",")
	out := make([]int, len(parts))
	for i, d := range parts {
		var err error
		out[i], err = strconv.Atoi(d)
		if err != nil {
			return err
		}
	}
	if !l.changed {
		*l.p = out
	} else {
		*l.p = append(*l.p, out...)
	}
	l.changed = true
	return nil
}

type flagDef struct {
	name      string
	short     byte
	value     flagValue
	isBool    bool
	changed   bool
}

type flagSet struct {
	defs    []*flagDef
	byName  map[string]*flagDef
	byShort map[byte]*flagDef
	args    []string
}

func newFlagSet() *flagSet {
	return &flagSet{byName: map[string]*flagDef{}, byShort: map[byte]*flagDef{}}
}

func (fs *flagSet) add(name string, short byte, v flagValue, isBool bool) {
	d := &flagDef{name: name, short: short, value: v, isBool: isBool}
	fs.defs = append(fs.defs, d)
	fs.byName[name] = d
	if short != 0 {
		fs.byShort[short] = d
	}
}

func (fs *flagSet) boolFlag(p *bool, name string, short byte) {
	fs.add(name, short, boolValue{p}, true)
}

func (fs *flagSet) intFlag(p *int, name string, short byte) {
	fs.add(name, short, intValue{p}, false)
}

func (fs *flagSet) stringFlag(p *string, name string, short byte) {
	fs.add(name, short, stringValue{p}, false)
}

func (fs *flagSet) intListFlag(p *[]int, name string, short byte) {
	fs.add(name, short, &intListValue{p: p}, false)
}

func (fs *flagSet) set(d *flagDef, value string) error {
	if err := d.value.Set(value); err != nil {
		var label string
		if d.short != 0 {
			label = fmt.Sprintf("-%c, --%s", d.short, d.name)
		} else {
			label = fmt.Sprintf("--%s", d.name)
		}
		return fmt.Errorf("invalid argument %q for %q flag: %v", value, label, err)
	}
	d.changed = true
	return nil
}

func (fs *flagSet) parse(args []string) error {
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.args = append(fs.args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 {
				fs.args = append(fs.args, args...)
				break
			}
			args, err = fs.parseLong(s, args)
		} else {
			args, err = fs.parseShort(s, args)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (fs *flagSet) parseLong(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	split := strings.SplitN(name, "=", 2)
	name = split[0]
	d, ok := fs.byName[name]
	if !ok {
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	var value string
	switch {
	case len(split) == 2:
		value = split[1]
	case d.isBool:
		value = "true"
	case len(args) > 0:
		value = args[0]
		args = args[1:]
	default:
		return args, fmt.Errorf("flag needs an argument: %s", s)
	}
	return args, fs.set(d, value)
}

func (fs *flagSet) parseShort(s string, args []string) ([]string, error) {
	out := args
	shorthands := s[1:]
	for len(shorthands) > 0 {
		var err error
		shorthands, out, err = fs.parseSingleShort(shorthands, args)
		if err != nil {
			return out, err
		}
	}
	return out, nil
}

func (fs *flagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	outArgs := args
	rest := shorthands[1:]
	c := shorthands[0]
	d, ok := fs.byShort[c]
	if !ok {
		return rest, outArgs, fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorthands)
	}
	var value string
	switch {
	case len(shorthands) > 2 && shorthands[1] == '=':
		value = shorthands[2:]
		rest = ""
	case d.isBool:
		value = "true"
	case len(shorthands) > 1:
		value = shorthands[1:]
		rest = ""
	case len(args) > 0:
		value = args[0]
		outArgs = args[1:]
	default:
		return rest, outArgs, fmt.Errorf("flag needs an argument: %q in -%s", c, shorthands)
	}
	return rest, outArgs, fs.set(d, value)
}
