package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

// homeDir finds the current user's home directory, preferring $HOME and
// falling back to the passwd database and finally the shell.
func homeDir() (string, error) {
	if h := os.Getenv("HOME"); h != "" {
		return h, nil
	}
	var stdout bytes.Buffer
	cmd := exec.Command("getent", "passwd", strconv.Itoa(os.Getuid()))
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		if err != exec.ErrNotFound {
			return "", err
		}
	} else {
		if passwd := strings.TrimSpace(stdout.String()); passwd != "" {
			parts := strings.SplitN(passwd, ":", 7)
			if len(parts) > 5 {
				return parts[5], nil
			}
		}
	}
	stdout.Reset()
	cmd = exec.Command("sh", "-c", "cd && pwd")
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return "", err
	}
	result := strings.TrimSpace(stdout.String())
	if result == "" {
		return "", errors.New("blank output when reading home directory")
	}
	return result, nil
}

var configExts = []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "dotenv", "env", "ini"}

func checkConfigFile(home string) {
	for _, ext := range configExts {
		p := filepath.Join(home, ".ascii-image-converter."+ext)
		st, err := os.Stat(p)
		if err != nil || st.IsDir() {
			continue
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return
		}
		if configParses(ext, data) {
			fmt.Println("Using config file:", p)
		}
		return
	}
}

func configParses(ext string, data []byte) bool {
	text := string(data)
	lines := strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")
	switch ext {
	case "json":
		var m map[string]interface{}
		return json.Unmarshal(data, &m) == nil
	case "yaml", "yml":
		t := strings.TrimSpace(text)
		if t == "" {
			return true
		}
