	if os.Getenv("WSL_DISTRO_NAME") == "" {
		return false
	}
	b, err := os.ReadFile("/proc/sys/kernel/osrelease")
	if err == nil {
		return strings.Contains(string(b), "Microsoft")
	}
	return false
}

func detectColorLevel() int {
	if os.Getenv("WSL_DISTRO_NAME") != "" {
		if detectWSL() {
			return colorTrue
		}
	}
	termVal := os.Getenv("TERM")
	if termVal != "screen" {
		if os.Getenv("TERMINAL_EMULATOR") == "JetBrains-JediTerm" {
			return colorTrue
		}
	}
	level := colorLevelFromEnv(termVal)
	if level == colorNone {
		level = specialTermColor(termVal)
	}
	return level
}

func colorLevelFromEnv(termVal string) int {
	colorTerm := os.Getenv("COLORTERM")
	termProg := os.Getenv("TERM_PROGRAM")
	forceColor := os.Getenv("FORCE_COLOR")
	switch {
	case strings.Contains(colorTerm, "truecolor") || strings.Contains(colorTerm, "24bit"):
		if termVal == "screen" {
			return color256
		}
		return colorTrue
	case colorTerm != "" || forceColor != "":
		return color16
	case termProg == "Apple_Terminal":
