	asciiTableDetailed = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
)

var errNoColorSupport = errors.New("your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")

// pixelInfo holds the information extracted from a single resized pixel.
type pixelInfo struct {
	gray  uint8    // luminance (0-255)
	depth uint32   // luminance scaled to 16 bits
	rgb   [3]uint8 // premultiplied colour
}

// asciiChar is a single output cell.
type asciiChar struct {
	plain   string   // character without escape codes
	colored string   // character as printed on the terminal
	rgb     [3]uint8 // colour used when rendering to images
}

func extractPixels(img image.Image, w, h int) [][]pixelInfo {
	rows := make([][]pixelInfo, 0, h)
	for y := 0; y < h; y++ {
		row := make([]pixelInfo, 0, w)
		for x := 0; x < w; x++ {
			c := img.At(x, y)
			g := color.GrayModel.Convert(c).(color.Gray)
			r, gg, b, _ := c.RGBA()
			row = append(row, pixelInfo{
				gray:  g.Y,
				depth: uint32(g.Y) * 0x101,
				rgb:   [3]uint8{uint8(r / 257), uint8(gg / 257), uint8(b / 257)},
			})
		}
		rows = append(rows, row)
	}
	return rows
}

func colorsRequested() bool {
	return optColored || optGrayscale || !isWhite(optFontColor)
}

func isWhite(c []int) bool {
	return len(c) == 3 && c[0] == 255 && c[1] == 255 && c[2] == 255
}

// paint wraps s in the escape sequence for the given colour.
func paint(s string, rgb [3]uint8, bg bool) string {
	if !colorRendering || colorLevel == colorNone {
		return s
	}
	if colorLevel == colorTrue {
		if bg {
			return fmt.Sprintf("\x1b[48;2;%d;%d;%dm%s\x1b[0m", rgb[0], rgb[1], rgb[2], s)
		}
		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", rgb[0], rgb[1], rgb[2], s)
	}
	code := rgbTo256(rgb[0], rgb[1], rgb[2])
	if bg {
		return fmt.Sprintf("\x1b[48;5;%dm%s\x1b[0m", code, s)
	}
	return fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", code, s)
}

var cubeLevels = []uint8{0x00, 0x5f, 0x87, 0xaf, 0xd7, 0xff}

func rgbTo256(r, g, b uint8) uint8 {
	var idx [3]int
	for pi, part := range [3]uint8{r, g, b} {
		for i := 0; i < len(cubeLevels)-1; i++ {
			s, bg := cubeLevels[i], cubeLevels[i+1]
			if s <= part && part <= bg {
				d1 := int(part) - int(s)
				d2 := int(bg) - int(part)
				if d1 < d2 {
					idx[pi] = i
				} else {
					idx[pi] = i + 1
				}
				break
			}
		}
	}
	// Exact matches with the 16 system colours take precedence.
	switch idx {
	case [3]int{0, 0, 0}:
		return 0
	case [3]int{5, 0, 0}:
		return 9
	case [3]int{0, 5, 0}:
		return 10
	case [3]int{5, 5, 0}:
		return 11
	case [3]int{0, 0, 5}:
		return 12
	case [3]int{5, 0, 5}:
		return 13
	case [3]int{0, 5, 5}:
		return 14
	case [3]int{5, 5, 5}:
		return 15
	}
	return uint8(16 + 36*idx[0] + 6*idx[1] + idx[2])
}

func fontColorRGB() [3]uint8 {
	return [3]uint8{uint8(optFontColor[0]), uint8(optFontColor[1]), uint8(optFontColor[2])}
}

// decorate computes the terminal representation of a character based on the
// colouring options.
func decorate(ch string, px pixelInfo) (asciiChar, error) {
	out := asciiChar{plain: ch, colored: ch}
	rgb := px.rgb
	gray := px.gray
	if optNegative {
		rgb = [3]uint8{255 - rgb[0], 255 - rgb[1], 255 - rgb[2]}
		gray = 255 - gray
	}
	switch {
	case optColored:
		out.rgb = rgb
	case optGrayscale:
		out.rgb = [3]uint8{gray, gray, gray}
	default:
		out.rgb = fontColorRGB()
	}
	if colorsRequested() {
		if colorLevel != colorTrue && colorLevel != color256 {
			return out, errNoColorSupport
		}
		out.colored = paint(ch, out.rgb, optColorBg)
	}
	return out, nil
}

func convertToAscii(pixels [][]pixelInfo) ([][]asciiChar, error) {
	height := len(pixels)
	width := len(pixels[0])

	var table []rune
	switch {
	case optMap != "":
		table = []rune(optMap)
	case optComplex:
		table = []rune(asciiTableDetailed)
	default:
		table = []rune(asciiTableSimple)
	}
	n := float64(len(table))

	result := make([][]asciiChar, 0, height)
	for y := 0; y < height; y++ {
		row := make([]asciiChar, 0, width)
		for x := 0; x < width; x++ {
			px := pixels[y][x]
			depth := px.depth
			if optNegative {
				depth = 65535 - depth
			}
			v := float64(depth)
			t := v / 65535 * n
			if v == 65535 {
				t = n - 1
			}
			ch, err := decorate(string(table[int(t)]), px)
			if err != nil {
				return nil, err
			}
			row = append(row, ch)
		}
		result = append(result, row)
	}
	return result, nil
}

// braille dot bit for pixel offset (x,y) within a 2x4 cell.
var brailleBits = [4][2]int{{0x01, 0x08}, {0x02, 0x10}, {0x04, 0x20}, {0x40, 0x80}}

func convertToBraille(pixels [][]pixelInfo, threshold int) ([][]asciiChar, error) {
	height := len(pixels)
	width := len(pixels[0])
	result := make([][]asciiChar, 0, height/4)
	for y := 0; y+3 < height; y += 4 {
		row := make([]asciiChar, 0, width/2)
		for x := 0; x+1 < width; x += 2 {
			code := 0
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					g := int(pixels[y+dy][x+dx].gray)
					on := g >= threshold
					if optNegative {
						on = g <= threshold
					}
					if on {
						code |= brailleBits[dy][dx]
					}
				}
			}
			ch, err := decorate(string(rune(0x2800+code)), pixels[y][x])
			if err != nil {
				return nil, err
			}
			row = append(row, ch)
		}
		result = append(result, row)
	}
	return result, nil
}

func flattenArt(art [][]asciiChar, colored bool) string {
	var sb strings.Builder
	for i, row := range art {
		if i > 0 {
			sb.WriteByte('\n')
		}
		for _, c := range row {
			if colored {
				sb.WriteString(c.colored)
			} else {
				sb.WriteString(c.plain)
			}
		}
	}
	return sb.String()
}
EOF
echo ok"}

