{"command":"cd /workspace && cat > convert.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"image"
	_ "image/jpeg"
	_ "image/png"
	"io"
	"net/http"
	"os"
	"path"
	"strings"
	"syscall"
)

func isURL(p string) bool {
	return strings.HasPrefix(p, "http://") || strings.HasPrefix(p, "https://")
}

func stdinIsPipe() bool {
	st, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice == 0
}

// inputData holds the raw bytes of an input together with naming info.
type inputData struct {
	data     []byte
	label    string // used in error messages
	baseName string // used for saved file names
	isGif    bool
}

func readInput(p string) (*inputData, error) {
	in := &inputData{label: p}
	if p == "-" {
		if !stdinIsPipe() {
			return nil, fmt.Errorf("there is no input being piped to stdin")
		}
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Errorf("unable to read piped input: %v", err)
		}
		in.data = b
		in.label = "piped input"
		in.baseName = "piped-img"
		in.isGif = http.DetectContentType(b) == "image/gif"
		return in, nil
	}
	if isURL(p) {
		fmt.Printf("Fetching file from url...\r")
		resp, err := http.Get(p)
		if err != nil {
			return nil, fmt.Errorf("can't fetch content: %v", err)
		}
		defer resp.Body.Close()
		b, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, fmt.Errorf("failed to read fetched content: %v", err)
		}
		fmt.Printf("                          \r")
		in.data = b
		in.baseName = trimExt(path.Base(p))
		in.isGif = path.Ext(p) == ".gif"
		return in, nil
	}
	f, err := os.Open(p)
	if err != nil {
		return nil, fmt.Errorf("unable to open file: %v", err)
	}
	defer f.Close()
	b, rerr := io.ReadAll(f)
	if rerr != nil {
		// e.g. directories: decoding will fail with an unknown format
		if pe, ok := rerr.(*os.PathError); ok && pe.Err == syscall.EISDIR {
			b = nil
		}
	}
	in.data = b
	in.baseName = trimExt(path.Base(p))
	in.isGif = path.Ext(p) == ".gif"
	return in, nil
}

func convertPath(p string) error {
	in, err := readInput(p)
	if err != nil {
		return err
	}
	if optFont != "" {
		if err := loadUserFont(optFont); err != nil {
			return err
		}
	}
	if in.isGif {
		return processGif(in)
	}
	return processImage(in)
}

// computeDimensions returns the character dimensions of the art.
func computeDimensions(imgW, imgH int) (int, int) {
	ratio := float64(imgW) / float64(imgH)
	termW, termH := terminalSize()
	fromWidth := func(w int) (int, int) {
		h := int(float64(w) / ratio / 2)
		if h == 0 {
			h = 1
		}
		return w, h
	}
	if optFull {
		return fromWidth(termW - 1)
	}
	if optDimensions != nil {
		return optDimensions[0], optDimensions[1]
	}
	if optWidth != 0 {
		return fromWidth(optWidth)
	}
	if optHeight != 0 {
		h := optHeight
		w := 2 * int(ratio*float64(h))
		if w == 0 {
			w = 1
		}
		return w, h
	}
	h := termH - 1
	w := 2 * int(ratio*float64(h))
	if w == 0 {
		w = 1
	}
	if w > termW-1 {
		return fromWidth(termW - 1)
	}
	return w, h
}

// imageToArt converts a decoded image into a grid of characters.
func imageToArt(img image.Image) ([][]asciiChar, error) {
	b := img.Bounds()
	w, h := computeDimensions(b.Dx(), b.Dy())
	pw, ph := w, h
	if optBraille {
		pw, ph = w*2, h*4
	}
	var pixels [][]pixelInfo
	if pw > 0 && ph > 0 {
		small := resizeLanczos(img, pw, ph)
		var cur image.Image = small
		if optFlipX {
			cur = flipHorizontal(cur)
		}
		if optFlipY {
			cur = flipVertical(cur)
		}
		if optBraille && optDither {
			cur = ditherImage(cur)
		}
		pixels = extractPixels(cur, pw, ph)
	}
	if len(pixels) == 0 || len(pixels[0]) == 0 {
		var empty []int
		_ = empty[len(pixels)*0]
	}
	if optBraille {
		t := optThreshold
		if t == 0 {
			t = 128
		}
		return convertToBraille(pixels, t)
	}
	return convertToAscii(pixels)
}

func processImage(in *inputData) error {
	img, _, err := image.Decode(bytes.NewReader(in.data))
	if err != nil {
		return fmt.Errorf("can't decode %v: %v", in.label, err)
	}
	art, err := imageToArt(img)
	if err != nil {
		return err
	}
	if optSaveImg != "" {
		if err := saveArtImage(art, in.baseName); err != nil {
			return &saveError{err}
		}
	}
	if optSaveTxt != "" {
		if err := saveArtText(art, in.baseName); err != nil {
			return &saveError{err}
		}
	}
	if !optOnlySave {
		fmt.Println(flattenArt(art, colorsRequested()))
	}
	return nil
}

func saveDir(p string) string {
	if !strings.HasSuffix(p, "/") {
		p += "/"
	}
	return p
}

func saveArtText(art [][]asciiChar, base string) error {
	dir := saveDir(optSaveTxt)
	if _, err := os.Stat(dir); os.IsNotExist(err) {
		return fmt.Errorf("save path %v does not exist", dir)
	}
	full := dir + base + "-ascii-art.txt"
	f, err := os.Create(full)
	if err != nil {
		return err
	}
	defer f.Close()
	if _, err := f.WriteString(flattenArt(art, false)); err != nil {
		return err
	}
	if optOnlySave {
		fmt.Println("Saved " + full)
	}
	return nil
}
EOF
echo ok"}

