// bbox path cols rows: for each cell region (5+14c .. 5+14(c+1)), find bbox of nonzero red
func bbox() {
	f, _ := os.Open(os.Args[1])
	img, _, _ := image.Decode(f)
	cols, _ := strconv.Atoi(os.Args[2])
	rows, _ := strconv.Atoi(os.Args[3])
	for r := 0; r < rows; r++ {
		for c := 0; c < cols; c++ {
			x0, y0 := 5+14*c-4, 5+28*r-4
			x1, y1 := x0+14+8, y0+28+8
			minx, miny, maxx, maxy := 1<<30, 1<<30, -1, -1
			for y := y0; y < y1; y++ {
				for x := x0; x < x1; x++ {
					rr, _, _, _ := img.At(x, y).RGBA()
					if rr>>8 > 0 {
						if x < minx {
							minx = x
						}
						if y < miny {
							miny = y
						}
						if x > maxx {
							maxx = x
						}
						if y > maxy {
							maxy = y
						}
					}
				}
			}
			h := fnv.New32a()
			for y := miny; y <= maxy; y++ {
				for x := minx; x <= maxx; x++ {
					rr, _, _, _ := img.At(x, y).RGBA()
					h.Write([]byte{byte(rr >> 8)})
				}
			}
			fmt.Printf("cell %d,%d bbox x=%d..%d (rel %d) y=%d..%d (rel %d) hash=%08x\n", c, r, minx, maxx, minx-14*c, miny, maxy, miny-28*r, h.Sum32())
		}
	}
}
