	"image/color"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strconv"
)

var variant = os.Getenv("V")

func toLin(c uint16) float64 {
	v := float64(c) / 65535
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func lin16(c uint16) uint16 {
	return uint16(math.Round(toLin(c) * 65535))
}

func main() {
	f, _ := os.Open(os.Args[1])
	src, _, _ := image.Decode(f)
	w, _ := strconv.Atoi(os.Args[2])
	h, _ := strconv.Atoi(os.Args[3])
	img := resizeLanczos(src, w*2, h*4)
	W, H := w*2, h*4
	lins := make([][][3]int32, H)
	for y := 0; y < H; y++ {
		lins[y] = make([][3]int32, W)
		for x := 0; x < W; x++ {
			r, g, b, _ := img.At(x, y).RGBA()
			lins[y][x] = [3]int32{int32(lin16(uint16(r))), int32(lin16(uint16(g))), int32(lin16(uint16(b)))}
		}
	}
	matrix := [][]float32{{0, 0, 7.0 / 16}, {3.0 / 16, 5.0 / 16, 1.0 / 16}}
	cur := 1
	out := make([][]int, H)
	for y := 0; y < H; y++ {
		out[y] = make([]int, W)
		for x := 0; x < W; x++ {
			p := lins[y][x]
			var o [3]int32
			for k := 0; k < 3; k++ {
				o[k] = p[k]
				if o[k] < 0 {
					o[k] = 0
				}
				if o[k] > 65535 {
					o[k] = 65535
				}
			}
			// closest: black or white
			dB := float64(0)
			dW := float64(0)
			wts := [3]float64{1, 1, 1}
			for k := 0; k < 3; k++ {
				dB += wts[k] * float64(o[k]) * float64(o[k])
				dW += wts[k] * float64(65535-o[k]) * float64(65535-o[k])
			}
			var nc int32
			if dW < dB {
				nc = 65535
				out[y][x] = 1
			}
			var er [3]int32
			for k := 0; k < 3; k++ {
				er[k] = o[k] - nc
			}
			for yy := range matrix {
				for xx := range matrix[yy] {
					px, py := x+xx-cur, y+yy
					if px < 0 || px >= W || py >= H {
						continue
					}
					for k := 0; k < 3; k++ {
						switch variant {
						case "round":
							lins[py][px][k] += int32(math.Round(float64(float32(er[k]) * matrix[yy][xx])))
						default:
							lins[py][px][k] += int32(float32(er[k]) * matrix[yy][xx])
						}
					}
				}
			}
		}
	}
	_ = color.Black
	for y := 0; y < H; y++ {
		for x := 0; x < W; x++ {
			if out[y][x] == 1 {
				fmt.Print("#")
			} else {
				fmt.Print(".")
			}
		}
		fmt.Println()
	}
}
