{"command":"cd /workspace && cat > dither.go <<'EOF'
package main

import (
	"image"
	"image/color"
	"math"
)

// Floyd-Steinberg error diffusion to a black/white palette, performed in
// linear RGB space. The returned slice holds the luminance (0-255) of each
// output pixel, which is either 0 (black) or the pixel's alpha (white).

func linearize16(v uint32) int32 {
	f := float64(v) / 65535.0
	if f <= 0.04045 {
		f /= 12.92
	} else {
		f = math.Pow((f+0.055)/1.055, 2.4)
	}
	return int32(math.Round(f * 65535.0))
}

func sqDiff16(a, b uint16) uint32 {
	d := uint32(a) - uint32(b)
	return (d * d) >> 2
}

func clamp16i(v int32) int32 {
	if v < 0 {
		return 0
	}
	if v > 65535 {
		return 65535
	}
