		for y := y0; y != y1; y += dy {
			p := img.Pix[y*img.Stride : y*img.Stride+c.Width]
			if _, err := io.ReadFull(r, p); err != nil {
				return nil, err
			}
			if c.Width%4 != 0 {
				if _, err := io.ReadFull(r, tmp[:4-c.Width%4]); err != nil {
					return nil, err
				}
			}
		}
		return img, nil
	case 24:
		img := image.NewRGBA(image.Rect(0, 0, c.Width, c.Height))
		if c.Width == 0 || c.Height == 0 {
			return img, nil
		}
		b := make([]byte, (3*c.Width+3)&^3)
		for y := y0; y != y1; y += dy {
			if _, err := io.ReadFull(r, b); err != nil {
				return nil, err
			}
			p := img.Pix[y*img.Stride : y*img.Stride+c.Width*4]
			for i, j := 0, 0; i < len(p); i, j = i+4, j+3 {
				p[i+0] = b[j+2]
				p[i+1] = b[j+1]
				p[i+2] = b[j+0]
				p[i+3] = 0xff
			}
		}
		return img, nil
	case 32:
		img := image.NewNRGBA(image.Rect(0, 0, c.Width, c.Height))
		if c.Width == 0 || c.Height == 0 {
			return img, nil
		}
		for y := y0; y != y1; y += dy {
			p := img.Pix[y*img.Stride : y*img.Stride+c.Width*4]
			if _, err := io.ReadFull(r, p); err != nil {
				return nil, err
			}
			for i := 0; i < len(p); i += 4 {
				p[i+0], p[i+2] = p[i+2], p[i+0]
				if !allowAlpha {
					p[i+3] = 0xff
				}
			}
		}
		return img, nil
	}
	return nil, errBMPUnsupported
}

func decodeBMPConfig(r io.Reader) (image.Config, error) {
	c, _, _, _, err := bmpHeader(r)
	return c, err
}

func bmpHeader(r io.Reader) (image.Config, int, bool, bool, error) {
	const (
		fileHeaderLen   = 14
		infoHeaderLen   = 40
		v4InfoHeaderLen = 108
		v5InfoHeaderLen = 124
	)
	var b [1024]byte
	if _, err := io.ReadFull(r, b[:fileHeaderLen+4]); err != nil {
		if err == io.EOF {
			err = io.ErrUnexpectedEOF
		}
		return image.Config{}, 0, false, false, err
	}
	if string(b[:2]) != "BM" {
		return image.Config{}, 0, false, false, errors.New("bmp: invalid format")
	}
	offset := le32(b[10:14])
	infoLen := le32(b[14:18])
	if infoLen != infoHeaderLen && infoLen != v4InfoHeaderLen && infoLen != v5InfoHeaderLen {
		return image.Config{}, 0, false, false, errBMPUnsupported
	}
	if _, err := io.ReadFull(r, b[fileHeaderLen+4:fileHeaderLen+infoLen]); err != nil {
		if err == io.EOF {
			err = io.ErrUnexpectedEOF
		}
		return image.Config{}, 0, false, false, err
	}
	width := int(int32(le32(b[18:22])))
	height := int(int32(le32(b[22:26])))
	topDown := false
	if height < 0 {
		height, topDown = -height, true
	}
	if width < 0 || height < 0 {
		return image.Config{}, 0, false, false, errBMPUnsupported
	}
	planes, bpp, compression := le16(b[26:28]), le16(b[28:30]), le32(b[30:34])
	if compression == 3 && infoLen > infoHeaderLen &&
		le32(b[54:58]) == 0xff0000 && le32(b[58:62]) == 0xff00 &&
		le32(b[62:66]) == 0xff && le32(b[66:70]) == 0xff000000 {
		compression = 0
	}
	if planes != 1 || compression != 0 {
		return image.Config{}, 0, false, false, errBMPUnsupported
	}
	switch bpp {
	case 8:
		colorUsed := le32(b[46:50])
		if colorUsed == 0 {
			colorUsed = 256
		} else if colorUsed > 256 {
			return image.Config{}, 0, false, false, errBMPUnsupported
		}
		if offset != fileHeaderLen+infoLen+colorUsed*4 {
			return image.Config{}, 0, false, false, errBMPUnsupported
		}
		if _, err := io.ReadFull(r, b[:colorUsed*4]); err != nil {
			return image.Config{}, 0, false, false, err
		}
		pcm := make(color.Palette, colorUsed)
		for i := range pcm {
			pcm[i] = color.RGBA{b[4*i+2], b[4*i+1], b[4*i+0], 0xff}
		}
		return image.Config{ColorModel: pcm, Width: width, Height: height}, 8, topDown, false, nil
	case 24:
		if offset != fileHeaderLen+infoLen {
			return image.Config{}, 0, false, false, errBMPUnsupported
		}
		return image.Config{ColorModel: color.RGBAModel, Width: width, Height: height}, 24, topDown, false, nil
	case 32:
		if offset != fileHeaderLen+infoLen {
			return image.Config{}, 0, false, false, errBMPUnsupported
		}
		return image.Config{ColorModel: color.RGBAModel, Width: width, Height: height}, 32, topDown, infoLen > infoHeaderLen, nil
	}
	return image.Config{}, 0, false, false, errBMPUnsupported
}
