package main

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"io"
	"math"
)

// Baseline TIFF decoder: uncompressed, PackBits, LZW and Deflate
// compression; gray, paletted and RGB(A) photometric interpretations with
// 1, 8 or 16 bits per sample; strips or tiles; horizontal predictor.

func init() {
	image.RegisterFormat("tiff", "MM\x00\x2A", decodeTIFF, decodeTIFFConfig)
	image.RegisterFormat("tiff", "II\x2A\x00", decodeTIFF, decodeTIFFConfig)
}

type tiffFormatError string

func (e tiffFormatError) Error() string { return "tiff: invalid format: " + string(e) }

type tiffUnsupportedError string

func (e tiffUnsupportedError) Error() string { return "tiff: unsupported feature: " + string(e) }

var errTIFFNoPixels = tiffFormatError("not enough pixel data")

const (
	tImageWidth                = 256
	tImageLength               = 257
	tBitsPerSample             = 258
	tCompression               = 259
	tPhotometricInterpretation = 262
	tFillOrder                 = 266
	tStripOffsets              = 273
	tSamplesPerPixel           = 277
	tRowsPerStrip              = 278
	tStripByteCounts           = 279
	tT4Options                 = 292
	tT6Options                 = 293
	tTileWidth                 = 322
	tTileLength                = 323
	tTileOffsets               = 324
	tTileByteCounts            = 325
	tXResolution               = 282
	tYResolution               = 283
	tResolutionUnit            = 296
	tPredictor                 = 317
	tColorMap                  = 320
	tExtraSamples              = 338
	tSampleFormat              = 339
)

const (
	cNone       = 1
	cCCITT      = 2
	cG3         = 3
	cG4         = 4
	cLZW        = 5
	cJPEGOld    = 6
	cJPEG       = 7
	cDeflate    = 8
	cPackBits   = 32773
	cDeflateOld = 32946
)

const (
	pWhiteIsZero = 0
	pBlackIsZero = 1
	pRGB         = 2
	pPaletted    = 3
)

const (
	mBilevel = iota
	mPaletted
	mGray
	mGrayInvert
	mRGB
	mRGBA
	mNRGBA
)

var tiffLengths = [...]uint32{0, 1, 1, 2, 4, 8}

const (
	dtByte  = 1
	dtShort = 3
	dtLong  = 4
)

type tiffDecoder struct {
	r         *bytes.Reader
	data      []byte
	byteOrder binary.ByteOrder
	config    image.Config
	mode      int
	bpp       uint
	features  map[int][]uint
	palette   []color.Color

	buf   []byte
	off   int
	v     uint32
	nbits uint
}

func (d *tiffDecoder) firstVal(tag int) uint {
	f := d.features[tag]
	if len(f) == 0 {
		return 0
	}
	return f[0]
}

func (d *tiffDecoder) readAt(p []byte, off int64) (int, error) {
	return d.r.ReadAt(p, off)
}

func (d *tiffDecoder) ifdUint(p []byte) ([]uint, error) {
	var raw []byte
	if len(p) < 12 {
		return nil, tiffFormatError("bad IFD entry")
	}
	datatype := d.byteOrder.Uint16(p[2:4])
	if dt := int(datatype); dt <= 0 || dt >= len(tiffLengths) {
		return nil, tiffUnsupportedError("IFD entry datatype")
	}
	count := d.byteOrder.Uint32(p[4:8])
	if count > math.MaxInt32/tiffLengths[datatype] {
		return nil, tiffFormatError("IFD data too large")
	}
	var err error
	if datalen := tiffLengths[datatype] * count; datalen > 4 {
		raw = make([]byte, datalen)
		_, err = d.readAt(raw, int64(d.byteOrder.Uint32(p[8:12])))
	} else {
		raw = p[8 : 8+datalen]
	}
	if err != nil {
		return nil, err
	}
	u := make([]uint, count)
	switch datatype {
	case dtByte:
		for i := uint32(0); i < count; i++ {
			u[i] = uint(raw[i])
		}
	case dtShort:
		for i := uint32(0); i < count; i++ {
			u[i] = uint(d.byteOrder.Uint16(raw[2*i : 2*(i+1)]))
		}
	case dtLong:
		for i := uint32(0); i < count; i++ {
			u[i] = uint(d.byteOrder.Uint32(raw[4*i : 4*(i+1)]))
		}
	default:
		return nil, tiffUnsupportedError("data type")
	}
	return u, nil
}

func (d *tiffDecoder) parseIFD(p []byte) (int, error) {
	tag := d.byteOrder.Uint16(p[0:2])
	switch tag {
	case tBitsPerSample, tExtraSamples, tPhotometricInterpretation, tCompression,
		tPredictor, tStripOffsets, tStripByteCounts, tRowsPerStrip, tTileWidth,
		tTileLength, tTileOffsets, tTileByteCounts, tImageLength, tImageWidth,
		tFillOrder, tT4Options, tT6Options:
		val, err := d.ifdUint(p)
		if err != nil {
			return 0, err
		}
		d.features[int(tag)] = val
	case tColorMap:
		val, err := d.ifdUint(p)
		if err != nil {
			return 0, err
		}
		numcolors := len(val) / 3
		if len(val)%3 != 0 || numcolors <= 0 || numcolors > 256 {
			return 0, tiffFormatError("bad ColorMap length")
		}
		d.palette = make([]color.Color, numcolors)
		for i := 0; i < numcolors; i++ {
			d.palette[i] = color.RGBA64{
				uint16(val[i]),
				uint16(val[i+numcolors]),
				uint16(val[i+2*numcolors]),
				0xffff,
			}
		}
	case tSampleFormat:
		val, err := d.ifdUint(p)
		if err != nil {
			return 0, err
		}
		for _, v := range val {
			if v != 1 {
				return 0, tiffUnsupportedError("sample format")
			}
		}
	}
	return int(tag), nil
}

func (d *tiffDecoder) readBits(n uint) (uint32, bool) {
	for d.nbits < n {
		d.v <<= 8
		if d.off >= len(d.buf) {
			return 0, false
		}
		d.v |= uint32(d.buf[d.off])
		d.off++
		d.nbits += 8
	}
	d.nbits -= n
	rv := d.v >> d.nbits
	d.v &^= rv << d.nbits
	return rv, true
}

func (d *tiffDecoder) flushBits() {
	d.v = 0
	d.nbits = 0
}

func minI(a, b int) int {
	if a <= b {
		return a
	}
	return b
}

func (d *tiffDecoder) decode(dst image.Image, xmin, ymin, xmax, ymax int) error {
	d.off = 0

	if d.firstVal(tPredictor) == 2 {
		switch d.bpp {
		case 16:
			var off int
			n := 2 * len(d.features[tBitsPerSample])
			for y := ymin; y < ymax; y++ {
				off += n
				for x := 0; x < (xmax-xmin-1)*n; x += 2 {
					if off+2 > len(d.buf) {
						return errTIFFNoPixels
					}
					v0 := d.byteOrder.Uint16(d.buf[off-n : off-n+2])
					v1 := d.byteOrder.Uint16(d.buf[off : off+2])
					d.byteOrder.PutUint16(d.buf[off:off+2], v1+v0)
					off += 2
				}
			}
		case 8:
			var off int
			n := 1 * len(d.features[tBitsPerSample])
			for y := ymin; y < ymax; y++ {
				off += n
				for x := 0; x < (xmax-xmin-1)*n; x++ {
					if off >= len(d.buf) {
						return errTIFFNoPixels
					}
					d.buf[off] += d.buf[off-n]
					off++
				}
			}
		case 1:
			return tiffUnsupportedError("horizontal predictor with 1 BitsPerSample")
		}
	}

	rMaxX := minI(xmax, dst.Bounds().Max.X)
	rMaxY := minI(ymax, dst.Bounds().Max.Y)
	switch d.mode {
	case mGray, mGrayInvert:
		if d.bpp == 16 {
			img := dst.(*image.Gray16)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+2 > len(d.buf) {
						return errTIFFNoPixels
					}
					v := d.byteOrder.Uint16(d.buf[d.off : d.off+2])
					d.off += 2
					if d.mode == mGrayInvert {
						v = 0xffff - v
					}
					img.SetGray16(x, y, color.Gray16{v})
				}
				if rMaxX == img.Bounds().Max.X {
					d.off += 2 * (xmax - img.Bounds().Max.X)
				}
			}
		} else {
			img := dst.(*image.Gray)
			max := uint32((1 << d.bpp) - 1)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					v, ok := d.readBits(d.bpp)
					if !ok {
						return errTIFFNoPixels
					}
					v = v * 0xff / max
					if d.mode == mGrayInvert {
						v = 0xff - v
					}
					img.SetGray(x, y, color.Gray{uint8(v)})
				}
				d.flushBits()
			}
		}
	case mPaletted:
		img := dst.(*image.Paletted)
		for y := ymin; y < rMaxY; y++ {
			for x := xmin; x < rMaxX; x++ {
				v, ok := d.readBits(d.bpp)
				if !ok {
					return errTIFFNoPixels
				}
				img.SetColorIndex(x, y, uint8(v))
			}
			d.flushBits()
		}
	case mRGB:
		if d.bpp == 16 {
			img := dst.(*image.RGBA64)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+6 > len(d.buf) {
						return errTIFFNoPixels
					}
					r := d.byteOrder.Uint16(d.buf[d.off+0 : d.off+2])
					g := d.byteOrder.Uint16(d.buf[d.off+2 : d.off+4])
					b := d.byteOrder.Uint16(d.buf[d.off+4 : d.off+6])
					d.off += 6
					img.SetRGBA64(x, y, color.RGBA64{r, g, b, 0xffff})
				}
			}
		} else {
			img := dst.(*image.RGBA)
			for y := ymin; y < rMaxY; y++ {
				min := img.PixOffset(xmin, y)
				max := img.PixOffset(rMaxX, y)
				off := (y - ymin) * (xmax - xmin) * 3
				for i := min; i < max; i += 4 {
					if off+3 > len(d.buf) {
						return errTIFFNoPixels
					}
					img.Pix[i+0] = d.buf[off+0]
					img.Pix[i+1] = d.buf[off+1]
					img.Pix[i+2] = d.buf[off+2]
					img.Pix[i+3] = 0xff
					off += 3
				}
			}
		}
	case mNRGBA:
		if d.bpp == 16 {
			img := dst.(*image.NRGBA64)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+8 > len(d.buf) {
						return errTIFFNoPixels
					}
					r := d.byteOrder.Uint16(d.buf[d.off+0 : d.off+2])
					g := d.byteOrder.Uint16(d.buf[d.off+2 : d.off+4])
					b := d.byteOrder.Uint16(d.buf[d.off+4 : d.off+6])
					a := d.byteOrder.Uint16(d.buf[d.off+6 : d.off+8])
					d.off += 8
					img.SetNRGBA64(x, y, color.NRGBA64{r, g, b, a})
				}
			}
		} else {
			img := dst.(*image.NRGBA)
			for y := ymin; y < rMaxY; y++ {
				min := img.PixOffset(xmin, y)
				max := img.PixOffset(rMaxX, y)
				i0, i1 := (y-ymin)*(xmax-xmin)*4, (y-ymin+1)*(xmax-xmin)*4
				if i1 > len(d.buf) {
					return errTIFFNoPixels
				}
				copy(img.Pix[min:max], d.buf[i0:i1])
			}
		}
	case mRGBA:
		if d.bpp == 16 {
			img := dst.(*image.RGBA64)
			for y := ymin; y < rMaxY; y++ {
				for x := xmin; x < rMaxX; x++ {
					if d.off+8 > len(d.buf) {
						return errTIFFNoPixels
					}
					r := d.byteOrder.Uint16(d.buf[d.off+0 : d.off+2])
					g := d.byteOrder.Uint16(d.buf[d.off+2 : d.off+4])
					b := d.byteOrder.Uint16(d.buf[d.off+4 : d.off+6])
					a := d.byteOrder.Uint16(d.buf[d.off+6 : d.off+8])
					d.off += 8
					img.SetRGBA64(x, y, color.RGBA64{r, g, b, a})
				}
			}
		} else {
			img := dst.(*image.RGBA)
			for y := ymin; y < rMaxY; y++ {
				min := img.PixOffset(xmin, y)
				max := img.PixOffset(rMaxX, y)
				i0, i1 := (y-ymin)*(xmax-xmin)*4, (y-ymin+1)*(xmax-xmin)*4
				if i1 > len(d.buf) {
					return errTIFFNoPixels
				}
				copy(img.Pix[min:max], d.buf[i0:i1])
			}
		}
	}
	return nil
}

func newTIFFDecoder(r io.Reader) (*tiffDecoder, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	d := &tiffDecoder{r: bytes.NewReader(data), data: data, features: make(map[int][]uint)}

	p := make([]byte, 8)
	if _, err := d.readAt(p, 0); err != nil {
		if err == io.EOF {
			err = io.ErrUnexpectedEOF
		}
		return nil, err
	}
	switch string(p[0:4]) {
	case "II\x2A\x00":
		d.byteOrder = binary.LittleEndian
	case "MM\x00\x2A":
		d.byteOrder = binary.BigEndian
	default:
		return nil, tiffFormatError("malformed header")
	}

	ifdOffset := int64(d.byteOrder.Uint32(p[4:8]))
	if _, err := d.readAt(p[0:2], ifdOffset); err != nil {
		return nil, err
	}
	numItems := int(d.byteOrder.Uint16(p[0:2]))
	p = make([]byte, 12*numItems)
	if _, err := d.readAt(p, ifdOffset+2); err != nil {
		return nil, err
	}

	prevTag := -1
	for i := 0; i < len(p); i += 12 {
		tag, err := d.parseIFD(p[i : i+12])
		if err != nil {
			return nil, err
		}
		if tag <= prevTag {
			return nil, tiffFormatError("tags are not sorted in ascending order")
		}
		prevTag = tag
	}

	d.config.Width = int(d.firstVal(tImageWidth))
	d.config.Height = int(d.firstVal(tImageLength))

	if _, ok := d.features[tBitsPerSample]; !ok {
		d.features[tBitsPerSample] = []uint{1}
	}
	d.bpp = d.firstVal(tBitsPerSample)
	switch d.bpp {
	case 0:
		return nil, tiffFormatError("BitsPerSample must not be 0")
	case 1, 8, 16:
	default:
		return nil, tiffUnsupportedError(fmt.Sprintf("BitsPerSample of %v", d.bpp))
	}

	switch d.firstVal(tPhotometricInterpretation) {
	case pRGB:
		if d.bpp == 16 {
			for _, b := range d.features[tBitsPerSample] {
				if b != 16 {
					return nil, tiffFormatError("wrong number of samples for 16bit RGB")
				}
			}
		} else {
			for _, b := range d.features[tBitsPerSample] {
				if b != 8 {
					return nil, tiffFormatError("wrong number of samples for 8bit RGB")
				}
			}
		}
		switch len(d.features[tBitsPerSample]) {
		case 3:
			d.mode = mRGB
			if d.bpp == 16 {
				d.config.ColorModel = color.RGBA64Model
			} else {
				d.config.ColorModel = color.RGBAModel
			}
		case 4:
			switch d.firstVal(tExtraSamples) {
			case 1:
				d.mode = mRGBA
				if d.bpp == 16 {
					d.config.ColorModel = color.RGBA64Model
				} else {
					d.config.ColorModel = color.RGBAModel
				}
			case 2:
				d.mode = mNRGBA
				if d.bpp == 16 {
					d.config.ColorModel = color.NRGBA64Model
				} else {
					d.config.ColorModel = color.NRGBAModel
				}
			default:
				return nil, tiffFormatError("wrong number of samples for RGB")
			}
		default:
			return nil, tiffFormatError("wrong number of samples for RGB")
		}
	case pPaletted:
		d.mode = mPaletted
		d.config.ColorModel = color.Palette(d.palette)
	case pWhiteIsZero:
		d.mode = mGrayInvert
		if d.bpp == 16 {
			d.config.ColorModel = color.Gray16Model
		} else {
			d.config.ColorModel = color.GrayModel
		}
	case pBlackIsZero:
		d.mode = mGray
		if d.bpp == 16 {
			d.config.ColorModel = color.Gray16Model
		} else {
			d.config.ColorModel = color.GrayModel
		}
	default:
		return nil, tiffUnsupportedError("color model")
	}
	return d, nil
}

func decodeTIFFConfig(r io.Reader) (image.Config, error) {
	d, err := newTIFFDecoder(r)
	if err != nil {
		return image.Config{}, err
	}
	return d.config, nil
}

func decodeTIFF(r io.Reader) (img image.Image, err error) {
	d, err := newTIFFDecoder(r)
	if err != nil {
		return
	}

	blockPadding := false
	blockWidth := d.config.Width
	blockHeight := d.config.Height
	blocksAcross := 1
	blocksDown := 1
	if d.config.Width == 0 {
		blocksAcross = 0
	}
	if d.config.Height == 0 {
		blocksDown = 0
	}

	var blockOffsets, blockCounts []uint
	if int(d.firstVal(tTileWidth)) != 0 {
		blockPadding = true
		blockWidth = int(d.firstVal(tTileWidth))
		blockHeight = int(d.firstVal(tTileLength))
		if blockWidth != 0 {
			blocksAcross = (d.config.Width + blockWidth - 1) / blockWidth
		}
		if blockHeight != 0 {
			blocksDown = (d.config.Height + blockHeight - 1) / blockHeight
		}
		blockCounts = d.features[tTileByteCounts]
		blockOffsets = d.features[tTileOffsets]
	} else {
		if int(d.firstVal(tRowsPerStrip)) != 0 {
			blockHeight = int(d.firstVal(tRowsPerStrip))
		}
		if blockHeight != 0 {
			blocksDown = (d.config.Height + blockHeight - 1) / blockHeight
		}
		blockOffsets = d.features[tStripOffsets]
		blockCounts = d.features[tStripByteCounts]
	}

	if n := blocksAcross * blocksDown; len(blockOffsets) < n || len(blockCounts) < n {
		return nil, tiffFormatError("inconsistent header")
	}

	imgRect := image.Rect(0, 0, d.config.Width, d.config.Height)
	switch d.mode {
	case mGray, mGrayInvert:
		if d.bpp == 16 {
			img = image.NewGray16(imgRect)
		} else {
			img = image.NewGray(imgRect)
		}
	case mPaletted:
		img = image.NewPaletted(imgRect, d.palette)
	case mNRGBA:
		if d.bpp == 16 {
			img = image.NewNRGBA64(imgRect)
		} else {
			img = image.NewNRGBA(imgRect)
		}
	case mRGB, mRGBA:
		if d.bpp == 16 {
			img = image.NewRGBA64(imgRect)
		} else {
			img = image.NewRGBA(imgRect)
		}
	}

	for i := 0; i < blocksAcross; i++ {
		blkW := blockWidth
		if !blockPadding && i == blocksAcross-1 && d.config.Width%blockWidth != 0 {
			blkW = d.config.Width % blockWidth
		}
		for j := 0; j < blocksDown; j++ {
			blkH := blockHeight
			if !blockPadding && j == blocksDown-1 && d.config.Height%blockHeight != 0 {
				blkH = d.config.Height % blockHeight
			}
			offset := int64(blockOffsets[j*blocksAcross+i])
			n := int64(blockCounts[j*blocksAcross+i])
			switch d.firstVal(tCompression) {
			case cNone, 0:
				if offset < 0 || offset > int64(len(d.data)) || offset+n > int64(len(d.data)) || n < 0 {
					d.buf = make([]byte, n)
					_, err = d.readAt(d.buf, offset)
					if err == nil {
						err = io.EOF
					}
				} else {
					d.buf = d.data[offset : offset+n]
				}
			case cLZW:
				d.buf, err = tiffLZWDecode(io.NewSectionReader(d.r, offset, n))
			case cDeflate, cDeflateOld:
				var zr io.ReadCloser
				zr, err = zlib.NewReader(io.NewSectionReader(d.r, offset, n))
				if err != nil {
					return nil, err
				}
				d.buf, err = io.ReadAll(zr)
				zr.Close()
			case cPackBits:
				d.buf, err = unpackBits(io.NewSectionReader(d.r, offset, n))
			default:
				err = tiffUnsupportedError(fmt.Sprintf("compression value %d", d.firstVal(tCompression)))
			}
			if err != nil {
				return nil, err
			}
			xmin := i * blockWidth
			ymin := j * blockHeight
			xmax := xmin + blkW
			ymax := ymin + blkH
			if err = d.decode(img, xmin, ymin, xmax, ymax); err != nil {
				return nil, err
			}
		}
	}
	return
}

func unpackBits(r io.Reader) ([]byte, error) {
	buf := make([]byte, 128)
	dst := make([]byte, 0, 1024)
	br := &byteReader{r: r}
	for {
		b, err := br.ReadByte()
		if err != nil {
			if err == io.EOF {
				return dst, nil
			}
			return nil, err
		}
		code := int(int8(b))
		switch {
		case code >= 0:
			n, err := io.ReadFull(br, buf[:code+1])
			if err != nil {
				return nil, err
			}
			dst = append(dst, buf[:n]...)
		case code == -128:
		default:
			if b, err = br.ReadByte(); err != nil {
				return nil, err
			}
			for j := 0; j < 1-code; j++ {
				buf[j] = b
			}
			dst = append(dst, buf[:1-code]...)
		}
	}
}

type byteReader struct {
	r   io.Reader
	one [1]byte
}

func (b *byteReader) Read(p []byte) (int, error) { return b.r.Read(p) }

func (b *byteReader) ReadByte() (byte, error) {
	n, err := b.r.Read(b.one[:])
	if n == 1 {
		return b.one[0], nil
	}
	if err == nil {
		err = io.EOF
	}
	return 0, err
}

// tiffLZWDecode decodes TIFF flavoured LZW (MSB first, early change).
func tiffLZWDecode(r io.Reader) ([]byte, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	const (
		clearCode = 256
		eofCode   = 257
	)
	var (
		out      []byte
		bits     uint32
		nBits    uint
		pos      int
		width    uint = 9
		prefix   [4096]uint16
		suffix   [4096]uint8
		lengths  [4096]int
		hi       = eofCode
		last     = -1
		overflow = 1 << 9
	)
	for i := 0; i < 256; i++ {
		suffix[i] = uint8(i)
		lengths[i] = 1
	}
	readCode := func() (int, bool) {
		for nBits < width {
			if pos >= len(data) {
				return 0, false
			}
			bits = bits<<8 | uint32(data[pos])
			pos++
			nBits += 8
		}
		code := int(bits>>(nBits-width)) & (1<<width - 1)
		nBits -= width
		return code, true
	}
	tmp := make([]byte, 4096)
	emit := func(code int) byte {
		n := lengths[code]
		c := code
		for i := n - 1; i >= 0; i-- {
			tmp[i] = suffix[c]
			c = int(prefix[c])
		}
		out = append(out, tmp[:n]...)
		return tmp[0]
	}
	for {
		code, ok := readCode()
		if !ok {
			return out, errLZWUnexpectedEOF
		}
		switch {
		case code < clearCode:
			if last != -1 && hi < 4095 {
				hi++
				prefix[hi] = uint16(last)
				suffix[hi] = uint8(code)
				lengths[hi] = lengths[last] + 1
			}
			out = append(out, byte(code))
			last = code
		case code == clearCode:
			width = 9
			hi = eofCode
			overflow = 1 << width
			last = -1
			continue
		case code == eofCode:
			return out, nil
		case code <= hi:
			first := emitFirst(code, prefix[:], suffix[:])
			if last != -1 && hi < 4095 {
				hi++
				prefix[hi] = uint16(last)
				suffix[hi] = first
				lengths[hi] = lengths[last] + 1
			}
			emit(code)
			last = code
		case code == hi+1 && last != -1:
			first := emitFirst(last, prefix[:], suffix[:])
			hi++
			prefix[hi] = uint16(last)
			suffix[hi] = first
			lengths[hi] = lengths[last] + 1
			emit(hi)
			last = hi
		default:
			return out, errLZWInvalidCode
		}
		if hi+1 >= overflow-1 {
			if width == 12 {
				// stay at maximum width until a clear code arrives
				continue
			}
			width++
			overflow <<= 1
		}
	}
}

func emitFirst(code int, prefix []uint16, suffix []uint8) uint8 {
	for code >= 258 {
		code = int(prefix[code])
	}
	return suffix[code]
}

type lzwError string

func (e lzwError) Error() string { return string(e) }

var (
	errLZWUnexpectedEOF = io.ErrUnexpectedEOF
	errLZWInvalidCode   = lzwError("lzw: invalid code")
)
