// lzwEncodeTIFF: MSB-first LZW with early change.
func lzwEncodeTIFF(data []byte) []byte {
	var out []byte
	var bits uint32
	var nbits uint
	width := uint(9)
	write := func(code int) {
		bits = bits<<width | uint32(code)
		nbits += width
		for nbits >= 8 {
			out = append(out, byte(bits>>(nbits-8)))
			nbits -= 8
			bits &= (1 << nbits) - 1
		}
	}
	dict := map[string]int{}
	next := 258
	reset := func() {
		dict = map[string]int{}
		for i := 0; i < 256; i++ {
			dict[string([]byte{byte(i)})] = i
		}
		next = 258
		width = 9
	}
	reset()
	write(256)
	w := ""
	for _, c := range data {
		wc := w + string([]byte{c})
		if _, ok := dict[wc]; ok {
			w = wc
			continue
		}
		write(dict[w])
		dict[wc] = next
		next++
		if next+1 > (1<<width) && width < 12 {
			width++
		}
		if next >= 4094 {
			write(256)
			reset()
		}
		w = string([]byte{c})
	}
	if w != "" {
		write(dict[w])
		next++
		if next+1 > (1<<width) && width < 12 {
			width++
		}
	}
	write(257)
	if nbits > 0 {
		out = append(out, byte(bits<<(8-nbits)))
	}
	return out
}

func packBits(data []byte) []byte {
	var out []byte
	for i := 0; i < len(data); {
		// find run
		j := i + 1
		for j < len(data) && data[j] == data[i] && j-i < 128 {
			j++
		}
		if j-i >= 3 {
			out = append(out, byte(int8(-(j - i - 1))), data[i])
			i = j
			continue
		}
		k := i
		for k < len(data) && k-i < 128 {
			if k+2 < len(data) && data[k] == data[k+1] && data[k] == data[k+2] {
				break
			}
			k++
		}
		out = append(out, byte(k-i-1))
		out = append(out, data[i:k]...)
		i = k
	}
	return out
}

func init() {
	if len(os.Args) > 1 && os.Args[1] == "tiff" {
		// tiff in.png out.tif opts(comma separated): be, lzw, deflate, packbits, pred, strip=N, tile=N, gray, gray16, rgb16, rgba, nrgba, pal, bilevel, wiz
		f, _ := os.Open(os.Args[2])
		src, _ := png.Decode(f)
		b := src.Bounds()
		w, h := b.Dx(), b.Dy()
		opts := map[string]string{}
		for _, o := range strings.Split(os.Args[4], ",") {
			kv := strings.SplitN(o, "=", 2)
			if len(kv) == 2 {
				opts[kv[0]] = kv[1]
			} else {
				opts[kv[0]] = "1"
			}
		}
		var bo binary.ByteOrder = binary.LittleEndian
		if opts["be"] != "" {
			bo = binary.BigEndian
		}
		spp, bps, photometric, extra := 3, 8, 2, -1
		switch {
		case opts["gray"] != "":
			spp, bps, photometric = 1, 8, 1
		case opts["gray16"] != "":
			spp, bps, photometric = 1, 16, 1
		case opts["wiz"] != "":
			spp, bps, photometric = 1, 8, 0
		case opts["bilevel"] != "":
			spp, bps, photometric = 1, 1, 1
		case opts["rgb16"] != "":
			spp, bps = 3, 16
		case opts["rgba"] != "":
			spp, extra = 4, 1
		case opts["nrgba"] != "":
			spp, extra = 4, 2
		case opts["nrgba16"] != "":
			spp, bps, extra = 4, 16, 2
		case opts["pal"] != "":
			spp, bps, photometric = 1, 8, 3
		}
		var pal color.Palette
		if photometric == 3 {
			for i := 0; i < 256; i++ {
				pal = append(pal, color.RGBA{uint8(i), uint8(i * 3), uint8(255 - i), 255})
			}
		}
		// pixel row bytes
		rowBytes := func(y, x0, x1 int) []byte {
			var row []byte
			if bps == 1 {
				var cur byte
				n := 0
				for x := x0; x < x1; x++ {
					g := color.GrayModel.Convert(src.At(x+b.Min.X, y+b.Min.Y)).(color.Gray).Y
					cur <<= 1
					if g >= 128 {
						cur |= 1
					}
					n++
					if n == 8 {
						row = append(row, cur)
						cur, n = 0, 0
					}
				}
				if n > 0 {
					row = append(row, cur<<(8-uint(n)))
				}
				return row
			}
			for x := x0; x < x1; x++ {
				var c color.Color = color.Black
				if x < w && y < h {
					c = src.At(x+b.Min.X, y+b.Min.Y)
				}
				switch {
				case photometric == 3:
					row = append(row, uint8(pal.Index(c)))
				case photometric <= 1 && bps == 8:
					g := color.GrayModel.Convert(c).(color.Gray).Y
					if photometric == 0 {
						g = 255 - g
					}
					row = append(row, g)
				case photometric == 1 && bps == 16:
					g := color.Gray16Model.Convert(c).(color.Gray16).Y
					var t [2]byte
					bo.PutUint16(t[:], g*7+uint16(x))
					row = append(row, t[:]...)
				case bps == 16:
					n := color.NRGBA64Model.Convert(c).(color.NRGBA64)
					vals := []uint16{n.R ^ uint16(x*31), n.G, n.B}
					if spp == 4 {
						vals = append(vals, n.A)
					}
					for _, v := range vals {
						var t [2]byte
						bo.PutUint16(t[:], v)
						row = append(row, t[:]...)
					}
				case extra == 1:
					rr, gg, bb, aa := c.RGBA()
					row = append(row, uint8(rr>>8), uint8(gg>>8), uint8(bb>>8), uint8(aa>>8))
				default:
					n := color.NRGBAModel.Convert(c).(color.NRGBA)
					row = append(row, n.R, n.G, n.B)
					if spp == 4 {
						row = append(row, n.A)
					}
				}
			}
			return row
		}
		bytesPerPixel := spp * bps / 8
		compress := func(raw []byte, rw int) []byte {
			if opts["pred"] != "" && bps == 8 {
				// horizontal differencing per row
				out := make([]byte, len(raw))
				copy(out, raw)
				rowLen := rw * bytesPerPixel
				for r := 0; r*rowLen < len(raw); r++ {
					row := out[r*rowLen : (r+1)*rowLen]
					for i := len(row) - 1; i >= bytesPerPixel; i-- {
						row[i] -= row[i-bytesPerPixel]
					}
				}
				raw = out
			}
			switch {
			case opts["lzw"] != "":
				return lzwEncodeTIFF(raw)
			case opts["deflate"] != "":
				var buf bytes.Buffer
				zw := zlib.NewWriter(&buf)
				zw.Write(raw)
				zw.Close()
				return buf.Bytes()
			case opts["packbits"] != "":
				return packBits(raw)
			}
			return raw
		}
		var blocks [][]byte
		var entries []ifdEntry
		tileN := 0
		if t, ok := opts["tile"]; ok {
			for _, c := range t {
				tileN = tileN*10 + int(c-'0')
			}
		}
		stripN := h
		if s, ok := opts["strip"]; ok {
			stripN = 0
			for _, c := range s {
				stripN = stripN*10 + int(c-'0')
			}
		}
		if tileN > 0 {
			for ty := 0; ty < (h+tileN-1)/tileN; ty++ {
				for tx := 0; tx < (w+tileN-1)/tileN; tx++ {
					var raw []byte
					for y := ty * tileN; y < (ty+1)*tileN; y++ {
						raw = append(raw, rowBytes(y, tx*tileN, (tx+1)*tileN)...)
					}
					blocks = append(blocks, compress(raw, tileN))
				}
			}
		} else {
			for y0 := 0; y0 < h; y0 += stripN {
				var raw []byte
				for y := y0; y < y0+stripN && y < h; y++ {
					raw = append(raw, rowBytes(y, 0, w)...)
				}
				blocks = append(blocks, compress(raw, w))
			}
		}
		comp := uint32(1)
		switch {
		case opts["lzw"] != "":
			comp = 5
		case opts["deflate"] != "":
			comp = 8
		case opts["packbits"] != "":
			comp = 32773
		}
		bpsVals := []uint32{}
		for i := 0; i < spp; i++ {
			bpsVals = append(bpsVals, uint32(bps))
		}
		entries = append(entries,
			ifdEntry{256, 4, []uint32{uint32(w)}},
			ifdEntry{257, 4, []uint32{uint32(h)}},
			ifdEntry{258, 3, bpsVals},
			ifdEntry{259, 3, []uint32{comp}},
			ifdEntry{262, 3, []uint32{uint32(photometric)}},
			ifdEntry{277, 3, []uint32{uint32(spp)}},
		)
		if opts["pred"] != "" {
			entries = append(entries, ifdEntry{317, 3, []uint32{2}})
		}
		if extra >= 0 {
			entries = append(entries, ifdEntry{338, 3, []uint32{uint32(extra)}})
		}
		if photometric == 3 {
			var cm []uint32
			for ch := 0; ch < 3; ch++ {
				for _, c := range pal {
					r, g, bb, _ := c.RGBA()
					cm = append(cm, []uint32{r, g, bb}[ch])
				}
			}
			entries = append(entries, ifdEntry{320, 3, cm})
		}
		// layout: header(8) + blocks + ifd
		var body bytes.Buffer
		body.Write(make([]byte, 8))
		var offs, counts []uint32
		for _, blk := range blocks {
			offs = append(offs, uint32(body.Len()))
			counts = append(counts, uint32(len(blk)))
			body.Write(blk)
			if body.Len()%2 == 1 {
				body.WriteByte(0)
			}
		}
		if tileN > 0 {
			entries = append(entries, ifdEntry{322, 3, []uint32{uint32(tileN)}}, ifdEntry{323, 3, []uint32{uint32(tileN)}},
				ifdEntry{324, 4, offs}, ifdEntry{325, 4, counts})
		} else {
			entries = append(entries, ifdEntry{273, 4, offs}, ifdEntry{278, 4, []uint32{uint32(stripN)}}, ifdEntry{279, 4, counts})
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].tag < entries[j].tag })
		ifdOff := body.Len()
		// extra data area after IFD
		ifdSize := 2 + 12*len(entries) + 4
		extraOff := ifdOff + ifdSize
		var ifd, extraBuf bytes.Buffer
		tmp2 := make([]byte, 2)
		tmp4 := make([]byte, 4)
		bo.PutUint16(tmp2, uint16(len(entries)))
		ifd.Write(tmp2)
		for _, e := range entries {
			bo.PutUint16(tmp2, e.tag)
			ifd.Write(tmp2)
			bo.PutUint16(tmp2, e.typ)
			ifd.Write(tmp2)
			bo.PutUint32(tmp4, uint32(len(e.vals)))
			ifd.Write(tmp4)
			size := 2
			if e.typ == 4 {
				size = 4
			}
			var valBytes []byte
			for _, v := range e.vals {
				if size == 2 {
					bo.PutUint16(tmp2, uint16(v))
					valBytes = append(valBytes, tmp2...)
				} else {
					bo.PutUint32(tmp4, v)
					valBytes = append(valBytes, tmp4...)
				}
			}
			if len(valBytes) <= 4 {
				for len(valBytes) < 4 {
					valBytes = append(valBytes, 0)
				}
				ifd.Write(valBytes)
			} else {
				bo.PutUint32(tmp4, uint32(extraOff+extraBuf.Len()))
				ifd.Write(tmp4)
				extraBuf.Write(valBytes)
			}
		}
		ifd.Write([]byte{0, 0, 0, 0})
		out := body.Bytes()
		if bo == binary.LittleEndian {
			copy(out, "II\x2A\x00")
		} else {
			copy(out, "MM\x00\x2A")
		}
		bo.PutUint32(out[4:], uint32(ifdOff))
		out = append(out, ifd.Bytes()...)
		out = append(out, extraBuf.Bytes()...)
		os.WriteFile(os.Args[3], out, 0644)
		os.Exit(0)
	}
}

