type ifdEntry struct {
	tag   uint16
	typ   uint16
	vals  []uint32
}

// lzwEncodeTIFF: MSB-first LZW with early change.
func lzwEncodeTIFF(data []byte) []byte {
	var out []byte
	var bits uint32
	var nbits uint
	width := uint(9)
	write := func(code int) {
		bits = bits<<width | uint32(code)
		nbits += width
		for nbits >= 8 {
			out = append(out, byte(bits>>(nbits-8)))
			nbits -= 8
			bits &= (1 << nbits) - 1
		}
	}
	dict := map[string]int{}
	next := 258
	reset := func() {
		dict = map[string]int{}
		for i := 0; i < 256; i++ {
			dict[string([]byte{byte(i)})] = i
		}
		next = 258
		width = 9
	}
	reset()
	write(256)
	w := ""
	for _, c := range data {
		wc := w + string([]byte{c})
		if _, ok := dict[wc]; ok {
			w = wc
			continue
		}
		write(dict[w])
		dict[wc] = next
		next++
		if next+1 > (1<<width) && width < 12 {
			width++
		}
		if next >= 4094 {
			write(256)
			reset()
		}
		w = string([]byte{c})
	}
	if w != "" {
		write(dict[w])
		next++
		if next+1 > (1<<width) && width < 12 {
			width++
		}
	}
	write(257)
	if nbits > 0 {
		out = append(out, byte(bits<<(8-nbits)))
	}
	return out
}

func packBits(data []byte) []byte {
	var out []byte
	for i := 0; i < len(data); {
		// find run
		j := i + 1
		for j < len(data) && data[j] == data[i] && j-i < 128 {
			j++
		}
		if j-i >= 3 {
			out = append(out, byte(int8(-(j - i - 1))), data[i])
			i = j
			continue
		}
		k := i
		for k < len(data) && k-i < 128 {
			if k+2 < len(data) && data[k] == data[k+1] && data[k] == data[k+2] {
				break
			}
			k++
		}
		out = append(out, byte(k-i-1))
		out = append(out, data[i:k]...)
		i = k
	}
	return out
}

