import ctypes, sys, struct
lib = ctypes.CDLL('/usr/lib/x86_64-linux-gnu/libwebp.so.7')
def encode(raw_path, out_path, mode, quality=80.0):
    data = open(raw_path,'rb').read()
    w, h = struct.unpack('<II', data[:8])
    pix = data[8:]
    out = ctypes.POINTER(ctypes.c_uint8)()
    if mode in ('rgb', 'lossless_rgb'):
        rgb = bytearray()
        for i in range(0, len(pix), 4):
            rgb += pix[i:i+3]
        buf = (ctypes.c_uint8 * len(rgb)).from_buffer(rgb)
        if mode == 'rgb':
            lib.WebPEncodeRGB.restype = ctypes.c_size_t
            n = lib.WebPEncodeRGB(buf, w, h, w*3, ctypes.c_float(quality), ctypes.byref(out))
        else:
            lib.WebPEncodeLosslessRGB.restype = ctypes.c_size_t
            n = lib.WebPEncodeLosslessRGB(buf, w, h, w*3, ctypes.byref(out))
    else:
        rgba = bytearray(pix)
        buf = (ctypes.c_uint8 * len(rgba)).from_buffer(rgba)
        if mode == 'rgba':
            lib.WebPEncodeRGBA.restype = ctypes.c_size_t
            n = lib.WebPEncodeRGBA(buf, w, h, w*4, ctypes.c_float(quality), ctypes.byref(out))
        else:
            lib.WebPEncodeLosslessRGBA.restype = ctypes.c_size_t
            n = lib.WebPEncodeLosslessRGBA(buf, w, h, w*4, ctypes.byref(out))
    res = ctypes.string_at(out, n)
    open(out_path, 'wb').write(res)
    print(out_path, n, 'bytes', w, 'x', h)

if __name__ == '__main__':
    q = float(sys.argv[4]) if len(sys.argv) > 4 else 80.0
    encode(sys.argv[1], sys.argv[2], sys.argv[3], q)
