	{-6, 7}, {7, 6}, {-7, 6}, {8, 5}, {7, 7}, {-7, 7}, {8, 6}, {8, 7},
}

func vp8lPrefixValue(b *vp8lBits, code int) int {
	if code < 4 {
		return code + 1
	}
	extra := uint((code - 2) >> 1)
	offset := (2 + (code & 1)) << extra
	return offset + int(b.read(extra)) + 1
}

func divRoundUp(n, bits int) int {
	return (n + (1 << uint(bits)) - 1) >> uint(bits)
}

// decodeVP8LStream decodes an entropy coded image of the given size.
func decodeVP8LStream(b *vp8lBits, xsize, ysize int, level0 bool) ([]uint32, error) {
	cacheBits := 0
	if b.read(1) == 1 {
		cacheBits = int(b.read(4))
		if cacheBits < 1 || cacheBits > 11 {
			return nil, errVP8LInvalidColorCache
		}
	}
	var entropy []uint32
	entropyBits := 0
	entropyXSize := 0
	numGroups := 1
	if level0 && b.read(1) == 1 {
		entropyBits = int(b.read(3)) + 2
		entropyXSize = divRoundUp(xsize, entropyBits)
		var err error
		entropy, err = decodeVP8LStream(b, entropyXSize, divRoundUp(ysize, entropyBits), false)
		if err != nil {
			return nil, err
		}
		for i, v := range entropy {
			g := int(v>>8) & 0xffff
			entropy[i] = uint32(g)
			if g+1 > numGroups {
				numGroups = g + 1
			}
		}
	}
	if b.err != nil {
		return nil, b.err
	}
	cacheSize := 0
	if cacheBits > 0 {
		cacheSize = 1 << uint(cacheBits)
	}
	alphabets := [5]int{256 + 24 + cacheSize, 256, 256, 256, 40}
	groups := make([]vp8lGroup, numGroups)
	for i := range groups {
		for j := 0; j < 5; j++ {
			h, err := readVP8LHuffman(b, alphabets[j])
			if err != nil {
				return nil, err
			}
			groups[i][j] = h
		}
	}

	pix := make([]uint32, xsize*ysize)
	var cache []uint32
	if cacheSize > 0 {
		cache = make([]uint32, cacheSize)
	}
	cacheShift := uint(32 - cacheBits)
	lastCached := 0
	insertUpTo := func(end int) {
		if cache == nil {
			lastCached = end
			return
		}
		for ; lastCached < end; lastCached++ {
			p := pix[lastCached]
			cache[(0x1e35a7bd*p)>>cacheShift] = p
		}
	}
	total := xsize * ysize
	pos := 0
	for pos < total {
		x, y := pos%xsize, pos/xsize
		g := &groups[0]
		if entropy != nil {
			g = &groups[entropy[(y>>uint(entropyBits))*entropyXSize+(x>>uint(entropyBits))]]
		}
		code := g[0].decode(b)
		if b.err != nil {
			return nil, b.err
		}
		switch {
		case code < 256:
			red := g[1].decode(b)
			blue := g[2].decode(b)
			alpha := g[3].decode(b)
			if b.err != nil {
				return nil, b.err
			}
			pix[pos] = uint32(alpha)<<24 | uint32(red)<<16 | uint32(code)<<8 | uint32(blue)
			pos++
		case code < 256+24:
			length := vp8lPrefixValue(b, code-256)
			distSym := g[4].decode(b)
			distCode := vp8lPrefixValue(b, distSym)
			if b.err != nil {
				return nil, b.err
			}
			var dist int
			if distCode > 120 {
				dist = distCode - 120
			} else {
				d := vp8lDistanceMap[distCode-1]
				dist = int(d[0]) + int(d[1])*xsize
				if dist < 1 {
					dist = 1
				}
			}
			if dist > pos || pos+length > total {
				return nil, errVP8LInvalidLZ77
			}
			for i := 0; i < length; i++ {
				pix[pos] = pix[pos-dist]
				pos++
			}
		default:
			insertUpTo(pos)
			idx := code - 280
			if cache == nil || idx >= len(cache) {
				return nil, errVP8LInvalidColorCache
			}
			pix[pos] = cache[idx]
			pos++
		}
		insertUpTo(pos)
	}
	return pix, nil
}

type vp8lTransform struct {
	kind   int
	bits   int
	data   []uint32
	oldW   int
	tableN int
}

func average2(a, b uint32) uint32 {
	return (((a ^ b) & 0xfefefefe) >> 1) + (a & b)
}

func channel(p uint32, s uint) int { return int(p>>s) & 0xff }

func selectPred(l, t, tl uint32) uint32 {
	pa := 0
	pb := 0
	for _, s := range []uint{24, 16, 8, 0} {
		p := channel(l, s) + channel(t, s) - channel(tl, s)
		pl := p - channel(l, s)
		if pl < 0 {
			pl = -pl
		}
		pt := p - channel(t, s)
		if pt < 0 {
			pt = -pt
		}
		pa += pl
		pb += pt
	}
	if pa < pb {
		return l
	}
	return t
}

func clamp255(v int) uint32 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint32(v)
}

func clampAddSubFull(a, b, c uint32) uint32 {
	var out uint32
	for _, s := range []uint{24, 16, 8, 0} {
		out |= clamp255(channel(a, s)+channel(b, s)-channel(c, s)) << s
	}
	return out
}

func clampAddSubHalf(a, b uint32) uint32 {
	var out uint32
	for _, s := range []uint{24, 16, 8, 0} {
		ca := channel(a, s)
		cb := channel(b, s)
		out |= clamp255(ca+(ca-cb)/2) << s
	}
	return out
}

func addPixels(a, b uint32) uint32 {
	ag := (a & 0xff00ff00) + (b & 0xff00ff00)
	rb := (a & 0x00ff00ff) + (b & 0x00ff00ff)
	return (ag & 0xff00ff00) | (rb & 0x00ff00ff)
}

func inversePredictor(t *vp8lTransform, pix []uint32, w, h int) {
	if w == 0 || h == 0 {
		return
	}
	pix[0] = addPixels(pix[0], 0xff000000)
	for x := 1; x < w; x++ {
		pix[x] = addPixels(pix[x], pix[x-1])
	}
	tilesPerRow := divRoundUp(w, t.bits)
	for y := 1; y < h; y++ {
		row := y * w
		pix[row] = addPixels(pix[row], pix[row-w])
		for x := 1; x < w; x++ {
			mode := (t.data[(y>>uint(t.bits))*tilesPerRow+(x>>uint(t.bits))] >> 8) & 0xf
			i := row + x
			l := pix[i-1]
			tp := pix[i-w]
			tl := pix[i-w-1]
			tr := pix[i-w+1]
			var pred uint32
			switch mode {
			case 0:
				pred = 0xff000000
			case 1:
				pred = l
			case 2:
				pred = tp
			case 3:
				pred = tr
			case 4:
				pred = tl
			case 5:
				pred = average2(average2(l, tr), tp)
			case 6:
				pred = average2(l, tl)
			case 7:
				pred = average2(l, tp)
			case 8:
				pred = average2(tl, tp)
			case 9:
				pred = average2(tp, tr)
			case 10:
				pred = average2(average2(l, tl), average2(tp, tr))
			case 11:
				pred = selectPred(l, tp, tl)
			case 12:
				pred = clampAddSubFull(l, tp, tl)
			case 13:
				pred = clampAddSubHalf(average2(l, tp), tl)
			default:
				pred = 0xff000000
			}
			pix[i] = addPixels(pix[i], pred)
		}
	}
}

func colorDelta(t, c uint8) int {
	return (int(int8(t)) * int(int8(c))) >> 5
}

func inverseColorTransform(t *vp8lTransform, pix []uint32, w, h int) {
	tilesPerRow := divRoundUp(w, t.bits)
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			e := t.data[(y>>uint(t.bits))*tilesPerRow+(x>>uint(t.bits))]
			g2r := uint8(e)
			g2b := uint8(e >> 8)
			r2b := uint8(e >> 16)
			p := pix[y*w+x]
			green := uint8(p >> 8)
			red := uint8(p >> 16)
			blue := uint8(p)
			red = uint8(int(red) + colorDelta(g2r, green))
			blue = uint8(int(blue) + colorDelta(g2b, green))
			blue = uint8(int(blue) + colorDelta(r2b, red))
			pix[y*w+x] = (p & 0xff00ff00) | uint32(red)<<16 | uint32(blue)
		}
	}
}

func decodeVP8L(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	b := &vp8lBits{data: data}
	if b.read(8) != 0x2f {
		return nil, errVP8LInvalidHeader
	}
	width := int(b.read(14)) + 1
	height := int(b.read(14)) + 1
	b.read(1) // alpha hint
	if b.read(3) != 0 {
		return nil, errVP8LInvalidVersion
	}
	if b.err != nil {
		return nil, b.err
	}

	xsize := width
	var transforms []*vp8lTransform
	seen := map[int]bool{}
	for b.read(1) == 1 {
		kind := int(b.read(2))
		if seen[kind] {
			return nil, errVP8LRepeatedTransform
		}
		seen[kind] = true
		t := &vp8lTransform{kind: kind, oldW: xsize}
		switch kind {
		case 0, 1:
			t.bits = int(b.read(3)) + 2
			d, err := decodeVP8LStream(b, divRoundUp(xsize, t.bits), divRoundUp(height, t.bits), false)
			if err != nil {
				return nil, err
			}
			t.data = d
		case 2:
		case 3:
			n := int(b.read(8)) + 1
			t.tableN = n
			bits := 0
			switch {
			case n <= 2:
				bits = 3
			case n <= 4:
				bits = 2
			case n <= 16:
				bits = 1
			}
			t.bits = bits
			d, err := decodeVP8LStream(b, n, 1, false)
			if err != nil {
				return nil, err
			}
			for i := 1; i < len(d); i++ {
				d[i] = addPixels(d[i], d[i-1])
			}
			t.data = d
			xsize = divRoundUp(xsize, bits)
		}
		transforms = append(transforms, t)
		if b.err != nil {
			return nil, b.err
		}
	}
	pix, err := decodeVP8LStream(b, xsize, height, true)
	if err != nil {
		return nil, err
	}

	for i := len(transforms) - 1; i >= 0; i-- {
		t := transforms[i]
		switch t.kind {
		case 0:
			inversePredictor(t, pix, t.oldW, height)
		case 1:
			inverseColorTransform(t, pix, t.oldW, height)
		case 2:
			for j, p := range pix {
				g := (p >> 8) & 0xff
				pix[j] = (p & 0xff00ff00) | ((((p >> 16) + g) & 0xff) << 16) | ((p + g) & 0xff)
			}
		case 3:
			out := make([]uint32, t.oldW*height)
			bitsPer := 8 >> uint(t.bits)
			perByte := 1 << uint(t.bits)
			mask := uint32(1<<uint(bitsPer) - 1)
			for y := 0; y < height; y++ {
				for x := 0; x < t.oldW; x++ {
					packed := pix[y*xsize+x/perByte]
					idx := (packed >> 8) & 0xff
					if t.bits > 0 {
						idx = (idx >> uint(bitsPer*(x%perByte))) & mask
					}
					var c uint32
					if int(idx) < len(t.data) {
						c = t.data[idx]
					}
					out[y*t.oldW+x] = c
				}
			}
			pix = out
			xsize = t.oldW
		}
	}

	img := image.NewNRGBA(image.Rect(0, 0, width, height))
	for i, p := range pix {
		img.Pix[4*i+0] = uint8(p >> 16)
		img.Pix[4*i+1] = uint8(p >> 8)
		img.Pix[4*i+2] = uint8(p)
		img.Pix[4*i+3] = uint8(p >> 24)
	}
	return img, nil
}
