type riffReader struct {
	data []byte
	pos  int
	end  int
}

func newRIFF(data []byte) (string, *riffReader, error) {
	if len(data) < 8 {
		return "", nil, errRIFFMissingHeader
	}
	if string(data[0:4]) != "RIFF" {
		return "", nil, errRIFFMissingHeader
	}
	size := int(le32(data[4:8]))
	if len(data) < 12 {
		return "", nil, errRIFFShortData
	}
	if size < 4 {
		return "", nil, errRIFFShortData
	}
	end := 8 + size
	form := string(data[8:12])
	r := &riffReader{data: data, pos: 12, end: end}
	return form, r, nil
}

func (r *riffReader) next() (string, []byte, error) {
	if r.pos >= r.end {
		return "", nil, io.EOF
	}
	if r.pos+8 > r.end || r.pos+8 > len(r.data) {
		return "", nil, errRIFFShortHeader
	}
	id := string(r.data[r.pos : r.pos+4])
	n := int(le32(r.data[r.pos+4 : r.pos+8]))
	start := r.pos + 8
	if n < 0 || start+n > r.end {
		return "", nil, errRIFFShortData
	}
	stop := start + n
	if stop > len(r.data) {
		r.pos = r.end
		return id, r.data[start:], nil
	}
	r.pos = stop
	if n%2 == 1 {
		if r.pos >= r.end {
			r.pos = r.end
		} else {
			r.pos++
		}
	}
	return id, r.data[start:stop], nil
