package main

import (
	"errors"
	"image"
	"io"
)

// VP8 key frame decoder (RFC 6386) producing 4:2:0 YCbCr images.

var (
	errVP8InvalidFormat = errors.New("vp8: invalid format")
	errVP8Unsupported   = errors.New("vp8: unsupported feature")
)

// boolean entropy decoder
type vp8Bool struct {
	data     []byte
	pos      int
	value    uint32
	rng      uint32
	bitCount int
	eof      bool
}

func (d *vp8Bool) init(data []byte) {
	d.data = data
	d.pos = 0
	d.value = 0
	for i := 0; i < 2; i++ {
		d.value = d.value<<8 | uint32(d.nextByte())
	}
	d.rng = 255
	d.bitCount = 0
}

func (d *vp8Bool) nextByte() byte {
	if d.pos >= len(d.data) {
		d.eof = true
		return 0
	}
	b := d.data[d.pos]
	d.pos++
	return b
}

func (d *vp8Bool) bit(prob uint8) bool {
	split := 1 + (((d.rng - 1) * uint32(prob)) >> 8)
	bigSplit := split << 8
	var ret bool
	if d.value >= bigSplit {
		ret = true
		d.rng -= split
		d.value -= bigSplit
	} else {
		d.rng = split
	}
	for d.rng < 128 {
		d.value <<= 1
		d.rng <<= 1
		d.bitCount++
		if d.bitCount == 8 {
			d.bitCount = 0
			d.value |= uint32(d.nextByte())
		}
	}
	return ret
}

func (d *vp8Bool) flag() bool { return d.bit(128) }

func (d *vp8Bool) literal(n int) int {
	v := 0
	for i := 0; i < n; i++ {
		v <<= 1
		if d.bit(128) {
			v |= 1
		}
	}
	return v
}

func (d *vp8Bool) signed(n int) int {
	v := d.literal(n)
	if d.flag() {
		return -v
	}
	return v
}

const (
	bDC = iota
	bTM
	bVE
	bHE
	bRD
	bVR
	bLD
	bVL
	bHD
	bHU
	bDCNoTop
	bDCNoLeft
	bDCNoTopLeft
)

var vp8Bands = [17]int{0, 1, 2, 3, 6, 4, 5, 6, 6, 6, 6, 6, 6, 6, 6, 7, 0}
var vp8Zigzag = [16]int{0, 1, 4, 8, 5, 2, 3, 6, 9, 12, 13, 10, 7, 11, 14, 15}

var (
	vp8Cat3 = []uint8{173, 148, 140}
	vp8Cat4 = []uint8{176, 155, 140, 135}
	vp8Cat5 = []uint8{180, 157, 141, 134, 130}
	vp8Cat6 = []uint8{254, 254, 243, 230, 196, 177, 153, 140, 133, 130, 129}
)

type vp8Quant struct {
	y1, y2, uv [2]int32
}

type vp8FInfo struct {
	limit, ilevel, hevThresh int
	inner                    bool
}

type vp8MBInfo struct {
	isI4x4  bool
	imodes  [16]int
	uvmode  int
	segment int
	skip    bool
}

type vp8Decoder struct {
	width, height int
	mbw, mbh      int

	useSegment    bool
	updateMap     bool
	absoluteDelta bool
	quantizer     [4]int
	filterStr     [4]int
	segProbs      [3]uint8

	simple     bool
	level      int
	sharpness  int
	useLFDelta bool
	refDelta   [4]int
	modeDelta  [4]int
	filterType int

	parts []vp8Bool
	quant [4]vp8Quant
	probs [4][8][3][11]uint8

	useSkip bool
	skipP   uint8

	// planes
	y, u, v          []uint8
	yStride, cStride int
}

func decodeVP8(data []byte) (*image.YCbCr, error) {
	if len(data) < 10 {
		return nil, io.ErrUnexpectedEOF
	}
	bits := uint32(data[0]) | uint32(data[1])<<8 | uint32(data[2])<<16
	keyFrame := bits&1 == 0
	profile := (bits >> 1) & 7
	show := (bits >> 4) & 1
	partLen := int(bits >> 5)
	if !keyFrame {
		return nil, errVP8Unsupported
	}
	if profile > 3 || show == 0 {
		return nil, errVP8InvalidFormat
	}
	if data[3] != 0x9d || data[4] != 0x01 || data[5] != 0x2a {
		return nil, errVP8InvalidFormat
	}
	d := &vp8Decoder{}
	d.width = int(uint32(data[7])<<8|uint32(data[6])) & 0x3fff
	d.height = int(uint32(data[9])<<8|uint32(data[8])) & 0x3fff
	d.mbw = (d.width + 15) >> 4
	d.mbh = (d.height + 15) >> 4
	rest := data[10:]
	if partLen > len(rest) {
		return nil, io.ErrUnexpectedEOF
	}
	var br vp8Bool
	br.init(rest[:partLen])

	br.flag() // color space
	br.flag() // clamping type

	// segment header
	d.useSegment = br.flag()
	if d.useSegment {
		d.updateMap = br.flag()
		if br.flag() {
			d.absoluteDelta = br.flag()
			for s := 0; s < 4; s++ {
				if br.flag() {
					d.quantizer[s] = br.signed(7)
				}
			}
			for s := 0; s < 4; s++ {
				if br.flag() {
					d.filterStr[s] = br.signed(6)
				}
			}
		}
		if d.updateMap {
			for s := 0; s < 3; s++ {
				if br.flag() {
					d.segProbs[s] = uint8(br.literal(8))
				} else {
					d.segProbs[s] = 255
				}
			}
		}
	}

	// filter header
	d.simple = br.flag()
	d.level = br.literal(6)
	d.sharpness = br.literal(3)
	d.useLFDelta = br.flag()
	if d.useLFDelta {
		if br.flag() {
			for i := 0; i < 4; i++ {
				if br.flag() {
					d.refDelta[i] = br.signed(6)
				}
			}
			for i := 0; i < 4; i++ {
				if br.flag() {
					d.modeDelta[i] = br.signed(6)
				}
			}
		}
	}
	switch {
	case d.level == 0:
		d.filterType = 0
	case d.simple:
		d.filterType = 1
	default:
		d.filterType = 2
	}

	// partitions
	numParts := 1 << uint(br.literal(2))
	buf := rest[partLen:]
	lastPart := numParts - 1
	if len(buf) < 3*lastPart {
		return nil, io.ErrUnexpectedEOF
	}
	sizeLeft := len(buf) - 3*lastPart
	partStart := 3 * lastPart
	d.parts = make([]vp8Bool, numParts)
	for p := 0; p < lastPart; p++ {
		psize := int(buf[3*p]) | int(buf[3*p+1])<<8 | int(buf[3*p+2])<<16
		if psize > sizeLeft {
			psize = sizeLeft
		}
		d.parts[p].init(buf[partStart : partStart+psize])
		partStart += psize
		sizeLeft -= psize
	}
	d.parts[lastPart].init(buf[partStart : partStart+sizeLeft])

	// quantizers
	baseQ := br.literal(7)
	opt := func() int {
		if br.flag() {
			return br.signed(4)
		}
		return 0
	}
	dqy1dc := opt()
	dqy2dc := opt()
	dqy2ac := opt()
	dquvdc := opt()
	dquvac := opt()
	clip := func(v, m int) int {
		if v < 0 {
			return 0
		}
		if v > m {
			return m
		}
		return v
	}
	for i := 0; i < 4; i++ {
		var q int
		if d.useSegment {
			q = d.quantizer[i]
			if !d.absoluteDelta {
				q += baseQ
			}
		} else {
			if i > 0 {
				d.quant[i] = d.quant[0]
				continue
			}
			q = baseQ
		}
		m := &d.quant[i]
		m.y1[0] = vp8DcTable[clip(q+dqy1dc, 127)]
		m.y1[1] = vp8AcTable[clip(q, 127)]
		m.y2[0] = vp8DcTable[clip(q+dqy2dc, 127)] * 2
		m.y2[1] = (vp8AcTable[clip(q+dqy2ac, 127)] * 101581) >> 16
		if m.y2[1] < 8 {
			m.y2[1] = 8
		}
		m.uv[0] = vp8DcTable[clip(q+dquvdc, 117)]
		m.uv[1] = vp8AcTable[clip(q+dquvac, 127)]
	}

	br.flag() // refresh entropy probs (ignored)

	for t := 0; t < 4; t++ {
		for b := 0; b < 8; b++ {
			for c := 0; c < 3; c++ {
				for p := 0; p < 11; p++ {
					if br.bit(vp8CoeffUpdateProbs[t][b][c][p]) {
						d.probs[t][b][c][p] = uint8(br.literal(8))
					} else {
						d.probs[t][b][c][p] = vp8CoeffProbs0[t][b][c][p]
					}
				}
			}
		}
	}
	d.useSkip = br.flag()
	if d.useSkip {
		d.skipP = uint8(br.literal(8))
	}

	return d.decodeFrame(&br)
}

func (d *vp8Decoder) parseModes(br *vp8Bool, mb *vp8MBInfo, top []int, left *[4]int) {
	if d.updateMap {
		if !br.bit(d.segProbs[0]) {
			if br.bit(d.segProbs[1]) {
				mb.segment = 1
			} else {
				mb.segment = 0
			}
		} else {
			if br.bit(d.segProbs[2]) {
				mb.segment = 3
			} else {
				mb.segment = 2
			}
		}
	} else {
		mb.segment = 0
	}
	if d.useSkip {
		mb.skip = br.bit(d.skipP)
	}
	mb.isI4x4 = !br.bit(145)
	if !mb.isI4x4 {
		var ymode int
		if br.bit(156) {
			if br.bit(128) {
				ymode = bTM
			} else {
				ymode = bHE
			}
		} else {
			if br.bit(163) {
				ymode = bVE
			} else {
				ymode = bDC
			}
		}
		mb.imodes[0] = ymode
		for i := 0; i < 4; i++ {
			top[i] = ymode
			left[i] = ymode
		}
	} else {
		for y := 0; y < 4; y++ {
			ymode := left[y]
			for x := 0; x < 4; x++ {
				prob := &vp8BModeProbs[top[x]][ymode]
				switch {
				case !br.bit(prob[0]):
					ymode = bDC
				case !br.bit(prob[1]):
					ymode = bTM
				case !br.bit(prob[2]):
					ymode = bVE
				case !br.bit(prob[3]):
					if !br.bit(prob[4]) {
						ymode = bHE
					} else if !br.bit(prob[5]) {
						ymode = bRD
					} else {
						ymode = bVR
					}
				default:
					if !br.bit(prob[6]) {
						ymode = bLD
					} else if !br.bit(prob[7]) {
						ymode = bVL
					} else if !br.bit(prob[8]) {
						ymode = bHD
					} else {
						ymode = bHU
					}
				}
				top[x] = ymode
				mb.imodes[y*4+x] = ymode
			}
			left[y] = ymode
		}
	}
	switch {
	case !br.bit(142):
		mb.uvmode = bDC
	case !br.bit(114):
		mb.uvmode = bVE
	case br.bit(183):
		mb.uvmode = bTM
	default:
		mb.uvmode = bHE
	}
}

func (d *vp8Decoder) getLargeValue(br *vp8Bool, p *[11]uint8) int {
	var v int
	if !br.bit(p[3]) {
		if !br.bit(p[4]) {
			v = 2
		} else {
			v = 3
			if br.bit(p[5]) {
				v++
			}
		}
	} else {
		if !br.bit(p[6]) {
			if !br.bit(p[7]) {
				v = 5
				if br.bit(159) {
					v++
				}
			} else {
				v = 7
				if br.bit(165) {
					v += 2
				}
				if br.bit(145) {
					v++
				}
			}
		} else {
			bit1 := 0
			if br.bit(p[8]) {
				bit1 = 1
			}
			bit0 := 0
			if br.bit(p[9+bit1]) {
				bit0 = 1
			}
			cat := 2*bit1 + bit0
			var tab []uint8
			switch cat {
			case 0:
				tab = vp8Cat3
			case 1:
				tab = vp8Cat4
			case 2:
				tab = vp8Cat5
			default:
				tab = vp8Cat6
			}
			v = 0
			for _, pr := range tab {
				v += v
				if br.bit(pr) {
					v++
				}
			}
			v += 3 + (8 << uint(cat))
		}
	}
	return v
}

// getCoeffs decodes one 4x4 block of coefficients; it returns the index
// following the last non-zero coefficient.
func (d *vp8Decoder) getCoeffs(br *vp8Bool, t int, ctx int, dq [2]int32, n int, out []int16) int {
	p := &d.probs[t][vp8Bands[n]][ctx]
	for ; n < 16; n++ {
		if !br.bit(p[0]) {
			return n
		}
		for !br.bit(p[1]) {
			n++
			if n == 16 {
				return 16
			}
			p = &d.probs[t][vp8Bands[n]][0]
		}
		var v int
		next := &d.probs[t][vp8Bands[n+1]]
		if !br.bit(p[2]) {
			v = 1
			p = &next[1]
		} else {
			v = d.getLargeValue(br, p)
			p = &next[2]
		}
		if br.flag() {
			v = -v
		}
		q := dq[0]
		if n > 0 {
			q = dq[1]
		}
		out[vp8Zigzag[n]] = int16(int32(v) * q)
	}
	return 16
}

func transformWHT(in []int16, out []int16) {
	var tmp [16]int
	for i := 0; i < 4; i++ {
		a0 := int(in[0+i]) + int(in[12+i])
		a1 := int(in[4+i]) + int(in[8+i])
		a2 := int(in[4+i]) - int(in[8+i])
		a3 := int(in[0+i]) - int(in[12+i])
		tmp[0+i] = a0 + a1
		tmp[8+i] = a0 - a1
		tmp[4+i] = a3 + a2
		tmp[12+i] = a3 - a2
	}
	o := 0
	for i := 0; i < 4; i++ {
		dc := tmp[0+i*4] + 3
		a0 := dc + tmp[3+i*4]
		a1 := tmp[1+i*4] + tmp[2+i*4]
		a2 := tmp[1+i*4] - tmp[2+i*4]
		a3 := dc - tmp[3+i*4]
		out[o+0] = int16((a0 + a1) >> 3)
		out[o+16] = int16((a3 + a2) >> 3)
		out[o+32] = int16((a0 - a1) >> 3)
		out[o+48] = int16((a3 - a2) >> 3)
		o += 64
	}
}

func clip8(v int) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v)
}

func mul1(a int) int { return ((a * 20091) >> 16) + a }
func mul2(a int) int { return (a * 35468) >> 16 }

// idctAdd adds the inverse DCT of in to the 4x4 block at dst.
func idctAdd(in []int16, dst []uint8, off, stride int) {
	var c [16]int
	t := 0
	for i := 0; i < 4; i++ {
		a := int(in[i]) + int(in[8+i])
		b := int(in[i]) - int(in[8+i])
		cc := mul2(int(in[4+i])) - mul1(int(in[12+i]))
		dd := mul1(int(in[4+i])) + mul2(int(in[12+i]))
		c[t+0] = a + dd
		c[t+1] = b + cc
		c[t+2] = b - cc
		c[t+3] = a - dd
		t += 4
	}
	for i := 0; i < 4; i++ {
		dc := c[i] + 4
		a := dc + c[8+i]
		b := dc - c[8+i]
		cc := mul2(c[4+i]) - mul1(c[12+i])
		dd := mul1(c[4+i]) + mul2(c[12+i])
		row := off + i*stride
		dst[row+0] = clip8(int(dst[row+0]) + ((a + dd) >> 3))
		dst[row+1] = clip8(int(dst[row+1]) + ((b + cc) >> 3))
		dst[row+2] = clip8(int(dst[row+2]) + ((b - cc) >> 3))
		dst[row+3] = clip8(int(dst[row+3]) + ((a - dd) >> 3))
	}
}

func avg3(a, b, c int) uint8 { return uint8((a + 2*b + c + 2) >> 2) }
func avg2(a, b int) uint8    { return uint8((a + b + 1) >> 1) }

// work buffer layout (stride bps): row 0 holds the above samples, column 0
// the left samples.
const bps = 32

type vp8Work struct {
	buf [bps * 17]uint8
}

// pixel accessor relative to block origin at (ox, oy) in work buffer
func predict4(w []uint8, o int, mode int) {
	at := func(x, y int) int { return int(w[o+x+y*bps]) }
	set := func(x, y int, v uint8) { w[o+x+y*bps] = v }
	top := func(i int) int { return at(i, -1) }
	left := func(i int) int { return at(-1, i) }
	switch mode {
	case bDC:
		dc := 4
		for i := 0; i < 4; i++ {
			dc += top(i) + left(i)
		}
		dc >>= 3
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, uint8(dc))
			}
		}
	case bTM:
		tl := at(-1, -1)
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, clip8(top(x)+left(y)-tl))
			}
		}
	case bVE:
		vals := [4]uint8{
			avg3(top(-1), top(0), top(1)),
			avg3(top(0), top(1), top(2)),
			avg3(top(1), top(2), top(3)),
			avg3(top(2), top(3), top(4)),
		}
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, vals[x])
			}
		}
	case bHE:
		A, B, C, D, E := at(-1, -1), left(0), left(1), left(2), left(3)
		rows := [4]uint8{avg3(A, B, C), avg3(B, C, D), avg3(C, D, E), avg3(D, E, E)}
		for y := 0; y < 4; y++ {
			for x := 0; x < 4; x++ {
				set(x, y, rows[y])
			}
		}
	case bRD:
		I, J, K, L := left(0), left(1), left(2), left(3)
		X := at(-1, -1)
		A, B, C, D := top(0), top(1), top(2), top(3)
		set(0, 3, avg3(J, K, L))
		v := avg3(I, J, K)
		set(1, 3, v)
		set(0, 2, v)
		v = avg3(X, I, J)
		set(2, 3, v)
		set(1, 2, v)
		set(0, 1, v)
		v = avg3(A, X, I)
		set(3, 3, v)
		set(2, 2, v)
		set(1, 1, v)
		set(0, 0, v)
		v = avg3(B, A, X)
		set(3, 2, v)
		set(2, 1, v)
		set(1, 0, v)
		v = avg3(C, B, A)
		set(3, 1, v)
		set(2, 0, v)
		set(3, 0, avg3(D, C, B))
	case bLD:
		A, B, C, D := top(0), top(1), top(2), top(3)
		E, F, G, H := top(4), top(5), top(6), top(7)
		set(0, 0, avg3(A, B, C))
		v := avg3(B, C, D)
		set(1, 0, v)
		set(0, 1, v)
		v = avg3(C, D, E)
		set(2, 0, v)
		set(1, 1, v)
		set(0, 2, v)
		v = avg3(D, E, F)
		set(3, 0, v)
		set(2, 1, v)
		set(1, 2, v)
		set(0, 3, v)
		v = avg3(E, F, G)
		set(3, 1, v)
		set(2, 2, v)
		set(1, 3, v)
		v = avg3(F, G, H)
		set(3, 2, v)
		set(2, 3, v)
		set(3, 3, avg3(G, H, H))
	case bVR:
		I, J, K := left(0), left(1), left(2)
		X := at(-1, -1)
		A, B, C, D := top(0), top(1), top(2), top(3)
		v := avg2(X, A)
		set(0, 0, v)
		set(1, 2, v)
		v = avg2(A, B)
		set(1, 0, v)
		set(2, 2, v)
		v = avg2(B, C)
		set(2, 0, v)
		set(3, 2, v)
		set(3, 0, avg2(C, D))
		set(0, 3, avg3(K, J, I))
		set(0, 2, avg3(J, I, X))
		v = avg3(I, X, A)
		set(0, 1, v)
		set(1, 3, v)
		v = avg3(X, A, B)
		set(1, 1, v)
		set(2, 3, v)
		v = avg3(A, B, C)
		set(2, 1, v)
		set(3, 3, v)
		set(3, 1, avg3(B, C, D))
	case bVL:
		A, B, C, D := top(0), top(1), top(2), top(3)
		E, F, G, H := top(4), top(5), top(6), top(7)
		set(0, 0, avg2(A, B))
		v := avg2(B, C)
		set(1, 0, v)
		set(0, 2, v)
		v = avg2(C, D)
		set(2, 0, v)
		set(1, 2, v)
		v = avg2(D, E)
		set(3, 0, v)
		set(2, 2, v)
		set(0, 1, avg3(A, B, C))
		v = avg3(B, C, D)
		set(1, 1, v)
		set(0, 3, v)
		v = avg3(C, D, E)
		set(2, 1, v)
		set(1, 3, v)
		v = avg3(D, E, F)
		set(3, 1, v)
		set(2, 3, v)
		set(3, 2, avg3(E, F, G))
		set(3, 3, avg3(F, G, H))
	case bHU:
		I, J, K, L := left(0), left(1), left(2), left(3)
		set(0, 0, avg2(I, J))
		v := avg2(J, K)
		set(2, 0, v)
		set(0, 1, v)
		v = avg2(K, L)
		set(2, 1, v)
		set(0, 2, v)
		set(1, 0, avg3(I, J, K))
		v = avg3(J, K, L)
		set(3, 0, v)
		set(1, 1, v)
		v = avg3(K, L, L)
		set(3, 1, v)
		set(1, 2, v)
		lv := uint8(L)
		set(3, 2, lv)
		set(2, 2, lv)
		set(0, 3, lv)
		set(1, 3, lv)
		set(2, 3, lv)
		set(3, 3, lv)
	case bHD:
		I, J, K, L := left(0), left(1), left(2), left(3)
		X := at(-1, -1)
		A, B, C := top(0), top(1), top(2)
		v := avg2(I, X)
		set(0, 0, v)
		set(2, 1, v)
		v = avg2(J, I)
		set(0, 1, v)
		set(2, 2, v)
		v = avg2(K, J)
		set(0, 2, v)
		set(2, 3, v)
		set(0, 3, avg2(L, K))
		set(3, 0, avg3(A, B, C))
		set(2, 0, avg3(X, A, B))
		v = avg3(I, X, A)
		set(1, 0, v)
		set(3, 1, v)
		v = avg3(J, I, X)
		set(1, 1, v)
		set(3, 2, v)
		v = avg3(K, J, I)
		set(1, 2, v)
		set(3, 3, v)
		set(1, 3, avg3(L, K, J))
	}
}

// predictBlock handles 16x16 luma and 8x8 chroma prediction.
func predictBlock(w []uint8, o int, size int, mode int) {
	at := func(x, y int) int { return int(w[o+x+y*bps]) }
	fill := func(v uint8) {
		for y := 0; y < size; y++ {
			for x := 0; x < size; x++ {
				w[o+x+y*bps] = v
			}
		}
	}
	shift := uint(4)
	if size == 16 {
		shift = 5
	}
	switch mode {
	case bDC:
		dc := size
		for i := 0; i < size; i++ {
			dc += at(i, -1) + at(-1, i)
		}
		fill(uint8(dc >> shift))
	case bDCNoTop:
		dc := size >> 1
		for i := 0; i < size; i++ {
			dc += at(-1, i)
		}
		fill(uint8(dc >> (shift - 1)))
	case bDCNoLeft:
		dc := size >> 1
		for i := 0; i < size; i++ {
			dc += at(i, -1)
		}
		fill(uint8(dc >> (shift - 1)))
	case bDCNoTopLeft:
		fill(0x80)
	case bTM:
		tl := at(-1, -1)
		for y := 0; y < size; y++ {
			for x := 0; x < size; x++ {
				w[o+x+y*bps] = clip8(at(x, -1) + at(-1, y) - tl)
			}
		}
	case bVE:
		for y := 0; y < size; y++ {
			for x := 0; x < size; x++ {
				w[o+x+y*bps] = w[o+x-bps]
			}
		}
	case bHE:
		for y := 0; y < size; y++ {
			for x := 0; x < size; x++ {
				w[o+x+y*bps] = w[o-1+y*bps]
			}
		}
	}
}

func checkMode(mbx, mby, mode int) int {
	if mode == bDC {
		if mbx == 0 {
			if mby == 0 {
				return bDCNoTopLeft
			}
			return bDCNoLeft
		}
		if mby == 0 {
			return bDCNoTop
		}
	}
	return mode
}

func (d *vp8Decoder) decodeFrame(br *vp8Bool) (*image.YCbCr, error) {
	d.yStride = 16 * d.mbw
	d.cStride = 8 * d.mbw
	img := image.NewYCbCr(image.Rect(0, 0, 16*d.mbw, 16*d.mbh), image.YCbCrSubsampleRatio420)
	d.y, d.u, d.v = img.Y, img.Cb, img.Cr
	d.yStride, d.cStride = img.YStride, img.CStride

	// filter strengths
	var fstr [4][2]vp8FInfo
	if d.filterType > 0 {
		for s := 0; s < 4; s++ {
			var base int
			if d.useSegment {
				base = d.filterStr[s]
				if !d.absoluteDelta {
					base += d.level
				}
			} else {
				base = d.level
			}
			for i4 := 0; i4 <= 1; i4++ {
				info := &fstr[s][i4]
				level := base
				if d.useLFDelta {
					level += d.refDelta[0]
					if i4 == 1 {
						level += d.modeDelta[0]
					}
				}
				if level < 0 {
					level = 0
				} else if level > 63 {
					level = 63
				}
				if level > 0 {
					ilevel := level
					if d.sharpness > 0 {
						if d.sharpness > 4 {
							ilevel >>= 2
						} else {
							ilevel >>= 1
						}
						if ilevel > 9-d.sharpness {
							ilevel = 9 - d.sharpness
						}
					}
					if ilevel < 1 {
						ilevel = 1
					}
					info.ilevel = ilevel
					info.limit = 2*level + ilevel
					switch {
					case level >= 40:
						info.hevThresh = 2
					case level >= 15:
						info.hevThresh = 1
					default:
						info.hevThresh = 0
					}
				} else {
					info.limit = 0
				}
				info.inner = i4 == 1
			}
		}
	}

	// contexts
	intraT := make([]int, 4*d.mbw)
	nzTop := make([]uint32, d.mbw)
	nzDCTop := make([]uint32, d.mbw)
	topY := make([]uint8, 16*d.mbw)
	topU := make([]uint8, 8*d.mbw)
	topV := make([]uint8, 8*d.mbw)
	finfo := make([]vp8FInfo, d.mbw*d.mbh)

	var coeffs [384]int16
	var work [bps * 17]uint8 // luma: row 0 = above, rows 1..16 = block
	var cwork [2][bps * 9]uint8

	mbs := make([]vp8MBInfo, d.mbw)
	for mby := 0; mby < d.mbh; mby++ {
		var intraL [4]int
		for i := range intraL {
			intraL[i] = bDC
		}
		if mby == 0 {
			for i := range intraT {
				intraT[i] = bDC
			}
		}
		// parse modes for the whole row
		for mbx := 0; mbx < d.mbw; mbx++ {
			mbs[mbx] = vp8MBInfo{}
			d.parseModes(br, &mbs[mbx], intraT[4*mbx:4*mbx+4], &intraL)
		}
		tokenBr := &d.parts[mby&(len(d.parts)-1)]
		var nzLeft, nzDCLeft uint32

		// left border init
		const yo = 1 + bps // offset of block origin (x=0,y=0) => index 1+bps? we use column 0 as left
		for mbx := 0; mbx < d.mbw; mbx++ {
			mb := &mbs[mbx]
			// residuals
			for i := range coeffs {
				coeffs[i] = 0
			}
			skip := false
			if d.useSkip {
				skip = mb.skip
			}
			var nonZeroY, nonZeroUV uint32
			if !skip {
				nonZeroY, nonZeroUV = d.parseResiduals(tokenBr, mb, &coeffs, &nzTop[mbx], &nzLeft, &nzDCTop[mbx], &nzDCLeft)
				skip = nonZeroY|nonZeroUV == 0
			} else {
				nzTop[mbx] = 0
				nzLeft = 0
				if !mb.isI4x4 {
					nzDCTop[mbx] = 0
					nzDCLeft = 0
				}
			}
			if d.filterType > 0 {
				f := fstr[mb.segment][b2i(mb.isI4x4)]
				f.inner = f.inner || !skip
				finfo[mby*d.mbw+mbx] = f
			}

			// set up work buffers: luma block origin at (1, 1) within work
			d.setupWork(work[:], 16, mbx, mby, d.y, d.yStride, topY, true)
			d.setupWork(cwork[0][:], 8, mbx, mby, d.u, d.cStride, topU, false)
			d.setupWork(cwork[1][:], 8, mbx, mby, d.v, d.cStride, topV, false)

			o := 1 + bps
			if mb.isI4x4 {
				// top right samples
				for n := 0; n < 16; n++ {
					bx, by := n&3, n>>2
					bo := o + bx*4 + by*4*bps
					predict4(work[:], bo, mb.imodes[n])
					if nonZeroY&(0x80000000>>uint(2*n))&0 != 0 || hasCoeffs(coeffs[n*16:n*16+16]) {
						idctAdd(coeffs[n*16:n*16+16], work[:], bo, bps)
					}
				}
			} else {
				predictBlock(work[:], o, 16, checkMode(mbx, mby, mb.imodes[0]))
				for n := 0; n < 16; n++ {
					if hasCoeffs(coeffs[n*16 : n*16+16]) {
						bx, by := n&3, n>>2
						idctAdd(coeffs[n*16:n*16+16], work[:], o+bx*4+by*4*bps, bps)
					}
				}
			}
			uvMode := checkMode(mbx, mby, mb.uvmode)
			for ch := 0; ch < 2; ch++ {
				predictBlock(cwork[ch][:], o, 8, uvMode)
				base := 256 + ch*64
				for n := 0; n < 4; n++ {
					c := coeffs[base+n*16 : base+n*16+16]
					if hasCoeffs(c) {
						bx, by := n&1, n>>1
						idctAdd(c, cwork[ch][:], o+bx*4+by*4*bps, bps)
					}
				}
			}
			// store results into the frame
			for y := 0; y < 16; y++ {
				copy(d.y[(mby*16+y)*d.yStride+mbx*16:], work[o+y*bps:o+y*bps+16])
			}
			for y := 0; y < 8; y++ {
				copy(d.u[(mby*8+y)*d.cStride+mbx*8:], cwork[0][o+y*bps:o+y*bps+8])
				copy(d.v[(mby*8+y)*d.cStride+mbx*8:], cwork[1][o+y*bps:o+y*bps+8])
			}
		}
		// stash bottom rows as top samples for the next MB row
		for mbx := 0; mbx < d.mbw; mbx++ {
			copy(topY[mbx*16:mbx*16+16], d.y[(mby*16+15)*d.yStride+mbx*16:])
			copy(topU[mbx*8:mbx*8+8], d.u[(mby*8+7)*d.cStride+mbx*8:])
			copy(topV[mbx*8:mbx*8+8], d.v[(mby*8+7)*d.cStride+mbx*8:])
		}
	}

	if d.filterType > 0 {
		for mby := 0; mby < d.mbh; mby++ {
			for mbx := 0; mbx < d.mbw; mbx++ {
				d.loopFilter(mbx, mby, &finfo[mby*d.mbw+mbx])
			}
		}
	}

	return img.SubImage(image.Rect(0, 0, d.width, d.height)).(*image.YCbCr), nil
}

func b2i(b bool) int {
	if b {
		return 1
	}
	return 0
}

func hasCoeffs(c []int16) bool {
	for _, v := range c {
		if v != 0 {
			return true
		}
	}
	return false
}

// setupWork fills the prediction work buffer for a macroblock: above row,
// left column, top-left corner and (for luma) top-right samples. The block
// itself starts at (1,1).
func (d *vp8Decoder) setupWork(w []uint8, size, mbx, mby int, plane []uint8, stride int, top []uint8, luma bool) {
	o := 1 + bps
	// left column
	if mbx == 0 {
		for j := 0; j < size; j++ {
			w[o-1+j*bps] = 129
		}
	} else {
		for j := 0; j < size; j++ {
			w[o-1+j*bps] = plane[(mby*size+j)*stride+mbx*size-1]
		}
	}
	// above row and corner
	extra := 0
	if luma {
		extra = 4
	}
	if mby == 0 {
		for i := -1; i < size+extra; i++ {
			w[o-bps+i] = 127
		}
	} else {
		copy(w[o-bps:o-bps+size], top[mbx*size:mbx*size+size])
		if mbx == 0 {
			w[o-bps-1] = 129
		} else {
			w[o-bps-1] = top[mbx*size-1]
		}
		if luma {
			if mbx >= d.mbw-1 {
				for i := 0; i < 4; i++ {
					w[o-bps+16+i] = top[mbx*16+15]
				}
			} else {
				copy(w[o-bps+16:o-bps+20], top[(mbx+1)*16:(mbx+1)*16+4])
			}
		}
	}
	if luma {
		// replicate the top-right samples for the inner rows of 4x4 blocks
		for k := 1; k <= 3; k++ {
			copy(w[o+(4*k-1)*bps+16:o+(4*k-1)*bps+20], w[o-bps+16:o-bps+20])
		}
	}
}

func (d *vp8Decoder) parseResiduals(br *vp8Bool, mb *vp8MBInfo, coeffs *[384]int16, nzT, nzL, nzDCT, nzDCL *uint32) (uint32, uint32) {
	q := d.quant[mb.segment]
	var nonZeroY, nonZeroUV uint32
	first := 0
	acType := 3
	if !mb.isI4x4 {
		var dc [16]int16
		ctx := int(*nzDCT + *nzDCL)
		nz := d.getCoeffs(br, 1, ctx, q.y2, 0, dc[:])
		v := uint32(0)
		if nz > 0 {
			v = 1
		}
		*nzDCT = v
		*nzDCL = v
		if nz > 1 {
			transformWHT(dc[:], coeffs[:])
		} else {
			dc0 := (int(dc[0]) + 3) >> 3
			for i := 0; i < 256; i += 16 {
				coeffs[i] = int16(dc0)
			}
		}
		first = 1
		acType = 0
	}

	tnz := *nzT & 0x0f
	lnz := *nzL & 0x0f
	for y := 0; y < 4; y++ {
		l := lnz & 1
		var nzCoeffs uint32
		for x := 0; x < 4; x++ {
			ctx := int(l + (tnz & 1))
			blk := coeffs[(y*4+x)*16 : (y*4+x)*16+16]
			nz := d.getCoeffs(br, acType, ctx, q.y1, first, blk)
			if nz > first {
				l = 1
			} else {
				l = 0
			}
			tnz = (tnz >> 1) | (l << 7)
			nzCoeffs = nzCodeBits(nzCoeffs, nz, blk[0] != 0)
		}
		tnz >>= 4
		lnz = (lnz >> 1) | (l << 7)
		nonZeroY = (nonZeroY << 8) | nzCoeffs
	}
	outT := tnz
	outL := lnz >> 4

	for ch := 0; ch < 4; ch += 2 {
		var nzCoeffs uint32
		tnz = *nzT >> uint(4+ch)
		lnz = *nzL >> uint(4+ch)
		for y := 0; y < 2; y++ {
			l := lnz & 1
			for x := 0; x < 2; x++ {
				ctx := int(l + (tnz & 1))
				idx := 16 + (ch/2)*4 + y*2 + x
				blk := coeffs[idx*16 : idx*16+16]
				nz := d.getCoeffs(br, 2, ctx, q.uv, 0, blk)
				if nz > 0 {
					l = 1
				} else {
					l = 0
				}
				tnz = (tnz >> 1) | (l << 3)
				nzCoeffs = nzCodeBits(nzCoeffs, nz, blk[0] != 0)
			}
			tnz >>= 2
			lnz = (lnz >> 1) | (l << 5)
		}
		nonZeroUV |= nzCoeffs << uint(4*ch)
		outT |= (tnz << 4) << uint(ch)
		outL |= (lnz & 0xf0) << uint(ch)
	}
	*nzT = outT
	*nzL = outL
	return nonZeroY, nonZeroUV
}

func nzCodeBits(nzCoeffs uint32, nz int, dcNZ bool) uint32 {
	nzCoeffs <<= 2
	switch {
	case nz > 3:
		nzCoeffs |= 3
	case nz > 1:
		nzCoeffs |= 2
	case dcNZ:
		nzCoeffs |= 1
	}
	return nzCoeffs
}

// loop filter tables / helpers
func sclip1(v int) int {
	if v < -128 {
		return -128
	}
	if v > 127 {
		return 127
	}
	return v
}

func sclip2(v int) int {
	if v < -16 {
		return -16
	}
	if v > 15 {
		return 15
	}
	return v
}

func absI(v int) int {
	if v < 0 {
		return -v
	}
	return v
}

func doFilter2(p []uint8, i, step int) {
	p1, p0, q0, q1 := int(p[i-2*step]), int(p[i-step]), int(p[i]), int(p[i+step])
	a := 3*(q0-p0) + sclip1(p1-q1)
	a1 := sclip2((a + 4) >> 3)
	a2 := sclip2((a + 3) >> 3)
	p[i-step] = clip8(p0 + a2)
	p[i] = clip8(q0 - a1)
}

func doFilter4(p []uint8, i, step int) {
	p1, p0, q0, q1 := int(p[i-2*step]), int(p[i-step]), int(p[i]), int(p[i+step])
	a := 3 * (q0 - p0)
	a1 := sclip2((a + 4) >> 3)
	a2 := sclip2((a + 3) >> 3)
	a3 := (a1 + 1) >> 1
	p[i-2*step] = clip8(p1 + a3)
	p[i-step] = clip8(p0 + a2)
	p[i] = clip8(q0 - a1)
	p[i+step] = clip8(q1 - a3)
}

func doFilter6(p []uint8, i, step int) {
	p2, p1, p0 := int(p[i-3*step]), int(p[i-2*step]), int(p[i-step])
	q0, q1, q2 := int(p[i]), int(p[i+step]), int(p[i+2*step])
	a := sclip1(3*(q0-p0) + sclip1(p1-q1))
	a1 := (27*a + 63) >> 7
	a2 := (18*a + 63) >> 7
	a3 := (9*a + 63) >> 7
	p[i-3*step] = clip8(p2 + a3)
	p[i-2*step] = clip8(p1 + a2)
	p[i-step] = clip8(p0 + a1)
	p[i] = clip8(q0 - a1)
	p[i+step] = clip8(q1 - a2)
	p[i+2*step] = clip8(q2 - a3)
}

func hev(p []uint8, i, step, thresh int) bool {
	p1, p0, q0, q1 := int(p[i-2*step]), int(p[i-step]), int(p[i]), int(p[i+step])
	return absI(p1-p0) > thresh || absI(q1-q0) > thresh
}

func needsFilter(p []uint8, i, step, t int) bool {
	p1, p0, q0, q1 := int(p[i-2*step]), int(p[i-step]), int(p[i]), int(p[i+step])
	return 4*absI(p0-q0)+absI(p1-q1) <= t
}

func needsFilter2(p []uint8, i, step, t, it int) bool {
	p3, p2, p1 := int(p[i-4*step]), int(p[i-3*step]), int(p[i-2*step])
	p0, q0 := int(p[i-step]), int(p[i])
	q1, q2, q3 := int(p[i+step]), int(p[i+2*step]), int(p[i+3*step])
	if 4*absI(p0-q0)+absI(p1-q1) > t {
		return false
	}
	return absI(p3-p2) <= it && absI(p2-p1) <= it && absI(p1-p0) <= it &&
		absI(q3-q2) <= it && absI(q2-q1) <= it && absI(q1-q0) <= it
}

func simpleFilter(p []uint8, i, step, stride2, n, thresh int) {
	t2 := 2*thresh + 1
	for k := 0; k < n; k++ {
		if needsFilter(p, i+k*stride2, step, t2) {
			doFilter2(p, i+k*stride2, step)
		}
	}
}

func filterLoop26(p []uint8, i, hstride, vstride, size, thresh, ithresh, hevT int) {
	t2 := 2*thresh + 1
	for ; size > 0; size-- {
		if needsFilter2(p, i, hstride, t2, ithresh) {
			if hev(p, i, hstride, hevT) {
				doFilter2(p, i, hstride)
			} else {
				doFilter6(p, i, hstride)
			}
		}
		i += vstride
	}
}

func filterLoop24(p []uint8, i, hstride, vstride, size, thresh, ithresh, hevT int) {
	t2 := 2*thresh + 1
	for ; size > 0; size-- {
		if needsFilter2(p, i, hstride, t2, ithresh) {
			if hev(p, i, hstride, hevT) {
				doFilter2(p, i, hstride)
			} else {
				doFilter4(p, i, hstride)
			}
		}
		i += vstride
	}
}

func (d *vp8Decoder) loopFilter(mbx, mby int, f *vp8FInfo) {
	limit := f.limit
	if limit == 0 {
		return
	}
	ys := d.yStride
	yo := mby*16*ys + mbx*16
	if d.filterType == 1 {
		if mbx > 0 {
			simpleFilter(d.y, yo, 1, ys, 16, limit+4)
		}
		if f.inner {
			for k := 1; k <= 3; k++ {
				simpleFilter(d.y, yo+4*k, 1, ys, 16, limit)
			}
		}
		if mby > 0 {
			simpleFilter(d.y, yo, ys, 1, 16, limit+4)
		}
		if f.inner {
			for k := 1; k <= 3; k++ {
				simpleFilter(d.y, yo+4*k*ys, ys, 1, 16, limit)
			}
		}
		return
	}
	cs := d.cStride
	co := mby*8*cs + mbx*8
	il := f.ilevel
	ht := f.hevThresh
	if mbx > 0 {
		filterLoop26(d.y, yo, 1, ys, 16, limit+4, il, ht)
		filterLoop26(d.u, co, 1, cs, 8, limit+4, il, ht)
		filterLoop26(d.v, co, 1, cs, 8, limit+4, il, ht)
	}
	if f.inner {
		for k := 1; k <= 3; k++ {
			filterLoop24(d.y, yo+4*k, 1, ys, 16, limit, il, ht)
		}
		filterLoop24(d.u, co+4, 1, cs, 8, limit, il, ht)
		filterLoop24(d.v, co+4, 1, cs, 8, limit, il, ht)
	}
	if mby > 0 {
		filterLoop26(d.y, yo, ys, 1, 16, limit+4, il, ht)
		filterLoop26(d.u, co, cs, 1, 8, limit+4, il, ht)
		filterLoop26(d.v, co, cs, 1, 8, limit+4, il, ht)
	}
	if f.inner {
		for k := 1; k <= 3; k++ {
			filterLoop24(d.y, yo+4*k*ys, ys, 1, 16, limit, il, ht)
		}
		filterLoop24(d.u, co+4*cs, cs, 1, 8, limit, il, ht)
		filterLoop24(d.v, co+4*cs, cs, 1, 8, limit, il, ht)
	}
}
