	"image"
	"os"
)

func main() {
	data, _ := os.ReadFile(os.Args[1])
	// find VP8 chunk
	img, err := decodeWebP(bytesReader(data))
	if err != nil {
		fmt.Println("err", err)
		os.Exit(1)
	}
	var y *image.YCbCr
	switch m := img.(type) {
	case *image.YCbCr:
		y = m
	case *image.NYCbCrA:
		y = &m.YCbCr
	default:
		fmt.Printf("type %T\n", img)
		os.Exit(1)
	}
	b := y.Bounds()
	out := []byte{}
	for j := 0; j < b.Dy(); j++ {
		out = append(out, y.Y[j*y.YStride:j*y.YStride+b.Dx()]...)
	}
	cw, ch := (b.Dx()+1)/2, (b.Dy()+1)/2
	for j := 0; j < ch; j++ {
		out = append(out, y.Cb[j*y.CStride:j*y.CStride+cw]...)
	}
	for j := 0; j < ch; j++ {
		out = append(out, y.Cr[j*y.CStride:j*y.CStride+cw]...)
	}
	os.Stdout.Write(out)
}
