#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
  int lossless; float quality; int method; int image_hint; int target_size; float target_PSNR;
  int segments; int sns_strength; int filter_strength; int filter_sharpness; int filter_type;
  int autofilter; int alpha_compression; int alpha_filtering; int alpha_quality; int pass;
  int show_compressed; int preprocessing; int partitions; int partition_limit; int emulate_jpeg_size;
  int thread_level; int low_memory; int near_lossless; int exact; int use_delta_palette; int use_sharp_yuv;
  uint32_t pad[64];
} WebPConfig;

typedef int (*WebPWriterFunction)(const uint8_t* data, size_t data_size, const void* picture);

typedef struct {
  int use_argb; int colorspace; int width, height;
  uint8_t *y, *u, *v; int y_stride, uv_stride;
  uint8_t* a; int a_stride; uint32_t pad1[2];
  uint32_t* argb; int argb_stride; uint32_t pad2[3];
  WebPWriterFunction writer; void* custom_ptr;
  int extra_info_type; uint8_t* extra_info;
  void* stats; int error_code; void* progress_hook; void* user_data;
  uint32_t pad3[3]; uint8_t *pad4, *pad5; uint32_t pad6[8];
  void* memory_; void* memory_argb_; void* pad7[2];
  uint8_t extra[512];
} WebPPicture;

typedef struct { uint8_t* mem; size_t size; size_t max_size; uint32_t pad[1]; } WebPMemoryWriter;

extern int WebPConfigInitInternal(WebPConfig*, int, float, int);
extern int WebPPictureInitInternal(WebPPicture*, int);
extern int WebPPictureImportRGBA(WebPPicture*, const uint8_t*, int);
extern int WebPEncode(const WebPConfig*, WebPPicture*);
extern void WebPMemoryWriterInit(WebPMemoryWriter*);
extern int WebPMemoryWrite(const uint8_t*, size_t, const WebPPicture*);
extern void WebPPictureFree(WebPPicture*);

int main(int argc, char** argv) {
  // wenc in.raw out.webp quality filter_type(0 simple,1 strong) filter_strength sharpness partitions(0..3) segments sns
  FILE* f = fopen(argv[1], "rb");
  uint32_t wh[2]; fread(wh, 4, 2, f);
  int w = wh[0], h = wh[1];
  uint8_t* pix = malloc(w*h*4); fread(pix, 1, w*h*4, f); fclose(f);
  WebPConfig cfg; memset(&cfg, 0, sizeof(cfg));
  if (!WebPConfigInitInternal(&cfg, 0, atof(argv[3]), 0x020f)) { fprintf(stderr, "cfg init fail\n"); return 1; }
  cfg.quality = atof(argv[3]);
  cfg.filter_type = atoi(argv[4]);
  cfg.filter_strength = atoi(argv[5]);
  cfg.filter_sharpness = atoi(argv[6]);
  cfg.partitions = atoi(argv[7]);
  cfg.segments = atoi(argv[8]);
  cfg.sns_strength = atoi(argv[9]);
  cfg.autofilter = 0;
  WebPPicture pic; memset(&pic, 0, sizeof(pic));
  if (!WebPPictureInitInternal(&pic, 0x020f)) { fprintf(stderr, "pic init fail\n"); return 1; }
  pic.width = w; pic.height = h; pic.use_argb = 0;
  if (!WebPPictureImportRGBA(&pic, pix, w*4)) { fprintf(stderr, "import fail\n"); return 1; }
  WebPMemoryWriter wr; WebPMemoryWriterInit(&wr);
  pic.writer = (WebPWriterFunction)WebPMemoryWrite; pic.custom_ptr = &wr;
  if (!WebPEncode(&cfg, &pic)) { fprintf(stderr, "encode fail %d\n", pic.error_code); return 1; }
  FILE* o = fopen(argv[2], "wb"); fwrite(wr.mem, 1, wr.size, o); fclose(o);
  return 0;
}
