var vp8LutShift = func() (t [127]uint8) {
	for r := 0; r < 127; r++ {
		s := uint8(0)
		for (uint32(r)+1)<<s < 128 {
			s++
		}
		t[r] = s
	}
	return
}()

var vp8LutRangeM1 = func() (t [127]uint8) {
	for r := 0; r < 127; r++ {
		t[r] = uint8(((uint32(r) + 1) << vp8LutShift[r]) - 1)
	}
	return
