func (d *vp8Bool) init(data []byte) {
	d.data = data
	d.pos = 0
	d.rangeM1 = 254
	d.bits = 0
	d.nBits = 0
	d.eof = false
}

func (d *vp8Bool) bit(prob uint8) bool {
	if d.nBits < 8 {
		if d.pos >= len(d.data) {
			d.eof = true
			return false
		}
		d.bits |= uint32(d.data[d.pos]) << (8 - d.nBits)
		d.pos++
		d.nBits += 8
