// writes records: rune(uint32) ox(int16) oy(int16) w(uint16) h(uint16) data[w*h]
func extract(path string) (int, int, int, int, []byte, bool) {
	f, err := os.Open(path)
	if err != nil {
		return 0, 0, 0, 0, nil, false
	}
	defer f.Close()
	img, _, err := image.Decode(f)
	if err != nil {
		return 0, 0, 0, 0, nil, false
	}
	b := img.Bounds()
	ox, oy := 5+14, 5+28
	minx, miny, maxx, maxy := 1<<30, 1<<30, -1<<30, -1<<30
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			r, _, _, _ := img.At(x, y).RGBA()
			if r>>8 != 0 {
				if x < minx {
					minx = x
				}
				if x > maxx {
					maxx = x
				}
				if y < miny {
					miny = y
				}
				if y > maxy {
					maxy = y
				}
			}
		}
	}
	if maxx < 0 {
		return 0, 0, 0, 0, nil, true
	}
	w, h := maxx-minx+1, maxy-miny+1
	data := make([]byte, 0, w*h)
	for y := miny; y <= maxy; y++ {
		for x := minx; x <= maxx; x++ {
			r, _, _, _ := img.At(x, y).RGBA()
			data = append(data, byte(r>>8))
