package main

import (
	"bytes"
	"compress/zlib"
	"encoding/binary"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"io"
	"os"
	"sync"
)

// Rendering of ascii art into raster images using pre-rasterised glyph
// coverage masks. Each character occupies a 14x28 pixel cell and the image
// has a 5 pixel margin on every side.

const (
	cellW  = 14
	cellH  = 28
	margin = 5
)

type glyphMask struct {
	ox, oy, w, h int
	alpha        []byte
}

type glyphSet struct {
	glyphs  map[rune]*glyphMask
	notdef  *glyphMask
	braille [8]*glyphMask
}

var (
	defaultGlyphsOnce sync.Once
	defaultGlyphs     *glyphSet
)

func parseGlyphBlob(blob []byte) map[rune]*glyphMask {
	zr, err := zlib.NewReader(bytes.NewReader(blob))
	if err != nil {
		return map[rune]*glyphMask{}
	}
	data, err := io.ReadAll(zr)
	if err != nil {
		return map[rune]*glyphMask{}
	}
	m := map[rune]*glyphMask{}
	for i := 0; i+12 <= len(data); {
		r := rune(binary.LittleEndian.Uint32(data[i:]))
		ox := int(int16(binary.LittleEndian.Uint16(data[i+4:])))
		oy := int(int16(binary.LittleEndian.Uint16(data[i+6:])))
		w := int(binary.LittleEndian.Uint16(data[i+8:]))
		h := int(binary.LittleEndian.Uint16(data[i+10:]))
		i += 12
		if i+w*h > len(data) {
			break
		}
		m[r] = &glyphMask{ox: ox, oy: oy, w: w, h: h, alpha: data[i : i+w*h]}
		i += w * h
	}
	return m
}

func loadDefaultGlyphs() *glyphSet {
	defaultGlyphsOnce.Do(func() {
		gs := &glyphSet{glyphs: parseGlyphBlob(asciiGlyphBlob)}
		gs.notdef = gs.glyphs[0x4e2d]
		delete(gs.glyphs, 0x4e2d)
		dots := parseGlyphBlob(brailleGlyphBlob)
		for b := 0; b < 8; b++ {
			gs.braille[b] = dots[rune(0x2800+(1<<uint(b)))]
		}
		defaultGlyphs = gs
	})
	return defaultGlyphs
}

// compositeGlyph draws the coverage mask m with colour c at (x, y) using
// Porter-Duff "over" in 16-bit precision.
func compositeGlyph(dst *image.RGBA, m *glyphMask, x, y int, c [3]uint8) {
	if m == nil {
		return
	}
	sr := uint32(c[0]) * 0x101
	sg := uint32(c[1]) * 0x101
	sb := uint32(c[2]) * 0x101
	const sa = 0xffff
	b := dst.Rect
	for j := 0; j < m.h; j++ {
		py := y + m.oy + j
		if py < b.Min.Y || py >= b.Max.Y {
			continue
		}
		for i := 0; i < m.w; i++ {
			px := x + m.ox + i
			if px < b.Min.X || px >= b.Max.X {
				continue
			}
			a8 := m.alpha[j*m.w+i]
			if a8 == 0 {
				continue
			}
			ma := uint32(a8) * 0x101
			pr := sr * ma / 0xffff
			pg := sg * ma / 0xffff
			pb := sb * ma / 0xffff
			pa := uint32(sa) * ma / 0xffff
			off := dst.PixOffset(px, py)
			p := dst.Pix[off : off+4 : off+4]
			qr := uint32(p[0]) * 0x101
			qg := uint32(p[1]) * 0x101
			qb := uint32(p[2]) * 0x101
			qa := uint32(p[3]) * 0x101
			pa1 := 0xffff - pa
			p[0] = uint8((qr*pa1/0xffff + pr) >> 8)
			p[1] = uint8((qg*pa1/0xffff + pg) >> 8)
			p[2] = uint8((qb*pa1/0xffff + pb) >> 8)
			p[3] = uint8((qa*pa1/0xffff + pa) >> 8)
		}
	}
