	return color.NRGBA{uint8(optSaveBg[0]), uint8(optSaveBg[1]), uint8(optSaveBg[2]), uint8(optSaveBg[3] * 255 / 100)}
}

func textColor(ch asciiChar) [3]uint8 {
	return ch.rgb
}

// renderArt renders the character grid at full size.
func renderArt(art [][]asciiChar) *image.RGBA {
	rows := len(art)
	cols := 0
	if rows > 0 {
		cols = len(art[0])
	}
	img := image.NewRGBA(image.Rect(0, 0, cellW*cols+2*margin, cellH*rows+2*margin))
