			}
		}
	}
	return img
}

func isBlankRune(r rune) bool {
	switch r {
	case ' ', 0xa0, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006, 0x2007, 0x2008, 0x2009, 0x200a, 0x202f, 0x205f, 0x3000:
