	origH := g.Config.Height
	var wg sync.WaitGroup
	var mu sync.Mutex
	counter := 0
	sem := make(chan struct{}, 4)
	for i := range frames {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			sem <- struct{}{}
			p := renderGifFrame(frames[i], origH)
			<-sem
			mu.Lock()
			out.Image[i] = p
