	if innerH > 0 {
		targetW = int(float64(targetH) * float64(innerW) / float64(innerH))
	}
	full := renderArt(art)
	canvas := image.NewRGBA(image.Rect(0, 0, targetW+2*margin, targetH+2*margin))
	draw.Draw(canvas, canvas.Bounds(), image.NewUniform(backgroundColor()), image.Point{}, draw.Src)
	if targetW > 0 && targetH > 0 && innerW > 0 && innerH > 0 {
