package main

import (
	"fmt"
	"image"
)

// TrueType font parsing and (unhinted) glyph outline loading, plus glyph
// rasterisation into coverage masks.

type ttFormatError string

func (e ttFormatError) Error() string { return "freetype: invalid TrueType format: " + string(e) }

type ttUnsupportedError string

func (e ttUnsupportedError) Error() string {
	return "freetype: unsupported TrueType feature: " + string(e)
}

type fix26 int32

type ttPoint struct {
	X, Y  fix26
	Flags uint32
}

type ttCM struct {
	start, end, delta, offset uint32
}

type ttFont struct {
	cmap, cvt, fpgm, glyf, hdmx, head, hhea, hmtx, kern, loca, maxp, name, os2, prep, vmtx []byte

	cmapIndexes []byte
	cm          []ttCM

	locaOffsetFormat int
	nGlyph           int
	nHMetric         int
	nKern            int
	fUnitsPerEm      int32
	ascent, descent  int32
	lineGap          int32
	bounds           [4]fix26 // minX, minY, maxX, maxY
}

func u16(b []byte, i int) uint16 { return uint16(b[i])<<8 | uint16(b[i+1]) }
func u32(b []byte, i int) uint32 {
	return uint32(b[i])<<24 | uint32(b[i+1])<<16 | uint32(b[i+2])<<8 | uint32(b[i+3])
}

func readTTTable(ttf []byte, ol []byte) ([]byte, error) {
	offset := int(u32(ol, 0))
	if offset < 0 {
		return nil, ttFormatError(fmt.Sprintf("offset too large: %d", uint32(offset)))
	}
	length := int(u32(ol, 4))
	if length < 0 {
		return nil, ttFormatError(fmt.Sprintf("length too large: %d", uint32(length)))
	}
	end := offset + length
	if end < 0 || end > len(ttf) {
		return nil, ttFormatError(fmt.Sprintf("offset + length too large: %d", uint32(offset)+uint32(length)))
	}
	return ttf[offset:end], nil
}

func parseTTF(ttf []byte) (*ttFont, error) {
	return parseTTFAt(ttf, 0)
}

func parseTTFAt(ttf []byte, offset int) (*ttFont, error) {
	if len(ttf)-offset < 12 {
		return nil, ttFormatError("TTF data is too short")
	}
	original := offset
	magic := u32(ttf, offset)
	offset += 4
	switch magic {
	case 0x00010000:
	case 0x74746366:
		if original != 0 {
			return nil, ttFormatError("recursive TTC")
		}
		ttcVersion := u32(ttf, offset)
		offset += 4
		if ttcVersion != 0x00010000 && ttcVersion != 0x00020000 {
			return nil, ttFormatError("bad TTC version")
		}
		numFonts := int(u32(ttf, offset))
		offset += 4
		if numFonts <= 0 {
			return nil, ttFormatError("bad number of TTC fonts")
		}
		if len(ttf[offset:])/4 < numFonts {
			return nil, ttFormatError("TTC offset table is too short")
		}
		offset = int(u32(ttf, offset))
		if offset <= 0 || offset > len(ttf) {
			return nil, ttFormatError("bad TTC offset")
		}
		return parseTTFAt(ttf, offset)
	default:
		return nil, ttFormatError("bad TTF version")
	}
	n := int(u16(ttf, offset))
	offset += 2
	offset += 6
	if len(ttf) < 16*n+offset {
		return nil, ttFormatError("TTF data is too short")
	}
	f := &ttFont{}
	var err error
	for i := 0; i < n; i++ {
		x := 16*i + offset
		ol := ttf[x+8 : x+16]
		switch string(ttf[x : x+4]) {
		case "cmap":
			f.cmap, err = readTTTable(ttf, ol)
		case "cvt ":
			f.cvt, err = readTTTable(ttf, ol)
		case "fpgm":
			f.fpgm, err = readTTTable(ttf, ol)
		case "glyf":
			f.glyf, err = readTTTable(ttf, ol)
		case "hdmx":
			f.hdmx, err = readTTTable(ttf, ol)
		case "head":
			f.head, err = readTTTable(ttf, ol)
		case "hhea":
			f.hhea, err = readTTTable(ttf, ol)
		case "hmtx":
			f.hmtx, err = readTTTable(ttf, ol)
		case "kern":
			f.kern, err = readTTTable(ttf, ol)
		case "loca":
			f.loca, err = readTTTable(ttf, ol)
		case "maxp":
			f.maxp, err = readTTTable(ttf, ol)
		case "name":
			f.name, err = readTTTable(ttf, ol)
		case "OS/2":
			f.os2, err = readTTTable(ttf, ol)
		case "prep":
			f.prep, err = readTTTable(ttf, ol)
		case "vmtx":
			f.vmtx, err = readTTTable(ttf, ol)
		}
		if err != nil {
			return nil, err
		}
	}
	if err = f.parseHead(); err != nil {
		return nil, err
	}
	if err = f.parseMaxp(); err != nil {
		return nil, err
	}
	if err = f.parseCmap(); err != nil {
		return nil, err
	}
	if err = f.parseKern(); err != nil {
		return nil, err
	}
	if err = f.parseHhea(); err != nil {
		return nil, err
	}
	return f, nil
}

func (f *ttFont) parseHead() error {
	if len(f.head) != 54 {
		return ttFormatError(fmt.Sprintf("bad head length: %d", len(f.head)))
	}
	f.fUnitsPerEm = int32(u16(f.head, 18))
	f.bounds[0] = fix26(int16(u16(f.head, 36)))
	f.bounds[1] = fix26(int16(u16(f.head, 38)))
	f.bounds[2] = fix26(int16(u16(f.head, 40)))
	f.bounds[3] = fix26(int16(u16(f.head, 42)))
	switch i := u16(f.head, 50); i {
	case 0:
		f.locaOffsetFormat = 0
	case 1:
		f.locaOffsetFormat = 1
	default:
		return ttFormatError(fmt.Sprintf("bad indexToLocFormat: %d", i))
	}
	return nil
}

func (f *ttFont) parseMaxp() error {
	if len(f.maxp) != 32 {
		return ttFormatError(fmt.Sprintf("bad maxp length: %d", len(f.maxp)))
	}
	f.nGlyph = int(u16(f.maxp, 4))
	return nil
}

func (f *ttFont) parseCmap() error {
	const (
		unicodeEncodingBMPOnly  = 0x00000003
		unicodeEncodingFull     = 0x00000004
		microsoftSymbolEncoding = 0x00030000
		microsoftUCS2Encoding   = 0x00030001
		microsoftUCS4Encoding   = 0x0003000a
	)
	if len(f.cmap) < 4 {
		return ttFormatError("cmap too short")
	}
	nsubtab := int(u16(f.cmap, 2))
	if len(f.cmap) < 8*nsubtab+4 {
		return ttFormatError("cmap too short")
	}
	offset, found, x := 0, false, 4
	for i := 0; i < nsubtab; i++ {
		pidPsid, o := u32(f.cmap, x), u32(f.cmap, x+4)
		x += 8
		if pidPsid == unicodeEncodingBMPOnly || pidPsid == unicodeEncodingFull {
			offset, found = int(o), true
			break
		} else if pidPsid == microsoftSymbolEncoding ||
			pidPsid == microsoftUCS2Encoding ||
			pidPsid == microsoftUCS4Encoding {
			offset, found = int(o), true
		}
	}
	if !found {
		return ttUnsupportedError("cmap encoding")
	}
	if offset <= 0 || offset > len(f.cmap) {
		return ttFormatError("bad cmap offset")
	}
	cmapFormat := u16(f.cmap, offset)
	switch cmapFormat {
	case 4:
		language := u16(f.cmap, offset+4)
		if language != 0 {
			return ttUnsupportedError(fmt.Sprintf("language: %d", language))
		}
		segCountX2 := int(u16(f.cmap, offset+6))
		if segCountX2%2 == 1 {
			return ttFormatError(fmt.Sprintf("bad segCountX2: %d", segCountX2))
		}
		segCount := segCountX2 / 2
		offset += 14
		f.cm = make([]ttCM, segCount)
		for i := 0; i < segCount; i++ {
			f.cm[i].end = uint32(u16(f.cmap, offset))
			offset += 2
		}
		offset += 2
		for i := 0; i < segCount; i++ {
			f.cm[i].start = uint32(u16(f.cmap, offset))
			offset += 2
		}
		for i := 0; i < segCount; i++ {
			f.cm[i].delta = uint32(u16(f.cmap, offset))
			offset += 2
		}
		for i := 0; i < segCount; i++ {
			f.cm[i].offset = uint32(u16(f.cmap, offset))
			offset += 2
		}
		f.cmapIndexes = f.cmap[offset:]
		return nil
	case 12:
		if u16(f.cmap, offset+2) != 0 {
			return ttFormatError(fmt.Sprintf("cmap format: % x", f.cmap[offset:offset+4]))
		}
		length := u32(f.cmap, offset+4)
		language := u32(f.cmap, offset+8)
		if language != 0 {
			return ttUnsupportedError(fmt.Sprintf("language: %d", language))
		}
		nGroups := u32(f.cmap, offset+12)
		if length != 12*nGroups+16 {
			return ttFormatError("inconsistent cmap length")
		}
		offset += 16
		f.cm = make([]ttCM, nGroups)
		for i := uint32(0); i < nGroups; i++ {
			f.cm[i].start = u32(f.cmap, offset+0)
			f.cm[i].end = u32(f.cmap, offset+4)
			f.cm[i].delta = u32(f.cmap, offset+8) - f.cm[i].start
			offset += 12
		}
		return nil
	}
	return ttUnsupportedError(fmt.Sprintf("cmap format: %d", cmapFormat))
}

func (f *ttFont) parseKern() error {
	if len(f.kern) == 0 {
		if f.nKern != 0 {
			return ttFormatError("bad kern table length")
		}
		return nil
	}
	if len(f.kern) < 18 {
		return ttFormatError("kern data too short")
	}
	version, offset := u16(f.kern, 0), 2
	if version != 0 {
		return ttUnsupportedError(fmt.Sprintf("kern version: %d", version))
	}
	n := u16(f.kern, offset)
	offset += 2
	if n != 1 {
		return ttUnsupportedError(fmt.Sprintf("kern nTables: %d", n))
	}
	offset += 2
	length := int(u16(f.kern, offset))
	offset += 2
	coverage := u16(f.kern, offset)
	offset += 2
	if coverage != 0x0001 {
		return ttUnsupportedError(fmt.Sprintf("kern coverage: 0x%04x", coverage))
	}
	f.nKern = int(u16(f.kern, offset))
	if 6*f.nKern != length-14 {
		return ttFormatError("bad kern table length")
	}
	return nil
}

func (f *ttFont) parseHhea() error {
	if len(f.hhea) != 36 {
		return ttFormatError(fmt.Sprintf("bad hhea length: %d", len(f.hhea)))
	}
	f.ascent = int32(int16(u16(f.hhea, 4)))
	f.descent = int32(int16(u16(f.hhea, 6)))
	f.lineGap = int32(int16(u16(f.hhea, 8)))
	f.nHMetric = int(u16(f.hhea, 34))
	if 4*f.nHMetric+2*(f.nGlyph-f.nHMetric) != len(f.hmtx) {
		return ttFormatError(fmt.Sprintf("bad hmtx length: %d", len(f.hmtx)))
	}
	return nil
}

func (f *ttFont) index(x rune) int {
	c := uint32(x)
	for i, j := 0, len(f.cm); i < j; {
		h := i + (j-i)/2
		cm := &f.cm[h]
		if c < cm.start {
			j = h
		} else if cm.end < c {
			i = h + 1
		} else if cm.offset == 0 {
			return int(uint16(c + cm.delta))
		} else {
			offset := int(cm.offset) + 2*(h-len(f.cm)+int(c-cm.start))
			return int(u16(f.cmapIndexes, offset))
		}
	}
	return 0
}

func (f *ttFont) scale(x fix26) fix26 {
	if x >= 0 {
		x += fix26(f.fUnitsPerEm) / 2
	} else {
		x -= fix26(f.fUnitsPerEm) / 2
	}
	return x / fix26(f.fUnitsPerEm)
}

type ttHMetric struct{ advance, lsb fix26 }

func (f *ttFont) unscaledHMetric(i int) ttHMetric {
	if i < 0 || f.nGlyph <= i {
		return ttHMetric{}
	}
	if i >= f.nHMetric {
		p := 4 * (f.nHMetric - 1)
		return ttHMetric{
			advance: fix26(u16(f.hmtx, p)),
			lsb:     fix26(int16(u16(f.hmtx, p+2*(i-f.nHMetric)+4))),
		}
	}
	return ttHMetric{
		advance: fix26(u16(f.hmtx, 4*i)),
		lsb:     fix26(int16(u16(f.hmtx, 4*i+2))),
	}
}

// glyph loading

type ttGlyphBuf struct {
	font       *ttFont
	scale      fix26
	Points     []ttPoint
	Ends       []int
	phantom    [4]ttPoint
	pp1x       fix26
	metricsSet bool
	bounds     [4]fix26
}

const (
	flagOnCurve              = 1 << 0
	flagXShortVector         = 1 << 1
	flagYShortVector         = 1 << 2
	flagRepeat               = 1 << 3
	flagPositiveXShortVector = 1 << 4
	flagThisXIsSame          = 1 << 4
	flagPositiveYShortVector = 1 << 5
	flagThisYIsSame          = 1 << 5
)

func (g *ttGlyphBuf) load(f *ttFont, scale fix26, i int) error {
	g.Points = g.Points[:0]
	g.Ends = g.Ends[:0]
	g.font = f
	g.scale = scale
	g.pp1x = 0
	g.phantom = [4]ttPoint{}
	g.metricsSet = false
	if err := g.loadGlyph(0, i, true); err != nil {
		return err
	}
	if g.pp1x != 0 {
		for k := range g.Points {
			g.Points[k].X -= g.pp1x
		}
	}
	if len(g.Points) == 0 {
		g.bounds = [4]fix26{}
	} else {
		p := g.Points[0]
		g.bounds = [4]fix26{p.X, p.Y, p.X, p.Y}
		for _, p := range g.Points[1:] {
			if g.bounds[0] > p.X {
				g.bounds[0] = p.X
			} else if g.bounds[2] < p.X {
				g.bounds[2] = p.X
			}
			if g.bounds[1] > p.Y {
				g.bounds[1] = p.Y
			} else if g.bounds[3] < p.Y {
				g.bounds[3] = p.Y
			}
		}
	}
	return nil
}

func (g *ttGlyphBuf) addPhantomsAndScale(np1 int) {
	g.Points = append(g.Points, g.phantom[:]...)
	for k := np1; k < len(g.Points); k++ {
		p := &g.Points[k]
		p.X = g.font.scale(g.scale * p.X)
		p.Y = g.font.scale(g.scale * p.Y)
	}
}

func (g *ttGlyphBuf) loadGlyph(recursion uint32, i int, useMyMetrics bool) error {
	if recursion >= 32 {
		return ttUnsupportedError("excessive compound glyph recursion")
	}
	f := g.font
	var g0, g1 uint32
	if f.locaOffsetFormat == 0 {
		g0 = 2 * uint32(u16(f.loca, 2*i))
		g1 = 2 * uint32(u16(f.loca, 2*i+2))
	} else {
		g0 = u32(f.loca, 4*i)
		g1 = u32(f.loca, 4*i+4)
	}
	var glyf []byte
	ne := 0
	var boundsXMin, boundsYMax fix26
	if g0+10 <= g1 {
		glyf = f.glyf[g0:g1]
		ne = int(int16(u16(glyf, 0)))
		boundsXMin = fix26(int16(u16(glyf, 2)))
		boundsYMax = fix26(int16(u16(glyf, 8)))
	}
	uhm := f.unscaledHMetric(i)
	pp1x := fix26(0)
	g.phantom = [4]ttPoint{
		{X: boundsXMin - uhm.lsb},
		{X: boundsXMin - uhm.lsb + uhm.advance},
		{X: uhm.advance / 2, Y: boundsYMax},
		{X: uhm.advance / 2, Y: boundsYMax},
	}
	if len(glyf) == 0 {
		g.addPhantomsAndScale(len(g.Points))
		copy(g.phantom[:], g.Points[len(g.Points)-4:])
		g.Points = g.Points[:len(g.Points)-4]
		return nil
	}
	if ne < 0 {
		if ne != -1 {
			return ttUnsupportedError("negative number of contours")
		}
		pp1x = f.scale(g.scale * (boundsXMin - uhm.lsb))
		if err := g.loadCompound(recursion, glyf, useMyMetrics); err != nil {
			return err
		}
	} else {
		np0, ne0 := len(g.Points), len(g.Ends)
		g.loadSimple(glyf, ne)
		g.addPhantomsAndScale(np0)
		pp1x = g.Points[len(g.Points)-4].X
		g.Points = g.Points[:len(g.Points)-4]
		if np0 != 0 {
			for k := ne0; k < len(g.Ends); k++ {
				g.Ends[k] += np0
			}
		}
	}
	if useMyMetrics && !g.metricsSet {
		g.metricsSet = true
		g.pp1x = pp1x
	}
	return nil
}

func (g *ttGlyphBuf) loadSimple(glyf []byte, ne int) {
	offset := 10
	for k := 0; k < ne; k++ {
		g.Ends = append(g.Ends, 1+int(u16(glyf, offset)))
		offset += 2
	}
	instrLen := int(u16(glyf, offset))
	offset += 2
	offset += instrLen
	if ne == 0 {
		return
	}
	np0 := len(g.Points)
	np1 := np0 + g.Ends[len(g.Ends)-1]
	for k := np0; k < np1; {
		c := uint32(glyf[offset])
		offset++
		g.Points = append(g.Points, ttPoint{Flags: c})
		k++
		if c&flagRepeat != 0 {
			count := glyf[offset]
			offset++
			for ; count > 0; count-- {
				g.Points = append(g.Points, ttPoint{Flags: c})
				k++
			}
		}
	}
	var x int16
	for k := np0; k < np1; k++ {
		fl := g.Points[k].Flags
		if fl&flagXShortVector != 0 {
			dx := int16(glyf[offset])
			offset++
			if fl&flagPositiveXShortVector == 0 {
				x -= dx
			} else {
				x += dx
			}
		} else if fl&flagThisXIsSame == 0 {
			x += int16(u16(glyf, offset))
			offset += 2
		}
		g.Points[k].X = fix26(x)
	}
	var y int16
	for k := np0; k < np1; k++ {
		fl := g.Points[k].Flags
		if fl&flagYShortVector != 0 {
			dy := int16(glyf[offset])
			offset++
			if fl&flagPositiveYShortVector == 0 {
				y -= dy
			} else {
				y += dy
			}
		} else if fl&flagThisYIsSame == 0 {
			y += int16(u16(glyf, offset))
			offset += 2
		}
		g.Points[k].Y = fix26(y)
	}
}

func (g *ttGlyphBuf) loadCompound(recursion uint32, glyf []byte, useMyMetrics bool) error {
	const (
		flagArg1And2AreWords = 1 << iota
		flagArgsAreXYValues
		flagRoundXYToGrid
		flagWeHaveAScale
		flagUnused
		flagMoreComponents
		flagWeHaveAnXAndYScale
		flagWeHaveATwoByTwo
		flagWeHaveInstructions
		flagUseMyMetrics
		flagOverlapCompound
	)
	np0 := len(g.Points)
	offset := 10
	for {
		flags := u16(glyf, offset)
		component := int(u16(glyf, offset+2))
		var dx, dy fix26
		var transform [4]int16
		hasTransform := false
		if flags&flagArg1And2AreWords != 0 {
			dx = fix26(int16(u16(glyf, offset+4)))
			dy = fix26(int16(u16(glyf, offset+6)))
			offset += 8
		} else {
			dx = fix26(int16(int8(glyf[offset+4])))
			dy = fix26(int16(int8(glyf[offset+5])))
			offset += 6
		}
		if flags&flagArgsAreXYValues == 0 {
			return ttUnsupportedError("compound glyph transform vector")
		}
		if flags&(flagWeHaveAScale|flagWeHaveAnXAndYScale|flagWeHaveATwoByTwo) != 0 {
			hasTransform = true
			switch {
			case flags&flagWeHaveAScale != 0:
				transform[0] = int16(u16(glyf, offset+0))
				transform[3] = transform[0]
				offset += 2
			case flags&flagWeHaveAnXAndYScale != 0:
				transform[0] = int16(u16(glyf, offset+0))
				transform[3] = int16(u16(glyf, offset+2))
				offset += 4
			case flags&flagWeHaveATwoByTwo != 0:
				transform[0] = int16(u16(glyf, offset+0))
				transform[1] = int16(u16(glyf, offset+2))
				transform[2] = int16(u16(glyf, offset+4))
				transform[3] = int16(u16(glyf, offset+6))
				offset += 8
			}
		}
		savedPP := g.phantom
		np := len(g.Points)
		componentUMM := useMyMetrics && (flags&flagUseMyMetrics != 0)
		if err := g.loadGlyph(recursion+1, component, componentUMM); err != nil {
			return err
		}
		if flags&flagUseMyMetrics == 0 {
			g.phantom = savedPP
		}
		if hasTransform {
			for j := np; j < len(g.Points); j++ {
				p := &g.Points[j]
				newX := fix26((int64(p.X)*int64(transform[0])+1<<13)>>14) +
					fix26((int64(p.Y)*int64(transform[2])+1<<13)>>14)
				newY := fix26((int64(p.X)*int64(transform[1])+1<<13)>>14) +
					fix26((int64(p.Y)*int64(transform[3])+1<<13)>>14)
				p.X, p.Y = newX, newY
			}
		}
		dx = g.font.scale(g.scale * dx)
		dy = g.font.scale(g.scale * dy)
		if flags&flagRoundXYToGrid != 0 {
			dx = (dx + 32) &^ 63
			dy = (dy + 32) &^ 63
		}
		for j := np; j < len(g.Points); j++ {
			p := &g.Points[j]
			p.X += dx
			p.Y += dy
		}
		if flags&flagMoreComponents == 0 {
			break
		}
	}
	g.addPhantomsAndScale(len(g.Points))
	points := g.Points[np0:]
	g.Points = g.Points[:len(g.Points)-4]
	if !g.metricsSet {
		copy(g.phantom[:], points[len(points)-4:])
	}
	return nil
}

// ttFace rasterises glyphs at a fixed size.
type ttFace struct {
	f          *ttFont
	scale      fix26
	maxw, maxh int
	glyphBuf   ttGlyphBuf
	r          rasterizer
}

func newTTFace(f *ttFont, size float64) *ttFace {
	a := &ttFace{f: f, scale: fix26(0.5 + (size * 72 * 64 / 72))}
	b := [4]fix26{
		f.scale(a.scale * f.bounds[0]), f.scale(a.scale * f.bounds[1]),
		f.scale(a.scale * f.bounds[2]), f.scale(a.scale * f.bounds[3]),
	}
	xmin := +int(b[0]) >> 6
	ymin := -int(b[3]) >> 6
	xmax := +int(b[2]+63) >> 6
	ymax := -int(b[1]-63) >> 6
	a.maxw = xmax - xmin
	a.maxh = ymax - ymin
	a.r.setBounds(a.maxw, a.maxh)
	return a
}

// glyph returns the coverage mask and its placement for rune ru drawn with
// the dot at (dotX, dotY) in 26.6 fixed point.
func (a *ttFace) glyph(dotX, dotY fix26, ru rune) (image.Rectangle, *image.Alpha, bool) {
	dotX = (dotX + 8) & -16
	dotY = (dotY + 32) & -64
	ix, fx := int(dotX>>6), dotX&0x3f
	iy, fy := int(dotY>>6), dotY&0x3f
	index := a.f.index(ru)
	if err := a.glyphBuf.load(a.f, a.scale, index); err != nil {
		return image.Rectangle{}, nil, false
	}
	gb := &a.glyphBuf
	xmin := int(fx+gb.bounds[0]) >> 6
	ymin := int(fy-gb.bounds[3]) >> 6
	xmax := int(fx+gb.bounds[2]+0x3f) >> 6
	ymax := int(fy-gb.bounds[1]+0x3f) >> 6
	if xmin > xmax || ymin > ymax {
		return image.Rectangle{}, nil, false
	}
	fx -= fix26(xmin << 6)
	fy -= fix26(ymin << 6)
	mask := image.NewAlpha(image.Rect(0, 0, a.maxw, a.maxh))
	a.r.clear()
	e0 := 0
	for _, e1 := range gb.Ends {
		a.drawContour(gb.Points[e0:e1], fx, fy)
		e0 = e1
	}
	a.r.rasterize(mask)
	dr := image.Rect(ix+xmin, iy+ymin, ix+xmin+(xmax-xmin), iy+ymin+(ymax-ymin))
	return dr, mask, true
}

func (a *ttFace) drawContour(ps []ttPoint, dx, dy fix26) {
	if len(ps) == 0 {
		return
	}
	start := rpoint{X: dx + ps[0].X, Y: dy - ps[0].Y}
	var others []ttPoint
	if ps[0].Flags&0x01 != 0 {
		others = ps[1:]
	} else {
		last := rpoint{X: dx + ps[len(ps)-1].X, Y: dy - ps[len(ps)-1].Y}
		if ps[len(ps)-1].Flags&0x01 != 0 {
			start = last
			others = ps[:len(ps)-1]
		} else {
			start = rpoint{X: (start.X + last.X) / 2, Y: (start.Y + last.Y) / 2}
			others = ps
		}
	}
	a.r.start(start)
	q0, on0 := start, true
	for _, p := range others {
		q := rpoint{X: dx + p.X, Y: dy - p.Y}
		on := p.Flags&0x01 != 0
		if on {
			if on0 {
				a.r.add1(q)
			} else {
				a.r.add2(q0, q)
			}
		} else {
			if !on0 {
				mid := rpoint{X: (q0.X + q.X) / 2, Y: (q0.Y + q.Y) / 2}
				a.r.add2(q0, mid)
			}
		}
		q0, on0 = q, on
	}
	if on0 {
		a.r.add1(start)
	} else {
		a.r.add2(q0, start)
	}
}
