package main

import (
	"image"
)

// Anti-aliasing scanline rasteriser accumulating signed area and coverage
// per pixel cell, in 26.6 fixed point.

type rpoint struct{ X, Y fix26 }

type rcell struct {
	xi          int
	area, cover int
	next        int
}

type rasterizer struct {
	useNonZeroWinding bool
	width             int
	splitScale2       int
	a                 rpoint
	xi, yi            int
	area, cover       int
	cell              []rcell
	cellIndex         []int
}

func (r *rasterizer) setBounds(width, height int) {
	if width < 0 {
		width = 0
	}
	if height < 0 {
		height = 0
	}
	ss2 := 32
	if width > 24 || height > 24 {
		ss2 = 2 * ss2
		if width > 120 || height > 120 {
			ss2 = 2 * ss2
		}
	}
	r.width = width
	r.splitScale2 = ss2
	r.cell = r.cell[:0]
	r.cellIndex = make([]int, height)
	r.clear()
}

func (r *rasterizer) clear() {
	r.a = rpoint{}
	r.xi = 0
	r.yi = 0
	r.area = 0
	r.cover = 0
	r.cell = r.cell[:0]
	for i := range r.cellIndex {
		r.cellIndex[i] = -1
	}
}

func (r *rasterizer) findCell() int {
	if r.yi < 0 || r.yi >= len(r.cellIndex) {
		return -1
	}
	xi := r.xi
	if xi < 0 {
		xi = -1
	} else if xi > r.width {
		xi = r.width
	}
	i, prev := r.cellIndex[r.yi], -1
	for i != -1 && r.cell[i].xi <= xi {
		if r.cell[i].xi == xi {
			return i
		}
		i, prev = r.cell[i].next, i
	}
	c := len(r.cell)
	r.cell = append(r.cell, rcell{xi, 0, 0, i})
	if prev == -1 {
		r.cellIndex[r.yi] = c
	} else {
		r.cell[prev].next = c
	}
	return c
}

func (r *rasterizer) saveCell() {
	if r.area != 0 || r.cover != 0 {
		i := r.findCell()
		if i != -1 {
			r.cell[i].area += r.area
			r.cell[i].cover += r.cover
		}
		r.area = 0
		r.cover = 0
	}
}

func (r *rasterizer) setCell(xi, yi int) {
	if r.xi != xi || r.yi != yi {
		r.saveCell()
		r.xi, r.yi = xi, yi
	}
}

func (r *rasterizer) scan(yi int, x0, y0f, x1, y1f fix26) {
	x0i := int(x0) / 64
	x0f := x0 - fix26(64*x0i)
	x1i := int(x1) / 64
	x1f := x1 - fix26(64*x1i)

	if y0f == y1f {
		r.setCell(x1i, yi)
		return
	}
	dx, dy := x1-x0, y1f-y0f
	if x0i == x1i {
		r.area += int((x0f + x1f) * dy)
		r.cover += int(dy)
		return
	}
	var (
		p, q, edge0, edge1 fix26
		xiDelta            int
	)
	if dx > 0 {
		p, q = (64-x0f)*dy, dx
		edge0, edge1, xiDelta = 0, 64, 1
	} else {
		p, q = x0f*dy, -dx
		edge0, edge1, xiDelta = 64, 0, -1
	}
	yDelta, yRem := p/q, p%q
	if yRem < 0 {
		yDelta--
		yRem += q
	}
	xi, y := x0i, y0f
	r.area += int((x0f + edge1) * yDelta)
	r.cover += int(yDelta)
	xi, y = xi+xiDelta, y+yDelta
	r.setCell(xi, yi)
	if xi != x1i {
		p = 64 * (y1f - y + yDelta)
		fullDelta, fullRem := p/q, p%q
		if fullRem < 0 {
			fullDelta--
			fullRem += q
		}
		yRem -= q
		for xi != x1i {
			yDelta = fullDelta
			yRem += fullRem
			if yRem >= 0 {
				yDelta++
				yRem -= q
			}
			r.area += int(64 * yDelta)
			r.cover += int(yDelta)
			xi, y = xi+xiDelta, y+yDelta
			r.setCell(xi, yi)
		}
	}
	yDelta = y1f - y
	r.area += int((edge0 + x1f) * yDelta)
	r.cover += int(yDelta)
}

func (r *rasterizer) start(a rpoint) {
	r.setCell(int(a.X/64), int(a.Y/64))
	r.a = a
}

func (r *rasterizer) add1(b rpoint) {
	x0, y0 := r.a.X, r.a.Y
	x1, y1 := b.X, b.Y
	dx, dy := x1-x0, y1-y0
	y0i := int(y0) / 64
	y0f := y0 - fix26(64*y0i)
	y1i := int(y1) / 64
	y1f := y1 - fix26(64*y1i)

	if y0i == y1i {
		r.scan(y0i, x0, y0f, x1, y1f)
	} else if dx == 0 {
		var (
			edge0, edge1 fix26
			yiDelta      int
		)
		if dy > 0 {
			edge0, edge1, yiDelta = 0, 64, 1
		} else {
			edge0, edge1, yiDelta = 64, 0, -1
		}
		x0i, yi := int(x0)/64, y0i
		x0fTimes2 := (int(x0) - (64 * x0i)) * 2
		dcover := int(edge1 - y0f)
		darea := x0fTimes2 * dcover
		r.area += darea
		r.cover += dcover
		yi += yiDelta
		r.setCell(x0i, yi)
		dcover = int(edge1 - edge0)
		darea = x0fTimes2 * dcover
		for yi != y1i {
			r.area += darea
			r.cover += dcover
			yi += yiDelta
			r.setCell(x0i, yi)
		}
		dcover = int(y1f - edge0)
		darea = x0fTimes2 * dcover
		r.area += darea
		r.cover += dcover
	} else {
		var (
			p, q, edge0, edge1 fix26
			yiDelta            int
		)
		if dy > 0 {
			p, q = (64-y0f)*dx, dy
			edge0, edge1, yiDelta = 0, 64, 1
		} else {
			p, q = y0f*dx, -dy
			edge0, edge1, yiDelta = 64, 0, -1
		}
		xDelta, xRem := p/q, p%q
		if xRem < 0 {
			xDelta--
			xRem += q
		}
		x, yi := x0, y0i
		r.scan(yi, x, y0f, x+xDelta, edge1)
		x, yi = x+xDelta, yi+yiDelta
		r.setCell(int(x)/64, yi)
		if yi != y1i {
			p = 64 * dx
			fullDelta, fullRem := p/q, p%q
			if fullRem < 0 {
				fullDelta--
				fullRem += q
			}
			xRem -= q
			for yi != y1i {
				xDelta = fullDelta
				xRem += fullRem
				if xRem >= 0 {
					xDelta++
					xRem -= q
				}
				r.scan(yi, x, edge0, x+xDelta, edge1)
				x, yi = x+xDelta, yi+yiDelta
				r.setCell(int(x)/64, yi)
			}
		}
		r.scan(yi, x, edge0, x1, y1f)
	}
	r.a = b
}

func maxAbs26(a, b fix26) fix26 {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	if a < b {
		return b
	}
	return a
}

func (r *rasterizer) add2(b, c rpoint) {
	dev := maxAbs26(r.a.X-2*b.X+c.X, r.a.Y-2*b.Y+c.Y) / fix26(r.splitScale2)
	nsplit := 0
	for dev > 0 {
		dev /= 4
		nsplit++
	}
	const maxNsplit = 16
	if nsplit > maxNsplit {
		nsplit = maxNsplit
	}
	var (
		pStack [2*maxNsplit + 3]rpoint
		sStack [maxNsplit + 1]int
		i      int
	)
	sStack[0] = nsplit
	pStack[0] = c
	pStack[1] = b
	pStack[2] = r.a
	for i >= 0 {
		s := sStack[i]
		p := pStack[2*i:]
		if s > 0 {
			mx := p[1].X
			p[4].X = p[2].X
			p[3].X = (p[4].X + mx) / 2
			p[1].X = (p[0].X + mx) / 2
			p[2].X = (p[1].X + p[3].X) / 2
			my := p[1].Y
			p[4].Y = p[2].Y
			p[3].Y = (p[4].Y + my) / 2
			p[1].Y = (p[0].Y + my) / 2
			p[2].Y = (p[1].Y + p[3].Y) / 2
			sStack[i] = s - 1
			sStack[i+1] = s - 1
			i++
		} else {
			midx := (p[0].X + 2*p[1].X + p[2].X) / 4
			midy := (p[0].Y + 2*p[1].Y + p[2].Y) / 4
			r.add1(rpoint{midx, midy})
			r.add1(p[0])
			i--
		}
	}
}

func (r *rasterizer) areaToAlpha(area int) uint32 {
	a := (area + 1) >> 1
	if a < 0 {
		a = -a
	}
	alpha := uint32(a)
	if r.useNonZeroWinding {
		if alpha > 0x0fff {
			alpha = 0x0fff
		}
	} else {
		alpha &= 0x1fff
		if alpha > 0x1000 {
			alpha = 0x2000 - alpha
		} else if alpha == 0x1000 {
			alpha = 0x0fff
		}
	}
	return alpha<<4 | alpha>>8
}

func (r *rasterizer) paintSpan(m *image.Alpha, y, x0, x1 int, alpha uint32) {
	b := m.Rect
	if y < b.Min.Y || y >= b.Max.Y {
		return
	}
	if x0 < b.Min.X {
		x0 = b.Min.X
	}
	if x1 > b.Max.X {
		x1 = b.Max.X
	}
	if x0 >= x1 {
		return
	}
	base := (y-b.Min.Y)*m.Stride - b.Min.X
	c := uint8(alpha >> 8)
	for i := base + x0; i < base+x1; i++ {
		m.Pix[i] = c
	}
}

func (r *rasterizer) rasterize(m *image.Alpha) {
	r.saveCell()
	for yi := 0; yi < len(r.cellIndex); yi++ {
		xi, cover := 0, 0
		for c := r.cellIndex[yi]; c != -1; c = r.cell[c].next {
			if cover != 0 && r.cell[c].xi > xi {
				alpha := r.areaToAlpha(cover * 64 * 2)
				if alpha != 0 {
					xi0, xi1 := xi, r.cell[c].xi
					if xi0 < 0 {
						xi0 = 0
					}
					if xi1 >= r.width {
						xi1 = r.width
					}
					if xi0 < xi1 {
						r.paintSpan(m, yi, xi0, xi1, alpha)
					}
				}
			}
			cover += r.cell[c].cover
			alpha := r.areaToAlpha(cover*64*2 - r.cell[c].area)
			xi = r.cell[c].xi + 1
			if alpha != 0 {
				xi0, xi1 := r.cell[c].xi, xi
				if xi0 < 0 {
					xi0 = 0
				}
				if xi1 >= r.width {
					xi1 = r.width
				}
				if xi0 < xi1 {
					r.paintSpan(m, yi, xi0, xi1, alpha)
				}
			}
		}
	}
}
