			b[1] = p.Y
		} else if b[3] < p.Y {
			b[3] = p.Y
		}
	}
	return b
}

func (a *ttFace) rasterizeOutline(dotX, dotY fix26, pts []ttPoint, ends []int, bounds [4]fix26) (image.Rectangle, *image.Alpha, bool) {
	dotX = (dotX + 8) & -16
	dotY = (dotY + 32) & -64
	ix, fx := int(dotX>>6), dotX&0x3f
	iy, fy := int(dotY>>6), dotY&0x3f
	xmin := int(fx+bounds[0]) >> 6
	ymin := int(fy-bounds[3]) >> 6
	xmax := int(fx+bounds[2]+0x3f) >> 6
	ymax := int(fy-bounds[1]+0x3f) >> 6
	if xmin > xmax || ymin > ymax {
		return image.Rectangle{}, nil, false
	}
	fx -= fix26(xmin << 6)
	fy -= fix26(ymin << 6)
	mask := image.NewAlpha(image.Rect(0, 0, a.maxw, a.maxh))
	a.r.clear()
	e0 := 0
	for _, e1 := range ends {
		a.drawContour(pts[e0:e1], fx, fy)
		e0 = e1
	}
	a.r.rasterize(mask)
	dr := image.Rect(ix+xmin, iy+ymin, ix+xmin+(xmax-xmin), iy+ymin+(ymax-ymin))
	return dr, mask, true
}

// Braille cells of the default braille font are composites of square dots.
var brailleDotOffsets = [8][2]int{{300, 1300}, {300, 733}, {300, 167}, {900, 1300}, {900, 733}, {900, 167}, {300, -400}, {900, -400}}

const brailleUnitsPerEm = 2048

var brailleFontBounds = [4]fix26{-2090, -948, 3673, 2524}

func brailleScaleFU(x fix26) fix26 {
	if x >= 0 {
		x += brailleUnitsPerEm / 2
	} else {
		x -= brailleUnitsPerEm / 2
	}
	return x / brailleUnitsPerEm
}

func newBrailleFace(size float64) *ttFace {
	a := &ttFace{scale: fix26(0.5 + (size * 72 * 64 / 72))}
	b := [4]fix26{}
	for i := range b {
		b[i] = brailleScaleFU(a.scale * brailleFontBounds[i])
	}
	xmin := +int(b[0]) >> 6
	ymin := -int(b[3]) >> 6
	xmax := +int(b[2]+63) >> 6
	ymax := -int(b[1]-63) >> 6
	a.maxw = xmax - xmin
	a.maxh = ymax - ymin
	a.r.setBounds(a.maxw, a.maxh)
	return a
}

func (a *ttFace) brailleGlyph(dotX, dotY fix26, code int) (image.Rectangle, *image.Alpha, bool) {
	var pts []ttPoint
	var ends []int
	sc := func(v int) fix26 { return brailleScaleFU(a.scale * fix26(v)) }
	for b := 0; b < 8; b++ {
		if code&(1<<uint(b)) == 0 {
			continue
		}
		dx := (sc(brailleDotOffsets[b][0]) + 32) &^ 63
		dy := (sc(brailleDotOffsets[b][1]) + 32) &^ 63
		x0, x1 := sc(0)+dx, sc(300)+dx
		y0, y1 := sc(0)+dy, sc(300)+dy
		pts = append(pts,
			ttPoint{X: x0, Y: y1, Flags: 1},
			ttPoint{X: x1, Y: y1, Flags: 1},
			ttPoint{X: x1, Y: y0, Flags: 1},
			ttPoint{X: x0, Y: y0, Flags: 1})
		ends = append(ends, len(pts))
	}
	if len(pts) == 0 {
		return image.Rectangle{}, nil, false
	}
	return a.rasterizeOutline(dotX, dotY, pts, ends, outlineBounds(pts))
}

